// Rebuild glue: GUI layout and widget input rbxgs declares but never defines (replacing empty stubs).
// Children of a menu bar are laid out in order along its layout style (as TopMenuBar::getSize sums
// them); a relative panel sits on the canvas by its Rect locations plus offset (as
// Rect::positionChild); a widget tracks hover/press and clicks on release over itself.
// Behavioural reconstruction, not byte-verified.
#include "gui/Gui.h"
#include "gui/Widget.h"
#include "gui/Layout.h"
#include "util/Rect.h"

namespace RBX
{
	G3D::Vector2 TopMenuBar::getChildPosition(const GuiItem* child) const
	{
		G3D::Vector2 position = getPosition();
		for (size_t i = 0; i < numChildren(); ++i)
		{
			const GuiItem* current = getGuiItem((int)i);
			if (!current)
				continue;
			if (current == child)
				break;
			G3D::Vector2 size = current->getSize();
			if (layoutStyle == Layout::VERTICAL)
				position.y += size.y;
			else
				position.x += size.x;
		}
		return position;
	}

	G3D::Vector2 RelativePanel::getPosition() const
	{
		// relative panels hang off the GUI root, so they are placed on the whole canvas
		Rect area(GuiRoot::getCanvasSize());
		Rect placed = area.positionChild(Rect(getSize()), xLocation, yLocation);
		return placed.low + G3D::Vector2(offset.x, offset.y);
	}

	// GUI sizes are already in canvas pixels in this build
	G3D::Vector2 GuiRoot::toPixelSize(const G3D::Vector2& size)
	{
		return size;
	}

	bool GuiRoot::askSetParent(const Instance*) const
	{
		return true;
	}

	void GuiItem::label2d(Adorn* adorn, const std::string& text, const G3D::Color4& color, const G3D::Color4& outline, Adorn::XAlign xalign) const
	{
		G3D::Rect2D rect = getMyRect2D();
		float x = xalign == Adorn::XALIGN_LEFT ? rect.x0() + 2.0f : xalign == Adorn::XALIGN_RIGHT ? rect.x1() - 2.0f : rect.center().x;
		adorn->drawFont2D(text, G3D::Vector2(x, rect.center().y), getFontSize(), color, outline, xalign, Adorn::YALIGN_CENTER, Adorn::PROPORTIONAL_SPACING);
	}

	GuiResponse Widget::processMouse(const GuiEvent& event)
	{
		G3D::Vector2 mouse(event.mousePosition.x, event.mousePosition.y);
		bool over = getMyRect2D().contains(mouse);
		switch (event.eventType)
		{
		case UIEvent::MOUSE_MOVE:
			if (widgetState == DOWN_OVER || widgetState == DOWN_AWAY)
			{
				widgetState = over ? DOWN_OVER : DOWN_AWAY;
				onDrag(event);
				return GuiResponse::used(this);
			}
			widgetState = over ? HOVER : NOTHING;
			return over ? GuiResponse::used(this) : GuiResponse::notUsed();
		case UIEvent::MOUSE_LEFT_BUTTON_DOWN:
			if (!over)
				return GuiResponse::notUsed();
			widgetState = DOWN_OVER;
			onDown(event);
			return GuiResponse::used(this);
		case UIEvent::MOUSE_LEFT_BUTTON_UP:
			if (widgetState != DOWN_OVER && widgetState != DOWN_AWAY)
				return GuiResponse::notUsed();
			onUp(event);
			widgetState = over ? HOVER : NOTHING;
			if (over)
				onClick(event);
			return GuiResponse::used();
		default:
			return GuiResponse::notUsed();
		}
	}
}

rebuild/2008-06/glue/rbxgs/glue_guid_reg.base:
// Rebuild glue: instance references over the network. rbxgs serializes an instance as its Guid::Data
// (IdSerializer::serializeId) but has nothing that maps the id back to the instance. The 2008 client
// keeps such a registry (GuidItem<Instance> carries a registeredGuid flag); this is a behavioural
// reconstruction: ids are registered when sent (overlay patch in Streaming.cpp) or received
// (glue_replicator.cpp), held weakly, and looked up when a reference is read. Not byte-verified.
#include <RakPeer.h>  // first, as rbxgs Players.cpp: RakNet needs winsock2 before windows.h
#include <BitStream.h>
#include "Streaming.h"
#include "reflection/property.h"
#include <boost/thread/mutex.hpp>
#include <boost/weak_ptr.hpp>
#include <map>

namespace RBX
{
	namespace Network
	{
		namespace
		{
			boost::mutex& registryMutex()
			{
				static boost::mutex m;
				return m;
			}

			std::map<Guid::Data, boost::weak_ptr<Instance> >& registry()
			{
				static std::map<Guid::Data, boost::weak_ptr<Instance> > r;
				return r;
			}
		}

		void rebuildRegisterGuid(const Instance* instance)
		{
			if (!instance)
				return;
			Guid::Data id;
			instance->getGuid().extract(id);
			boost::mutex::scoped_lock lock(registryMutex());
			registry()[id] = shared_from(const_cast<Instance*>(instance));
		}

		Instance* rebuildFindGuid(const Guid::Data& id)
		{
			boost::mutex::scoped_lock lock(registryMutex());
			std::map<Guid::Data, boost::weak_ptr<Instance> >::iterator iter = registry().find(id);
			if (iter == registry().end())
				return NULL;
			boost::shared_ptr<Instance> instance = iter->second.lock();
			if (!instance)
				registry().erase(iter);
			return instance.get();
		}

		// true when the reference is resolved now (a null reference counts as resolved)
		bool IdSerializer::deserializeInstanceRef(RakNet::BitStream& stream, Instance*& instance, Guid::Data& id)
		{
			deserializeId(stream, id);
			if (*id.scope == Name::getNullName())
			{
				instance = NULL;
				return true;
			}
			instance = rebuildFindGuid(id);
			return instance != NULL;
		}

		bool IdSerializer::deserializeInstanceRef(RakNet::BitStream& stream, Instance*& instance)
		{
			Guid::Data id;
			return deserializeInstanceRef(stream, instance, id);
		}

		// an unknown target waits until that instance arrives (resolvePendingBindings)
		void IdSerializer::deserializeRef(Reflection::Property& property, RakNet::BitStream& stream)
		{
			const Reflection::RefPropertyDescriptor& desc = static_cast<const Reflection::RefPropertyDescriptor&>(property.getDescriptor());
			Instance* target = NULL;
			Guid::Data id;
			if (deserializeInstanceRef(stream, target, id))
			{
				desc.setRefValue(property.getInstance(), target);
				return;
			}
			WaitItem item;
			item.desc = &desc;
			item.instance = shared_from(static_cast<Instance*>(property.getInstance()));
			waitItems[id].push_back(item);
		}
	}
}

