		char text[512];
		_snprintf(text, sizeof(text), "%g, %g, %g, %g, %g, %g, %g, %g, %g, %g, %g, %g",
				  value.translation.x, value.translation.y, value.translation.z,
				  r[0][0], r[0][1], r[0][2], r[1][0], r[1][1], r[1][2], r[2][0], r[2][1], r[2][2]);
		return text;
	}

