        user = need(a.user or s.get("user"), "username", "Use --user or: roc config --user NAME")
        return agent_auto.run(srv, user, a.token or os.environ.get("ROC_AGENT_SERVER_TOKEN") or s.get("token"), a.cli, a.model, a.workers,
