                              server=a.server or s.get("server"), token=a.token or os.environ.get("ROC_AGENT_SERVER_TOKEN") or s.get("token"),
                              user=a.user or s.get("user"), client=a.client or "2008-06")
        if code:
            raise SystemExit(code)
