"""Recipe-driven native discovery. Local proofs are proposals, never native credit."""
import json
import hashlib
import functools
import os
import re
import subprocess
import sys
import time
import threading
import uuid
from collections import Counter, defaultdict, deque
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from types import SimpleNamespace

from roc import fingerprint, integration, libs, match, rebuild, worker, native_search, native_transforms

ROOT = Path(__file__).resolve().parent.parent
FLAGS = "/O2 /Ob2 /Oy /GF /GS- /EHsc /MD"
MODES = tuple(os.environ.get("ROC_NATIVE_MODES", "assertions,fp-fast,assertions-fp-fast").split(","))
# TU-wide pragma families, prepended like fp-fast (each mode name lists its parts, joined by '-').
PRAGMAS = {"fp": "#pragma float_control(precise, off)\n", "osize": '#pragma optimize("s", on)\n',
           "noautoinline": "#pragma auto_inline(off)\n"}
OUTPUT_MARKER = 'out.write_text(json.dumps(patches, indent=1) + "\\n", encoding="utf-8")'


class BaselineAdvanced(ValueError):
    """Saved proposals require fresh proofs against the latest accepted baseline."""


class SavedProposalError(ValueError):
    """One saved candidate cannot be safely rebased; other candidates may proceed."""


def hold_proposals(output, proposals, revision, ticket=None, state='pending', model=None):
    content = (json.dumps(proposals, sort_keys=True, indent=2) + '\n').encode()
    key = hashlib.sha256(content).hexdigest()
    archive = Path(output)/'recovery-proposals'/(key+'.json')
    if not archive.exists():
        archive.parent.mkdir(parents=True, exist_ok=True)
        temporary = archive.with_name(key+'.'+uuid.uuid4().hex+'.tmp')
        temporary.write_bytes(content)
        os.replace(temporary, archive)
    if hashlib.sha256(archive.read_bytes()).hexdigest() != key:
        raise ValueError('Saved recovery archive hash mismatch')
    ticket = Path(ticket) if ticket else Path(output)/'recovery-pending'/(integration.digest([key, model])+'.json')
    integration.atomic_json(ticket, dict(format=1, state=state, proposals=archive.relative_to(output).as_posix(),
        sha256=key, model=model, attempted_revision=revision if state == 'blocked' else None))
    return ticket


def pending_proposals(output, revision):
    output = Path(output).resolve()
    for ticket in sorted((output/'recovery-pending').glob('*.json')):
        record = json.loads(ticket.read_text())
        if record.get('format') != 1 or record.get('state') == 'done' or not record.get('model'):
            continue
        if record.get('state') == 'blocked' and record.get('attempted_revision') == revision:
            continue
        archive = (output/record['proposals']).resolve()
        if not archive.is_relative_to(output/'recovery-proposals'):
            raise ValueError('Saved recovery path escapes its proposal archive')
        if hashlib.sha256(archive.read_bytes()).hexdigest() != record['sha256']:
            raise ValueError('Saved recovery archive hash mismatch')
        integration.atomic_json(ticket, dict(record, state='rechecking', attempted_revision=revision))
        return ticket, archive
    return None, None


def rebase_saved_edits(text, edits):
    kept = []
    for old, new in edits:
        if old and text.count(old) == 1:
            kept.append([old, new])
        elif new and text.count(new) == 1 and (not old or old not in text):
            continue  # Already applied exactly; never fuzzy-match a changed anchor.
        elif old and old not in text and not new:
            continue  # An already absent deletion changes nothing; the new proof is still required.
        elif not old and new not in text:
            kept.append([old, new])
        else:
            raise SavedProposalError('Saved edit anchor changed or became ambiguous')
    return kept


def recheck_proposal(proposal, ctx, texts, output, revision, log, recover=False):
    rel = proposal['file']
    if rel not in texts:
        texts[rel] = (ctx.overlay/rel if (ctx.overlay/rel).exists() else ctx.tree/rel).read_text(errors='replace')
    log('native rechecking ' + rel)
    if not proposal.get('base_revision'):
        raise SavedProposalError('Saved proof is unversioned; run roc native-try check ' + rel)
    if proposal['base_revision'] != revision:
        log('accepted baseline advanced; independently revalidating saved edits: ' + rel)
    options = {'translation_unit':proposal['translation_unit']} if proposal.get('translation_unit') else {}
    baseline = compile_unit(texts[rel], rel, 'recheck-baseline', output, ctx.tree, ctx.overlay,
                            ctx.includes, ctx.defines, ctx.flags, **options)
    if not baseline['ok']:
        raise ValueError('Saved proposal baseline compile failed: ' + rel)
    keep = {h['addr'] for h in ctx.matcher.scan(Path(baseline['object']).read_bytes())}
    wanted = {h['addr'] for h in proposal['witnesses']}
    if recover:
        wanted -= keep | ctx.integrated
        if not wanted:
            log('Saved targets already exact/integrated; no submission needed: ' + rel)
            return None
        proposal['edits'] = rebase_saved_edits(texts[rel], proposal['edits'])
        for name, edits in list(proposal.get('related_headers', {}).items()):
            path = ctx.overlay/name if (ctx.overlay/name).exists() else ctx.tree/name
            proposal['related_headers'][name] = rebase_saved_edits(path.read_text(errors='replace'), edits)
    try:
        source = apply_edits(texts[rel], proposal['edits']) if proposal['edits'] else texts[rel]
    except ValueError as error:
        raise SavedProposalError(str(error)) from error
    final = compile_unit(source, rel, 'recheck-final', output, ctx.tree, ctx.overlay,
                         ctx.includes, ctx.defines, ctx.flags,
                         **dict(options, **({'related_headers':proposal['related_headers']} if proposal.get('related_headers') else {})))
    if not final['ok']:
        raise SavedProposalError('Saved proposal compile failed: ' + rel)
    missing = set(proposal.get('proof', {}).get('defined_symbols', ())).intersection(final.get('undefined_symbols', ()))
    if missing:
        raise SavedProposalError('Saved proposal lost required definitions: ' + ', '.join(sorted(missing)))
    hits = ctx.matcher.scan(Path(final['object']).read_bytes())
    found = {h['addr'] for h in hits}
    if not wanted <= found or keep - found:
        raise SavedProposalError('Saved proposal lost exact matches; rerun roc native-try check ' + rel)
    ownership = ownership_candidates(Path(final['object']).read_bytes(), [h for h in hits if h['addr'] in wanted])
    if not any(candidates == [addr] for addr, candidates in ownership.items()):
        log('no unique module ownership candidates; proposal retained locally: ' + rel)
        return None
    proposal['proof'] = dict(final, hits=hits, losses=[], ownership_candidates=ownership)
    if recover:
        proposal['witnesses'] = [dict(h, claim_unit=claim_unit(h, ctx.by_addr[h['addr']])) for h in hits if h['addr'] in wanted]
    proposal['base_revision'] = revision
    return proposal


def require_private_workspace():
    if (ROOT / "work/server.db").exists():
        raise ValueError("Native finding must use a private contributor checkout; server workspace detected")


def masked_cpp(text):
    """Hide comments and literals without moving any source offsets."""
    pattern = r'//[^\n]*|/\*[\s\S]*?\*/|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\''
    return re.sub(pattern, lambda m: re.sub(r"[^\n\r]", " ", m[0]), text)


def closing(text, start, left, right):
    depth = 0
    for i in range(start, len(text)):
        if text[i] == left:
            depth += 1
        elif text[i] == right:
            depth -= 1
            if not depth:
                return i
    raise ValueError("Unbalanced C++ source")


def methods(text):
    return dict(_method_spans(text))


@functools.lru_cache(maxsize=32)
def _method_spans(text):
    """Unambiguous out-of-line methods, including balanced constructor initializers."""
    clean = masked_cpp(text)
    result = defaultdict(list)
    for found in re.finditer(r"\b(\w+)::(~?\w+)\s*\(", clean):
        end = closing(clean, clean.index("(", found.start()), "(", ")") + 1
        cursor = end
        while cursor < len(clean) and clean[cursor].isspace():
            cursor += 1
        if found[1] == found[2] and clean[cursor:cursor+1] == ':':
            cursor += 1
            while True:
                initializer = re.match(r'\s*[A-Za-z_]\w*(?:::\w+)*\s*', clean[cursor:])
                if not initializer:
                    break
                cursor += initializer.end()
                if clean[cursor:cursor+1] == '<':
                    cursor = closing(clean, cursor, '<', '>') + 1
                    while cursor < len(clean) and clean[cursor].isspace():
                        cursor += 1
                if clean[cursor:cursor+1] != '(':
                    break
                cursor = closing(clean, cursor, '(', ')') + 1
                while cursor < len(clean) and clean[cursor].isspace():
                    cursor += 1
                if clean[cursor:cursor+1] != ',':
                    break
                cursor += 1
            brace = cursor if clean[cursor:cursor+1] == '{' else -1
        else:
            brace = clean.find("{", end)
            if brace >= 0 and not re.fullmatch(r"\s*(?:(?:const|volatile|override|final)\s*)*", clean[end:brace]):
                brace = -1
        if brace < 0:
            continue
        finish = closing(clean, brace, "{", "}") + 1
        if re.search(r"(?m)^\s*#\s*(?:if|elif|else|endif)\b", clean[brace:finish]):
            continue
        token = found[1] + "::" + found[2]
        result[token].append((found.start(), finish))
    return tuple((token, spans[0]) for token, spans in result.items() if len(spans) == 1)


def without_assertions(text):
    """Erase only complete RBXASSERT calls; keep their semicolon/control-flow slot."""
    clean = masked_cpp(text)
    edits = []
    for found in re.finditer(r"\bRBXASSERT\s*\(", clean):
        end = closing(clean, clean.index("(", found.start()), "(", ")") + 1
        if clean[end:].lstrip().startswith(";"):
            edits.append((found.start(), end))
    for start, end in reversed(edits):
        text = text[:start] + re.sub(r"[^\r\n]", " ", text[start:end]) + text[end:]
    return text


def symbol_method(symbol):
    found = re.match(r"^\?([A-Za-z_]\w*)@([A-Za-z_]\w*)@", symbol)
    if found:
        return found[2] + "::" + found[1]
    found = re.match(r"^\?\?0([A-Za-z_]\w*)@", symbol)
    if found:
        return found[1] + "::" + found[1]
    found = re.match(r"^\?\?1([A-Za-z_]\w*)@", symbol)
    return found[1] + "::~" + found[1] if found else None


def variant(text, mode, selected=None):
    edits = []
    spans = methods(text)
    if any(tag in mode for tag in ("assertions", "nonempty", "ternary", "index")):
        for token, (start, end) in spans.items():
            if selected is not None and token not in selected:
                continue
            old = text[start:end]
            new = without_assertions(old) if "assertions" in mode else old
            if "nonempty" in mode:
                pattern = r"!\s*([A-Za-z_]\w*(?:(?:\.|->)[A-Za-z_]\w*)*)(\.|->)empty\s*\(\s*\)"
                for found in reversed(list(re.finditer(pattern, masked_cpp(new)))):
                    new = new[:found.start()] + "(" + found[1] + found[2] + "size() > 0)" + new[found.end():]
            if "ternary" in mode:
                clean = masked_cpp(new)
                for found in reversed(list(re.finditer(r"\bif\s*\(", clean))):
                    start = clean.index("(", found.start())
                    end = closing(clean, start, "(", ")")
                    arms = re.match(r"\s*return\s+([^;{}]+);\s*else\s*return\s+([^;{}]+);", clean[end + 1:])
                    if arms:
                        yes, no = (new[end + 1 + arms.start(i):end + 1 + arms.end(i)].strip() for i in (1, 2))
                        new = new[:found.start()] + "return (%s) ? (%s) : (%s);" % (new[start + 1:end].strip(), yes, no) + new[end + 1 + arms.end():]
            if "index" in mode:
                pattern = r"\bfor\s*\(\s*(std::size_t|size_t|unsigned\s+int|unsigned|int)\s+\w+\s*="
                for found in reversed(list(re.finditer(pattern, masked_cpp(new)))):
                    new = new[:found.start(1)] + ("int" if "index-int" in mode else "size_t") + new[found.end(1):]
            if old != new:
                edits.append([old, new])
    if mode.startswith("runservice-outofline"):
        if not re.search(r"\bcreate\s*<\s*(?:RBX::)?RunService\s*>\s*\(", masked_cpp(text)):
            return text, []
        declaration = "template __declspec(noinline) RunService* ServiceProvider::create<RunService>() const;"
        namespace = re.search(r"\bnamespace\s+RBX\s*\{", masked_cpp(text))
        if not namespace:
            namespace = re.search(r"\busing\s+namespace\s+RBX\s*;", masked_cpp(text))
            before = masked_cpp(text[:namespace.start()]) if namespace else ""
            if not namespace or before.count("{") != before.count("}"):
                raise ValueError("RunService instantiation needs namespace RBX or its global using directive")
            declaration = "template __declspec(noinline) RBX::RunService* RBX::ServiceProvider::create<RBX::RunService>() const;"
        if declaration not in text:
            prefix = text[:namespace.end()]
            edits.insert(0, [prefix, prefix + "\n\t" + declaration + "\n"])
        if mode.endswith("-no-base"):
            for token, (start, end) in spans.items():
                if not token.endswith("::onServiceProvider") or selected is not None and token not in selected:
                    continue
                old = text[start:end]
                parameters = re.search(r"onServiceProvider\s*\(\s*(?:const\s+)?ServiceProvider\s*\*\s*(\w+)\s*,\s*(?:const\s+)?ServiceProvider\s*\*\s*(\w+)", masked_cpp(old))
                if not parameters:
                    continue
                pattern = r"\b(?:[A-Za-z_]\w*::)+onServiceProvider\s*\(\s*%s\s*,\s*%s\s*\)\s*;" % tuple(re.escape(p) for p in parameters.groups())
                new = old
                for found in reversed(list(re.finditer(pattern, masked_cpp(old)))):
                    new = new[:found.start()] + ";" + new[found.end():]
                if old != new:
                    edits.append([old, new])
    for old, new in edits:
        if text.count(old) != 1:
            raise ValueError("Ambiguous method anchor")
        text = text.replace(old, new, 1)
    parts = mode.split("-")
    pragmas = "".join(PRAGMAS[p] for p in ("fp", "osize", "noautoinline")
                      if p in parts and not re.match(r"\s*" + re.escape(PRAGMAS[p].strip()), text))
    if pragmas:
        prefix = re.match(r"(?:\s*\n)*[^\n]+\n", text)
        if prefix is None or text.count(prefix[0]) != 1:
            raise ValueError("Ambiguous TU prelude")
        old = prefix[0]
        new = pragmas + old
        text = text.replace(old, new, 1)
        edits.insert(0, [old, new])
    return text, edits


def proven_proposal(text, mode, hits, baseline):
    """A diagnostic can suggest many edits; promote only newly exact native methods."""
    spans = methods(text)
    counts = Counter(h["symbol"] for h in hits if h["addr"] not in baseline)
    witnesses = [h for h in hits if h["addr"] not in baseline and counts[h["symbol"]] == 1
                 and symbol_method(h["symbol"]) in spans]
    if not witnesses:
        return None
    selected = {symbol_method(h["symbol"]) for h in witnesses}
    final, edits = variant(text, mode, selected)
    return {"source": final, "edits": edits, "witnesses": witnesses, "mode": mode} if edits else None


def claim_unit(hit, row):
    unit = row["unit"]
    from roc.native_adapt import symbol_unit
    if unit.startswith(("G3D::", "Ogre::")) and symbol_unit(hit["symbol"]) == unit:
        return unit
    method = symbol_method(hit["symbol"])
    if method and re.search(r"(?:@|\?\?[01])" + re.escape(method.split("::")[0]) + r"@RBX@@", hit["symbol"]):
        return "RBX::" + method.split("::")[0]
    # Mined factory/RTTI tags can wrap a class name. The compiled native method
    # supplies a real existing class; the scheduling label is not ownership proof.
    return unit if re.fullmatch(r"RBX::(?:\w+::)*\w+", unit) else "RBX::" + method.split("::")[0]


def experiments(text, modes=None):
    seen, result = set(), []
    if modes is not None and (not isinstance(modes, (list, tuple)) or not all(isinstance(m, str) for m in modes)):
        raise ValueError("native modes must be a list of mode names")
    for mode in ("baseline", *(MODES if modes is None else modes)):
        try:
            source = text if mode == "baseline" else variant(text, mode)[0]
            key = hashlib.sha256(source.encode()).hexdigest()
            if key not in seen:
                seen.add(key)
                result.append((mode, source, None))
        except ValueError as error:
            result.append((mode, None, str(error)))
    return result


def grid_discovery(config, texts, targets, matcher, output, jobs, compile_source, names, by_addr, log):
    """Compile and match in separate bounded pools; process results as they finish."""
    from concurrent.futures import wait, FIRST_COMPLETED
    output = Path(output).resolve()
    started = time.monotonic()
    client = config.get('client', '2008-06')
    def module_ownership(data, hits):
        return ownership_candidates(data, hits) if client == '2008-06' else ownership_candidates(data, hits, client)
    journal = native_search.Journal(output)
    def partial_event(row):
        log('native partial %s %s: %.3f%% -> %.3f%% (local search; no exact credit)' % (row['file'], row['addr'], row['previous'], row['score']))
        if config.get('partial_report'):
            config['partial_report'](row)
    partials = native_search.Partials(output, config.get('base_revision'), config.get('partial_floor', 50), on_improvement=partial_event)
    homes = target_files(texts, targets, names, by_addr)
    symbols = {rel: {a: names[a]['symbol'] for a in addrs if names.get(a, {}).get('symbol')}
               for rel, addrs in homes.items()}
    tasks, sources, explicit, deferred, exhausted = [], {}, {}, {}, {}
    for rel, text in texts.items():
        modes = config.get('modes')
        variants = experiments(text, modes)
        selected = {symbol_method(s) for s in symbols.get(rel, {}).values()}
        scoped = config.get('scoped_modes', ['scoped-osize', 'scoped-speed', 'scoped-fp', 'scoped-noautoinline'])
        extra = list(native_search.scoped_variants(text, scoped, selected))
        extra += list(native_search.explicit_variants(text, config.get('rewrite_rules', []), rel))
        extra += list(native_transforms.method_variants(text, selected, config.get('declaration_context', ''),
                     config.get('transform_modes'))) if config.get('automatic_transforms', True) else []
        extra += list(native_transforms.proven_variants(text, config.get('proven_facts', []), rel))
        extra = [(m + '#' + integration.digest(s)[:12], s, e) for m, s, e in extra]
        deferred[rel] = []
        seen = set()
        for mode, source, error in variants + [(m, s, None) for m, s, _ in extra]:
            key = integration.digest(source) if source is not None else mode
            if key in seen:
                continue
            seen.add(key)
            sources[rel, mode] = source
            if mode == 'baseline':
                tasks.append((rel, mode, source, error))
            else:
                deferred[rel].append((mode, source, error))
        explicit.update({(rel, m): edits for m, _, edits in extra})
        if len(seen) == 1:
            tasks = [t for t in tasks if t[0] != rel]
    baseline, diagnostics, buffered, choices = {}, {}, defaultdict(list), defaultdict(list)

    def compile_one(item):
        rel, mode, source, error = item
        if error:
            return dict(file=rel, mode=mode, ok=False, error=error, seconds=0)
        try:
            return compile_source(source, rel, mode)
        except ValueError as failure:
            return dict(file=rel, mode=mode, ok=False, error=str(failure), seconds=0)

    def compare(result):
        tick = time.monotonic()
        data = Path(result['object']).read_bytes() if result['ok'] else None
        result['hits'] = matcher.scan(data) if data is not None else []
        if data is not None and config.get('keep_partials', True):
            result['diagnostics'] = (native_search.diagnose(data, symbols.get(result['file'], {})) if client == '2008-06'
                                     else native_search.diagnose(data, symbols.get(result['file'], {}), client))
        result['match_seconds'] = round(time.monotonic() - tick, 3)
        return result

    def process(result):
        rel, mode = result['file'], result['mode']
        if mode == 'baseline':
            if result['ok']:
                baseline[rel] = {h['addr'] for h in result['hits']}
                diagnostics[rel] = result.get('diagnostics', {})
                if config.get('automatic_transforms', True):
                    context_paths = result.get('compiler_config', {}).get('dependencies', {})
                    context = '\n'.join(Path(p).read_text(errors='replace') for p in context_paths
                        if '/App/include/' in str(p).replace('\\', '/') and Path(p).is_file())
                    selected = {symbol_method(s) for s in symbols.get(rel, {}).values()}
                    generated = list(native_transforms.immediate_variants(texts[rel], diagnostics[rel]))
                    if context:
                        generated += list(native_transforms.method_variants(texts[rel], selected, context, config.get('transform_modes')))
                        generated += list(native_transforms.template_variants(texts[rel], context))
                    known = {integration.digest(s) for (r, _), s in sources.items() if r == rel and s is not None}
                    for label, source, edits in generated:
                        hashed = integration.digest(source)
                        if hashed in known:
                            continue
                        known.add(hashed)
                        label += '#' + hashed[:12]
                        sources[rel, label], explicit[rel, label] = source, edits
                        deferred[rel].append((label, source, None))
                cache_key = integration.digest([result.get('input_signature'), config.get('base_revision'),
                    getattr(matcher, 'identity', None), sorted(targets), deferred[rel],
                    config.get('targeted_recipes', True), config.get('keep_partials', True),
                    hashlib.sha256(Path(native_search.__file__).read_bytes()).hexdigest(),
                    hashlib.sha256(Path(native_transforms.__file__).read_bytes()).hexdigest(),
                    hashlib.sha256(Path(__file__).read_bytes()).hexdigest()])
                cache_path = output / 'exhausted-grid' / (integration.digest(rel) + '.json')
                exhausted[rel] = cache_path, cache_key
                cached = (config.get('search_cache', True) and result.get('input_signature')
                          and not config.get('retry_exhausted') and cache_path.exists()
                          and json.loads(cache_path.read_text()).get('key') == cache_key)
                result['search_cache_hit'] = bool(cached)
                for label, source, error in (() if cached else deferred[rel]):
                    profile, _, method = label.partition(':')
                    method = method.split('#', 1)[0]
                    applicable = [d for d in diagnostics[rel].values() if symbol_method(d.get('symbol', '')) == method]
                    families = {'temporary-inline': 'expression-lifetime', 'temporary-name': 'expression-lifetime',
                                'map-value-entry': 'map-value-type', 'expression-grouping': 'expression-lifetime'}
                    if (config.get('targeted_recipes', True) and (profile.startswith('scoped-') or profile in families or profile == 'scope-lifetime') and applicable
                            and not any(families.get(profile, profile) in d['recipes'] for d in applicable)):
                        continue
                    item = (rel, label, source, error)
                    tasks.append(item)
                    queue.append(item)
        elif rel not in baseline:
            buffered[rel].append(result)
            return
        elif result['ok']:
            lost = baseline[rel] - {h['addr'] for h in result['hits']}
            result['losses'] = sorted(lost)
            partials.retain(rel, texts[rel], sources[rel, mode], result, result.get('diagnostics', {}), diagnostics[rel], lost)
            new_hits = [h for h in result['hits'] if h['addr'] in targets - baseline[rel]]
            if new_hits:
                ownership = module_ownership(Path(result['object']).read_bytes(), new_hits)
                unique = [h for h in new_hits if ownership.get(h['addr']) == [h['addr']]]
                result['ownership_candidates'] = ownership
                if unique:
                    source = sources[rel,mode]
                    covered = {symbol_method(h['symbol']) for h in result['hits']}
                    changed = native_transforms.changed_methods(texts[rel], source)
                    family, _, selected_method = mode.partition(':')
                    selected_method = selected_method.split('#',1)[0]
                    if (((rel,mode) in explicit and changed-covered)
                            or family.startswith('scoped-') and selected_method not in covered
                            or not native_search.visible_callees_ok(source, Path(result['object']).read_bytes(), config.get('proven_facts',[]), rel, client)):
                        result['blocker'] = 'unproven-method-change'
                        journal.add([result])
                        return
                    proposal = (dict(edits=explicit[rel, mode], witnesses=unique, mode=mode)
                                if (rel, mode) in explicit else proven_proposal(texts[rel], mode, unique, baseline[rel]))
                    if proposal:
                        for hit in proposal['witnesses']:
                            hit['claim_unit'] = claim_unit(hit, by_addr[hit['addr']])
                        choices[rel].append(proposal)
        journal.add([result])
        log('native %s %s: %d exact code+data' % (rel, mode, len(result['hits'])))
        integration.atomic_json(output / 'progress.json', dict(phase='discovery', tried=len(journal.records), total=len(tasks), file=rel, mode=mode))
        if mode == 'baseline':
            for pending in buffered.pop(rel, []):
                if rel in baseline:
                    process(pending)
                else:
                    pending['blocker'] = 'baseline-compile'
                    journal.add([pending])

    match_jobs = max(1, min(int(config.get('match_workers', 2)), 64))
    with ThreadPoolExecutor(max_workers=jobs) as compilers, ThreadPoolExecutor(max_workers=match_jobs) as scanners:
        queue = deque(tasks)
        compiling, scanning = set(), set()
        # Bound queued objects and source work. A slow match cannot consume unbounded RAM.
        def refill():
            while len(compiling) + len(scanning) < jobs + match_jobs:
                item = queue.popleft() if queue else None
                if item is None:
                    break
                compiling.add(compilers.submit(compile_one, item))
        refill()
        try:
            while compiling or scanning:
                done, _ = wait(compiling | scanning, return_when=FIRST_COMPLETED)
                for future in done:
                    if future in compiling:
                        compiling.remove(future)
                        scanning.add(scanners.submit(compare, future.result()))
                    else:
                        scanning.remove(future)
                        process(future.result())
                refill()
        finally:
            journal.flush()
    proposals, checks = [], []
    for rel, variants in choices.items():
        def verify(source, wanted):
            result = compare(compile_source(source, rel, 'combined-' + integration.digest(source)[:16]))
            found = {h['addr'] for h in result['hits']}
            lost = baseline[rel] - found
            result['losses'] = sorted(lost)
            checks.append(result)
            if result['ok'] and not lost and wanted <= found:
                owners = module_ownership(Path(result['object']).read_bytes(), [h for h in result['hits'] if h['addr'] in wanted])
                if all(owners.get(a) == [a] for a in wanted):
                    return result
        merged = native_search.merge_choices(texts[rel], variants, verify)
        if merged:
            proposals.append(dict(merged, file=rel))
    if config.get('propagate_siblings', True):
        seen_siblings = set()
        for winner in list(proposals):
            for rel, label, source, edits in native_transforms.sibling_variants(texts, winner, texts[winner['file']]):
                key = rel, integration.digest(source)
                if key in seen_siblings:
                    continue
                seen_siblings.add(key)
                if rel not in baseline:
                    result = compare(compile_source(texts[rel], rel, 'baseline'))
                    journal.add([result])
                    if not result['ok']:
                        continue
                    baseline[rel] = {h['addr'] for h in result['hits']}
                    diagnostics[rel] = result.get('diagnostics', {})
                sources[rel, label], explicit[rel, label] = source, edits
                result = compare(compile_source(source, rel, 'sibling-' + key[1][:16]))
                # compile_source labels carry their hash; process() indexes the original trial name.
                result['mode'] = label
                process(result)
        # Combine propagated and original witnesses using the same complete TU proof.
        for rel, variants in choices.items():
            def sibling_verify(source, wanted):
                result = compare(compile_source(source, rel, 'sibling-final-' + integration.digest(source)[:16]))
                found = {h['addr'] for h in result['hits']}
                result['losses'] = sorted(baseline[rel] - found)
                checks.append(result)
                if result['ok'] and not result['losses'] and wanted <= found:
                    owners = module_ownership(Path(result['object']).read_bytes(), [h for h in result['hits'] if h['addr'] in wanted])
                    if all(owners.get(a) == [a] for a in wanted):
                        return result
            merged = native_search.merge_choices(texts[rel], variants, sibling_verify)
            if merged:
                proposals = [p for p in proposals if p['file'] != rel] + [dict(merged, file=rel)]
    journal.flush()
    for rel, (path, key) in exhausted.items():
        rows = [r for r in journal.records if r['file'] == rel]
        if (not choices[rel] and config.get('search_cache', True) and rows
                and rows[0].get('input_signature') and all(r.get('ok') for r in rows)):
            integration.atomic_json(path, dict(key=key, accepted=False, blocker='exhausted-recipes'))
    integration.atomic_json(output / 'metrics.json', native_search.metrics(journal.records + checks, time.monotonic() - started, proposals))
    integration.atomic_json(output / 'blockers.json', native_search.blocker_queues(journal.records))
    return proposals, journal.records, checks


class Matcher:
    def __init__(self, addresses, cache_dir=None, client='2008-06'):
        self.client = client
        self.target = fingerprint.Target(client)
        self.index = defaultdict(list)
        self.cache, self.cache_lock = {}, threading.Lock()
        self.prefixes = {}
        functions = match._functions(client)
        for addr in sorted(addresses):
            if addr in functions and functions[addr].get("kind", "code") == "code":
                self.index[functions[addr]["size"]].append(addr)
        self.cache_dir = Path(cache_dir) if cache_dir else None
        self.identity = integration.digest([hashlib.sha256(self.target.image).hexdigest(),
                                           self.target.base, getattr(self.target, 'relocs', []), dict(self.index),
                                           hashlib.sha256(Path(match.__file__).read_bytes()).hexdigest(),
                                           hashlib.sha256(Path(fingerprint.__file__).read_bytes()).hexdigest(),
                                           hashlib.sha256(Path(__file__).read_bytes()).hexdigest()]) if cache_dir else None

    def candidates(self, code, relocs):
        """Prune by relocated prefix; same() and data_check() remain authoritative."""
        width = min(8, len(code))
        offsets = tuple(sorted(r for r in relocs if r < width))
        key = (len(code), offsets)
        with self.cache_lock:
            if key not in self.prefixes:
                if len(self.prefixes) >= 256:
                    self.prefixes.pop(next(iter(self.prefixes)))
                prefixes = defaultdict(list)
                for addr in self.index.get(len(code), ()):
                    offset = int(addr, 16) - self.target.base
                    prefix = bytes(self.target.image[offset:offset + width])
                    prefixes[match.masked(prefix, offsets)].append(addr)
                self.prefixes[key] = prefixes
            return self.prefixes[key].get(match.masked(code[:width], offsets), ())

    def scan(self, obj):
        key = hashlib.sha256(obj).digest()
        cached = self.cache.get(key)
        if cached is not None:
            return [dict(hit) for hit in cached]
        disk = self.cache_dir / self.identity / (key.hex() + '.json') if self.cache_dir else None
        if disk and disk.exists():
            saved = json.loads(disk.read_text())
            if saved.get('object_sha256') == key.hex() and saved.get('identity') == self.identity:
                return saved['hits']
        found, data_index = {}, None
        for symbol, code, relocs in match.coff_functions(obj):
            if len(code) < 6:
                continue
            refs = None
            for addr in self.candidates(code, relocs):
                if addr in found:
                    continue
                exe = self.target.same(addr, code, relocs)
                if exe is None:
                    continue
                # Shared tiny bodies can hit many addresses. Parse this symbol's
                # COFF data once, while checking each target's referenced bytes.
                if refs is None:
                    if data_index is None:
                        data_index = match._coff_data_index(obj)
                    refs = match.coff_data_refs(obj, symbol, index=data_index)
                _, bad = match.data_check(self.client, addr, exe, refs)
                if not bad:
                    found[addr] = symbol
        hits = [{"addr": addr, "symbol": found[addr]} for addr in sorted(found)]
        with self.cache_lock:
            if len(self.cache) >= 128:
                self.cache.pop(next(iter(self.cache)))
            self.cache[key] = [dict(hit) for hit in hits]
        if disk:
            integration.atomic_json(disk, dict(identity=self.identity, object_sha256=key.hex(), hits=hits))
        return hits


def ownership_candidates(obj, hits, client='2008-06'):
    """Use the server's whole-binary pairing, not the discovery target subset."""
    if not hits:
        return {}
    symbols = {h["symbol"] for h in hits}
    candidates = {symbol: addrs for symbol, _, addrs in rebuild.pair_object(client, obj, symbols)}
    return {h["addr"]: candidates.get(h["symbol"], []) for h in hits}


def compile_unit(source, rel, label, output, tree, overlay, includes, defines, flags, translation_unit=None, related_headers=None):
    output = Path(output).resolve()
    if related_headers:
        previous, hashes = {}, {}
        try:
            for name, edits in related_headers.items():
                header = (overlay / name).resolve()
                if not header.is_relative_to(overlay.resolve()) or header.suffix.lower() not in (".h", ".hpp", ".inl"):
                    raise ValueError("Paired edits must be headers inside the private overlay")
                if header not in previous:
                    previous[header] = header.read_bytes() if header.exists() else None
                original = header if header.exists() else tree / name
                if not edits:
                    continue
                changed = apply_edits(original.read_text(errors="replace"), edits)
                header.parent.mkdir(parents=True, exist_ok=True)
                header.write_text(changed, encoding="utf-8")
                hashes[name] = hashlib.sha256(changed.encode()).hexdigest()
            result = compile_unit(source, rel, label, output, tree, overlay, includes, defines, flags,
                                  translation_unit=translation_unit)
            result["related_header_sha256"] = hashes
            return result
        finally:
            for header, original in previous.items():
                if original is None:
                    header.unlink(missing_ok=True)
                else:
                    header.write_bytes(original)
    if translation_unit:
        # Trial the genuine header in the private overlay, then compile its real caller.
        # Restoring in finally keeps failed trials and later baselines independent.
        header = (overlay / rel).resolve()
        if not header.is_relative_to(overlay.resolve()):
            raise ValueError("Header trial must stay inside the private overlay")
        previous = header.read_bytes() if header.exists() else None
        header.parent.mkdir(parents=True, exist_ok=True)
        try:
            header.write_text(source, encoding="utf-8")
            caller = overlay / translation_unit
            if not caller.exists():
                caller = tree / translation_unit
            result = compile_unit(caller.read_text(errors="replace"), translation_unit, label + "-header-" +
                                  integration.digest(rel)[:8], output, tree, overlay, includes, defines, flags)
            result.update(file=rel, translation_unit=translation_unit,
                          header_sha256=hashlib.sha256(source.encode()).hexdigest())
            return result
        finally:
            if previous is None:
                header.unlink(missing_ok=True)
            else:
                header.write_bytes(previous)
    folder = output / "objects" / integration.digest([rel, label])[:20]
    folder.mkdir(parents=True, exist_ok=True)
    unit = folder / Path(rel).name
    if not unit.exists() or unit.read_text(encoding="utf-8") != source:
        unit.write_text(source, encoding="utf-8")
    siblings = [overlay / Path(rel).parent, tree / Path(rel).parent]
    started = time.monotonic()
    result = rebuild.compile_direct("2008-06", [unit], folder, siblings + includes, defines, flags)
    ok, message = result[str(unit)]
    logs = output / "logs"
    logs.mkdir(exist_ok=True)
    (logs / (folder.name + ".log")).write_text(message, encoding="utf-8")
    obj = unit.with_suffix(".obj")
    externals = rebuild.coff_externals(obj.read_bytes()) if ok else {}
    return {"file": rel, "mode": label, "ok": ok, "seconds": round(time.monotonic() - started, 3),
            "object": str(obj), "source_sha256": hashlib.sha256(source.encode()).hexdigest(),
            "object_sha256": hashlib.sha256(obj.read_bytes()).hexdigest() if ok else None,
            "defined_symbols": sorted(name for name, defined in externals.items() if defined),
            "undefined_symbols": sorted(name for name, defined in externals.items() if not defined),
            "compile_cache_hit": ok and message == 'content cache hit',
            "input_signature": json.loads(obj.with_suffix('.compile.json').read_text()).get('inputs')
                               if ok and obj.with_suffix('.compile.json').exists() else None,
            "compiler_config": json.loads(obj.with_suffix('.command.json').read_text())
                               if obj.with_suffix('.command.json').exists() else dict(client='2008-06', flags=flags, defines=defines, includes=[str(p) for p in siblings + includes]),
            "error": message if not ok else None}


def linked_preflight_progress(root, additions, output, log, interval=30):
    """Keep long independent builds visible without changing verifier inputs/gates."""
    from roc.integration_verify import linked_preflight
    stopped = threading.Event()
    phase = (time.monotonic(), 'Linked preflight: preparing')
    def report(message):
        nonlocal phase
        phase = (time.monotonic(), str(message))
        integration.atomic_json(Path(output)/'progress.json', dict(phase='linked-preflight', message=str(message)))
        log(message)
    def heartbeat():
        while not stopped.wait(interval):
            started, message = phase
            elapsed = time.monotonic() - started
            if elapsed >= interval:
                log('%s · still running (%ds)' % (message, elapsed))
    thread = threading.Thread(target=heartbeat, name='roc-preflight-progress', daemon=True)
    thread.start()
    try:
        return linked_preflight(root, additions, output, report)
    finally:
        stopped.set()
        thread.join()


def foreign_claims(user, identity):
    """Classes with a live claim (claimed/submitted/parked) by any other worker, from the host server DB."""
    import sqlite3
    path = Path(os.environ.get("ROC_NATIVE_EVIDENCE_ROOT", ROOT)) / "work/server.db"
    if not path.exists():
        return set()  # contributor PC without the server DB: the server's claim checks still apply
    db = sqlite3.connect("file:%s?mode=ro" % path.as_posix(), uri=True, timeout=30)
    try:
        return {unit for unit, worker in db.execute("SELECT unit,worker FROM integration_claims WHERE expires>? "
                                                      "AND (state IN ('claimed','submitted') OR state LIKE 'parked:%')",
                                                    (time.time(),)) if not worker.endswith(identity)}
    finally:
        db.close()


def stage_generator(generator, original, additions):
    require_private_workspace()
    if generator.read_bytes() != original:
        raise ValueError("Generator changed during discovery; proposals saved, edits not applied")
    text = original.decode("utf-8")
    if text.count(OUTPUT_MARKER) != 1:
        raise ValueError("Generator output anchor is ambiguous")
    integration.validate_patches(additions)
    block = ("# Native sweep: method-scoped corrections passed exact code/data preflight.\n"
             "import sys\n"
             "sys.path.insert(0, str(Path(__file__).resolve().parents[3]))\n"
             "from roc.integration import merge_patches\n"
             "patches = merge_patches(patches, json.loads(%r))\n\n") % json.dumps(additions, sort_keys=True)
    generator.write_bytes(text.replace(OUTPUT_MARKER, block + OUTPUT_MARKER).encode("utf-8"))


def restore_submitted_baseline(identifier, log=print):
    """Durable submitted snapshots let discovery continue against the unchanged accepted baseline."""
    folder = ROOT / "work/integration-client/jobs" / identifier
    snapshot, base = folder / "submitted-generator.py", folder / "generator-base.py"
    if not snapshot.exists() or not base.exists():
        return
    generator = ROOT / "rebuild/2008-06/patches/make_rbxgs_client.py"
    current = generator.read_bytes()
    if current == base.read_bytes():
        return
    if current != snapshot.read_bytes():
        return log("generator changed after submission; preserved local edits")
    generator.write_bytes(base.read_bytes())
    integration.run_generator(generator, ROOT)
    log("submitted snapshot retained; local baseline restored for next discovery")


def wait_for_job(api, identifier, timeout, log):
    started = time.monotonic()
    deadline, previous = started + timeout, None
    while time.monotonic() < deadline:
        jobs = api.call("/v1/integration?id=" + identifier)["jobs"]
        if not jobs:
            raise ValueError("Native job missing: " + identifier)
        job = jobs[0]
        phase = (job["state"], job["phase"])
        if phase != previous:
            log("native job %s: %s / %s" % (identifier, *phase))
            previous = phase
        if job["state"] in ("accepted", "rejected"):
            job['verification_wait_seconds'] = round(time.monotonic() - started, 3)
            return job
        time.sleep(5)
    raise TimeoutError("Native verification still pending: " + identifier)


MODEL_RULES = """You repair real 2008 Roblox C++ so MSVC compiles it to the exact bytes of the 2008 exe.
Edit ONLY the file below. Reply with one or more blocks inside one ```cpp fence, nothing else:
<<<<<<< SEARCH
exact old text, copied verbatim from the file
\x3d======
new text
\x3e>>>>>> REPLACE
Each SEARCH text must occur exactly once in the file as shown. Blocks apply in order.
Prefer one target and 1-3 small blocks. Include enough unchanged method context to make every anchor unique.
The mined sources are byte-exact proofs written with placeholder types: copy their control flow, call order,
constants and evaluation order, but use the real classes, members and methods. "standins" maps each placeholder
to the real symbol, RTTI type or import the exe uses at that spot. Never add padding structs, offset views,
invented fields, inline asm or casts to raw offsets. Keep every other method unchanged."""


def strip_asm(source):
    return "\n".join(line for line in source.splitlines() if not re.match(r"//\s*[0-9a-f]{8}\s", line))


def target_files(texts, wanted, names, by_addr):
    """{file: [addr]}: a target goes to the file defining its rebuilt method. Only a target without a rebuilt
    method falls back to the file named for its class; a rebuilt method no file defines (declared, body elsewhere
    or absent) cannot be fixed here and is skipped."""
    spans = {rel: methods(text) for rel, text in texts.items()}
    stems = defaultdict(list)
    for rel in texts:
        stems[Path(rel).stem.lower()].append(rel)
    out = defaultdict(list)
    for addr in sorted(wanted):
        symbol = names.get(addr, {}).get("symbol")
        method = symbol_method(symbol) if symbol else None
        homes = [rel for rel in texts if method and method in spans[rel]]
        if not homes and method and method.split("::")[0] == method.split("::")[1]:
            homes = [rel for rel, text in texts.items() if re.search(r"\b" + re.escape(method) + r"\s*\(", masked_cpp(text))]
        if not homes and not symbol:
            homes = stems.get(by_addr.get(addr, {}).get("unit", "").rsplit("::", 1)[-1].lower(), [])
        if len(homes) == 1:
            out[homes[0]].append(addr)
    return out


def model_evidence(addr, names, by_addr):
    from roc import packet, standins
    source, origin, _ = packet._source("2008-06", addr)
    if not source:
        settings = worker.load_settings()
        if not settings.get("server"):
            raise ValueError("Mined source missing; configure the group server or run roc pull 2008-06")
        api = worker.Api(settings["server"], integration.native_token() or settings.get("native_token") or settings.get("token"))
        try:
            source, origin, _ = packet._source("2008-06", addr, api)
        finally:
            api.close()
        if not source:
            raise ValueError("No mined source available for " + addr + "; check the group server or run roc pull 2008-06")
    code = match.target("2008-06", addr)[0]
    rebuilt = names.get(addr) or {}
    displayed = strip_asm(source)
    reference = match.directives(source).get("lib", "")
    recipe, _, rel = reference.partition(" ")
    definition = libs.RECIPES.get(recipe, {})
    expanded = False
    if definition.get("src") and not definition.get("generate") and Path(rel.strip()).name.startswith("roc_"):
        try:
            folder = libs._case_path(libs.LIBS / definition["src"]).resolve()
            proof = (folder / rel.strip().replace("\\", "/")).resolve()
            if proof.is_relative_to(folder) and proof.is_file():
                displayed += "\n" + strip_asm(proof.read_text(errors="replace"))
                expanded = True
        except OSError:
            pass  # Optional local proof; the compiled library reference remains available.
    assembly = match.disasm(code, int(addr, 16))
    # native_score: how close the rebuild's own method compiles today (the mined source is always 100%)
    evidence_dir = ROOT/'work/native-evidence'/addr
    evidence_dir.mkdir(parents=True, exist_ok=True)
    for path, full in ((evidence_dir/'mined.cpp', source), (evidence_dir/'target.asm', '\n'.join(assembly))):
        if not path.exists() or path.read_text(encoding='utf-8') != full:
            path.write_text(full, encoding='utf-8')
    item = {"addr": addr, "mined_source_file": str((evidence_dir/'mined.cpp').resolve()),
            "target_asm_file": str((evidence_dir/'target.asm').resolve()), "size": by_addr.get(addr, {}).get("size"), "rebuilt_symbol": rebuilt.get("symbol"),
            "native_score": rebuilt.get("score"), "mined_source": displayed[:4000],
            "mined_source_origin": origin, "target_asm": assembly[:120]}
    if len(assembly) > 120:
        item["target_asm_truncated"] = {"shown": 120, "total": len(assembly)}
    if reference:
        item.update(mined_source_reference=reference, mined_source_expanded=expanded)
    calls = list(dict.fromkeys(m[1].lower().zfill(8) for line in assembly
                               if (m := re.search(r"\b(?:call|jmp) 0x([0-9a-fA-F]+)\s*$", line))
                               and not int(addr, 16) <= int(m[1], 16) < int(addr, 16) + len(code)))
    item["target_calls"] = [{"addr": a, "native_symbol_hint": names.get(a, {}).get("symbol"),
                             "native_score": names.get(a, {}).get("score"),
                             "inventory_unit_hint": by_addr.get(a, {}).get("unit")} for a in calls]
    try:
        item["standins"] = standins.mapping("2008-06", addr, source)
    except Exception as error:  # noqa: BLE001 - the map is optional evidence
        item["standins_error"] = str(error)[:200]
    return item


def body_diff(obj, symbol, addr, limit=40):
    """Show relocated operands as symbols, retaining genuine constants and pointer indirection."""
    import difflib
    function = {name: (body, relocs) for name, body, relocs in match.coff_functions(obj)}.get(symbol)
    if function is None:
        return "rebuilt symbol %s is not in this object" % symbol
    code, relocs = function
    target, target_relocs, _ = match.target("2008-06", addr)
    decoder = match.Cs(match.CS_ARCH_X86, match.CS_MODE_32)
    decoder.detail = True

    def memory_symbol(found):
        expression = found[1]
        if re.fullmatch(r"(?:0x[0-9a-f]+|\d+)", expression):
            return "[sym]"
        expression, count = re.subn(r"\s*[+-]\s*(?:0x[0-9a-f]+|\d+)$", " + sym", expression)
        return "[" + expression + ("" if count else " + sym") + "]"

    def norm(body, relocations):
        lines, relocations = [], set(relocations)
        for instruction in decoder.disasm(body, 0):
            mnemonic, operand = instruction.mnemonic, instruction.op_str
            if instruction.disp_offset and instruction.address + instruction.disp_offset in relocations:
                operand = re.sub(r"\[([^\]]+)\]", memory_symbol, operand)
            if instruction.imm_offset and instruction.address + instruction.imm_offset in relocations:
                operand = re.sub(r"(?:^|(?<=, ))-?(?:0x[0-9a-f]+|\d+)$", "sym", operand)
            elif re.fullmatch(r"0x[0-9a-f]+|\d+", operand):
                if mnemonic == "call" or mnemonic == "jmp" and not 0 <= int(operand, 0) < len(body):
                    operand = "sym"
                elif mnemonic.startswith("j"):
                    operand = "X"
            lines.append(mnemonic + " " + operand)
        return lines
    lines = list(difflib.unified_diff(norm(target, target_relocs), norm(code, relocs),
                                      "target", "rebuilt", n=1, lineterm=""))
    return "\n".join(lines[:limit]) + ("\n..." if len(lines) > limit else "") if lines else "identical after masking"


def excerpt(text, symbols, around=20):
    """The file's #include lines plus each target method with `around` lines of context, verbatim, so SEARCH
    blocks still anchor in the full file. Falls back to the whole file when no target method is found."""
    spans, lines = methods(text), text.split("\n")
    starts = [0]
    for line in lines:
        starts.append(starts[-1] + len(line) + 1)

    def line_of(offset):
        return max(0, next(i for i, start in enumerate(starts) if start > offset) - 1)
    keep = {i for i, line in enumerate(lines) if line.lstrip().startswith("#include")}
    found = False
    for symbol in symbols:
        span = spans.get(symbol_method(symbol))
        if span:
            found = True
            keep.update(range(max(0, line_of(span[0]) - around), min(len(lines), line_of(span[1]) + around + 1)))
    if not found:
        return text
    out, last = [], -1
    for i in sorted(keep):
        if i != last + 1:
            out.append("// ...")
        out.append(lines[i])
        last = i
    return "\n".join(out)


def apply_edits(text, edits):
    if not isinstance(edits, list) or not edits:
        raise ValueError("no edits")
    for pair in edits:
        if not (isinstance(pair, list) and len(pair) == 2 and all(isinstance(p, str) for p in pair)) or not pair[0]:
            raise ValueError("each edit must be [old, new] strings with non-empty old")
        if text.count(pair[0]) != 1:
            raise ValueError("old text occurs %d times, need exactly 1: %r" % (text.count(pair[0]), pair[0][:80]))
        text = text.replace(pair[0], pair[1], 1)
    return text


EDIT_BLOCK = re.compile(r"<{7} SEARCH\n(.*?)\n={7}\n(.*?)\n?>{7} REPLACE", re.S)


def parse_edits(reply):
    """SEARCH/REPLACE blocks: C++ needs no escaping, unlike JSON strings (most JSON replies failed to parse)."""
    edits = [[old, new] for old, new in EDIT_BLOCK.findall(providers_text(reply).replace("\r\n", "\n"))]
    if not edits:
        raise ValueError("reply has no SEARCH/REPLACE block")
    return edits


def providers_text(reply):
    from roc import providers
    return providers.strip_reasoning(reply.text if hasattr(reply, "text") else str(reply))


def model_prompt(rel, shown, items):
    return ("%s\n\nFILE %s\n```cpp\n%s\n```\n\nTARGETS (exact 2008 functions this file should produce)\n%s"
            "\n\nReturn SEARCH/REPLACE blocks inside one ```cpp fence. Do not return the whole source file.") % (
        MODEL_RULES, rel, shown[:60000], json.dumps(items, separators=(",", ":")))


def method_prompt(rel, text, selected, method):
    return ("Repair ONLY %s in %s for the genuine VS2008 compiler. Return its complete qualified method "
            "definition in one ```cpp fence. Keep the signature unchanged. No SEARCH/REPLACE, extra methods, "
            "invented types/fields, raw offsets, assembly or prose. Use standins mappings to translate mined "
            "placeholders to real symbols. Match the target code AND data.\n\n"
            "CONTEXT\n```cpp\n%s\n```\nTARGET\n%s") % (
                method, rel, excerpt(text, [selected['rebuilt_symbol']], around=6)[:60000],
                json.dumps(selected, separators=(',', ':')))


def method_edits(text, reply, method):
    """Accept one complete method, retain its original declaration, and edit only its body."""
    code = providers_text(reply).strip()
    fenced = re.fullmatch(r"```(?:cpp|c\+\+)?\s*\n(.*?)\n```", code, re.S)
    if fenced:
        code = fenced[1]
    original, returned = methods(text), methods(code)
    if method not in original or set(returned) != {method}:
        raise ValueError("reply must contain only the unambiguous method " + method)
    start, end = original[method]
    new_start, new_end = returned[method]
    old_clean, new_clean = masked_cpp(text), masked_cpp(code)
    brace, new_brace = old_clean.index("{", start), new_clean.index("{", new_start)
    if re.sub(r"\s+", "", old_clean[start:brace]) != re.sub(r"\s+", "", new_clean[new_start:new_brace]):
        raise ValueError("method signature must stay unchanged")
    if not re.fullmatch(r"[\w\s:<>,*&~]*", new_clean[:new_start]) or new_clean[new_end:].strip() not in ("", ";"):
        raise ValueError("reply contains extra code outside the requested method")
    return [[text[start:end], text[start:brace] + code[new_brace:new_end]]]


def minimize(rel, text, edits, new, keep, compile_round, matcher, label, allow_empty=False, definitions=(), verified=None):
    """Only the edits the new exacts need, re-proved by a final compile; None if that proof fails. Models rewrite
    neighbouring methods too, and an unproven behaviour change in a method that was not exact would pass the
    loss check. keep: exacts this file already produced, which must survive."""
    edits = [pair for pair in edits if pair[0] != pair[1]]
    for pair in list(edits):
        rest = [other for other in edits if other is not pair]
        if not rest and not allow_empty:
            continue
        trial = compile_round(apply_edits(text, rest) if rest else text, "minimize-%s-%d" % (label, len(rest)))
        found = {h["addr"] for h in matcher.scan(Path(trial["object"]).read_bytes())} if trial["ok"] else set()
        if new <= found and not keep - found and not set(definitions).intersection(trial.get("undefined_symbols", ())):
            edits = rest
            verified = trial
    result = verified or compile_round(apply_edits(text, edits) if edits else text, "final-%s" % label)
    hits = matcher.scan(Path(result["object"]).read_bytes()) if result["ok"] else []
    found = {h["addr"] for h in hits}
    if not (new <= found and not keep - found) or set(definitions).intersection(result.get("undefined_symbols", ())):
        return None
    result.update(hits=hits, losses=[])
    return {"file": rel, "edits": edits, "mode": "model", "witnesses": [h for h in hits if h["addr"] in new],
            "proof": result}


def model_proposal(rel, text, addrs, baseline, owned, model, rounds, compile_round, matcher, evidence, log, options=None,
                   diff=None, shown=None):
    """Ask the model for anchored edits to one native file; keep the first that makes a new target exact and
    loses no owned exact in that file. Every round compiles the real TU; failures go back as feedback."""
    from roc import providers
    addrs = [addr for addr in addrs if addr not in baseline]
    if not addrs:
        return None, []
    generation = (options or {}).get("generation", "edits")
    if generation not in ("auto", "edits", "method"):
        raise ValueError("Unknown native generation mode: " + str(generation))
    spans = methods(text)
    items, selected = [], None
    for addr in addrs[:3]:
        item = evidence(addr)
        items.append(item)
        span = spans.get(symbol_method(item.get("rebuilt_symbol") or ""))
        if generation != "edits" and span and span[1] - span[0] <= 6000:
            selected = item
            break
    method = symbol_method(selected["rebuilt_symbol"]) if selected else None
    one_shot = generation != "edits" and method is not None
    prompt = model_prompt(rel, shown or text, items)
    if one_shot:
        prompt = method_prompt(rel, text, selected, method)
    if (options or {}).get('initial_feedback'):
        prompt += '\n\nPrevious worker batch diagnostics:\n' + options['initial_feedback'][-4000:]
    messages, trials = [{"role": "system", "content": "Repair native C++; return only the requested output inside one ```cpp fence. No tools or prose."},
                        {"role": "user", "content": prompt}], []
    seen_candidates, best_partial = set(), None
    for n in range(rounds):
        # Edit blocks are short: no thinking and a small reply cap keep each round to seconds, not a minute.
        # With thinking on, reasoning shares max_tokens: an 8192 cap left 27 of 29 replies without any edit.
        settings = dict({"allow_cloud": True, "timeout": 180, "thinking": "disabled"}, **(options or {}))
        response_mode = "method" if one_shot and (n == 0 or generation == "method") else "edits"
        settings["edit_blocks"] = response_mode == "edits"
        if settings.get("before_request") and not settings["before_request"]():
            return None, trials
        settings.setdefault("max_tokens", 3072 if settings["thinking"] == "disabled" else 32768)
        log("Requesting %s · %s · round %d/%d" % (model, rel, n + 1, rounds))
        from roc.integration_policy import model_for_attempt, usage
        active_model = model_for_attempt(model, settings, n)
        request = dict(file=rel, mode='model-request', model=active_model,
                       target_addresses=[selected['addr']] if selected and selected.get('addr') else
                       [item.get('addr', addr) for item, addr in zip(items, addrs)])
        if settings.get('attempt_allowed') and not settings['attempt_allowed'](request['target_addresses']):
            return None, trials
        trials.append(request)
        try:
            reply = providers.generate(active_model, messages, settings)
            request.update(usage(reply, active_model))
            if settings.get('record_attempt'):
                settings['record_attempt']([request])
        except Exception as error:
            trials.append(dict(file=rel, mode='model-error', ok=False, error=str(error)[:500],
                               error_category=getattr(error, 'category', '')))
            return None, trials
        log("Round %d/%d · AI %.1fs · %d in / %d out tokens" % (n + 1, rounds, getattr(reply, "latency_s", 0) or 0,
                                                              getattr(reply, "input_tokens", 0), getattr(reply, "output_tokens", 0)))
        messages.append({"role": "assistant", "content": providers_text(reply)})
        try:
            if response_mode == 'method':
                edits = method_edits(text, reply, method)
            else:
                try:
                    edits = parse_edits(reply)
                except ValueError:
                    if generation != 'auto' or not method:
                        raise
                    edits = method_edits(text, reply, method)
                    response_mode = 'method-fallback'
            edits = [pair for pair in edits if pair[0] != pair[1]]
            if not edits:
                raise ValueError("Reply made no source change; target is still not exact")
            integration.validate_patches({rel: edits})
            candidate = apply_edits(text, edits)
            fingerprint = integration.digest(candidate)
            if fingerprint in seen_candidates:
                raise ValueError("Repeated failed candidate; choose a different correction")
            seen_candidates.add(fingerprint)
            result = compile_round(candidate, "model-" + fingerprint[:16])
            log("Round %d/%d · compile %.1fs · queue %.1fs" %
                (n + 1, rounds, result.get("seconds", 0), result.get("queue_seconds", 0)))
        except ValueError as error:
            trials.append({"file": rel, "mode": "model-%d" % n, "generation": response_mode, "ok": False, "error": str(error)[:500],
                           "reply": providers_text(reply)[:3000]})
            instruction = ("Return only the complete corrected method in one cpp fence." if generation == "method" and method else
                           "Return SEARCH/REPLACE blocks in one cpp fence: <<<<<<< SEARCH, exact original text, =======, new text, >>>>>>> REPLACE.")
            messages.append({"role": "user", "content": "Rejected: %s\n%s" % (error, instruction)})
            continue
        hits = matcher.scan(Path(result["object"]).read_bytes()) if result["ok"] else []
        found = {h["addr"] for h in hits}
        new, lost = (found & set(addrs)) - baseline, baseline - found if result['ok'] else set()
        result.update(hits=hits, losses=sorted(lost), comparison_complete=bool(result['ok']),
                      reply=providers_text(reply)[:3000], generation=response_mode,
                      generation_seconds=getattr(reply, "latency_s", None),
                      input_tokens=getattr(reply, "input_tokens", None), output_tokens=getattr(reply, "output_tokens", None))
        trials.append(result)
        if settings.get('record_attempt'):
            settings['record_attempt']([result])
        if result['ok'] and not lost and result.get('diagnostics'):
            strength = sum(d['score'] for d in result['diagnostics'].values())
            if best_partial is None or strength > best_partial[0]:
                best_partial = strength, edits, result['diagnostics']
        if result['ok']:
            log("model %s round %d: %d new exact, %d lost" % (rel, n, len(new), len(lost)))
        else:
            log("model %s round %d: compile failed; no match comparison" % (rel, n))
        if new and not lost:
            proposal = minimize(rel, text, edits, new, baseline, compile_round, matcher, "%d" % n,
                                definitions=result.get("defined_symbols", ()), verified=result)
            if not proposal:
                trials.append(dict(result, error="minimized edits lost the proof"))
            if proposal:
                proposal['models'] = [active_model]
            return proposal, trials
        feedback = result["error"][-1500:] if not result["ok"] else \
            "Compiled. Newly exact: %s. Still not exact: %s. Lost previously exact: %s." % (
                sorted(new) or "none", sorted(set(addrs) - found) or "none", (str(sorted(lost)[:12]) + (" (%d total)" % len(lost) if len(lost) > 12 else "")) if lost else "none")
        if result["ok"] and diff:
            data = Path(result["object"]).read_bytes()
            feedback += "".join("\n\n%s target vs your rebuilt code:\n%s" % (a, diff(data, a))
                                for a in sorted(set(addrs) - found)[:2])
        if best_partial:
            feedback += '\nBest no-loss partial so far (search hint, not exact):\n' + json.dumps(
                dict(edits=best_partial[1], diagnostics=best_partial[2]), separators=(',', ':'))[:12000]
        instruction = ("Return the complete corrected method in one cpp fence." if generation == "method" and method else
                       "Return the complete corrected set of SEARCH/REPLACE blocks against the ORIGINAL file in one cpp fence. "
                       "Use <<<<<<< SEARCH, exact original text, =======, new text, >>>>>>> REPLACE delimiters.")
        messages.append({"role": "user", "content": feedback + "\n" + instruction})
    return None, trials


def resolve_compile_workers(value, jobs):
    count = min(jobs, 8, max(1, (os.cpu_count() or 2) // 2)) if value == "auto" else int(value)
    if not 1 <= count <= 64:
        raise ValueError("Native compiler count must be auto or 1-64")
    return count


def model_discovery(config, texts, wanted, owned, by_addr, matcher, output, jobs, log, compile_source, names):
    """Near-exact targets first; smaller files break ties to reach the first result sooner."""
    from roc import providers
    output = Path(output)
    journal = native_search.Journal(output)
    search_started = time.monotonic()
    local_slot = threading.local()
    def partial_event(row):
        if event:
            event('native_partial', slot=local_slot.slot, **row)
        else:
            log('native partial %s %s: %.3f%% -> %.3f%% (local search; no exact credit)' % (row['file'], row['addr'], row['previous'], row['score']))
        if config.get('partial_report'):
            config['partial_report'](row)
    partials = native_search.Partials(output, config.get('base_revision'), config.get('partial_floor', 50), on_improvement=partial_event) if config.get('keep_partials') else None
    if config.get("only_rebuilt", True):
        # Near misses first: the rebuild already compiles a body for the address, so the fix is local to that method.
        # Targets with no rebuilt body need new methods and header declarations; .cpp-only edits rarely reach them.
        wanted = {addr for addr in wanted if names.get(addr, {}).get("symbol")}
    homes = target_files(texts, wanted, names, by_addr)
    skip = set(config.get("exclude_files", []))
    homes = {rel: sorted(addrs, key=lambda a: (-(names.get(a, {}).get("score") or 0), by_addr.get(a, {}).get("size", 0))) for rel, addrs in homes.items()}
    from roc.integration_context import rank
    selection = config.get('selection', 'balanced')
    if selection not in ('easy', 'balanced', 'large'):
        raise ValueError('Invalid native selection')
    ranked = sorted(homes, key=lambda rel: (rank(
        [dict(by_addr.get(a, {}), addr=a) for a in homes[rel]], names,
        re.findall(r'^\s*#\s*include\s*[<"]([^>"\n]+)', texts[rel], re.M), {}, selection), len(texts[rel]), rel))
    files = [rel for rel in ranked if rel not in skip][:config.get('max_files')]
    if config.get('rolling_workers'):
        capacity = min(jobs, config.get('max_files') or len(ranked))
        retry = config.get('retry_targets', {})
        offsets = config.get('file_offsets', {})
        refill = [rel for rel in ranked if rel in skip and offsets.get(rel, 0) < retry.get(rel, 0)]
        extra = refill[:max(0, capacity-len(files))]
        files += extra
        if extra:
            log('Filling %d idle file slots with different pending targets' % len(extra))
    model, rounds = config["llm"], config.get("rounds", 3)
    options = {key: config[key] for key in ("thinking", "max_tokens", "generation") if key in config}
    options.update(config.get("provider_options", {}))
    options.setdefault("gate", providers.CloudGate(jobs))
    compile_batch = int(config.get('compile_batch', 1))
    if not 1 <= compile_batch <= 32:
        raise ValueError('Methods per compile must be 1-32')
    provider_failed = threading.Event()
    event = options.pop("event", None)
    compile_workers = resolve_compile_workers(config.get("compile_workers", "auto"), jobs)
    compile_slots = threading.Condition()
    active, waiting_proofs = 0, 0
    raw_compile = compile_source
    compile_records = []
    def compile_source(source, rel, label):
        nonlocal active, waiting_proofs
        queued = time.monotonic()
        proof = label != "baseline"
        with compile_slots:
            if proof:
                waiting_proofs += 1
            try:
                compile_slots.wait_for(lambda: active < compile_workers and (proof or waiting_proofs == 0))
                active += 1
            finally:
                if proof:
                    waiting_proofs -= 1
        waited = time.monotonic() - queued
        try:
            result = dict(raw_compile(source, rel, label), queue_seconds=round(waited, 2))
            compile_records.append(result)
            return result
        finally:
            with compile_slots:
                active -= 1
                compile_slots.notify_all()
    context = config.get("context", "file")
    log("Native discovery: %d files · %d AI workers · %d compiler slots" % (len(files), jobs, compile_workers))

    def discover(rel, log, options):
        if provider_failed.is_set() or options.get("before_request") and not options["before_request"]():
            return None, []
        log("Compiling baseline")
        base = compile_source(texts[rel], rel, "baseline")
        if not base["ok"]:
            return None, [base]
        log("Baseline: compile %.1fs · queue %.1fs" % (base.get("seconds", 0), base.get("queue_seconds", 0)))
        data = Path(base["object"]).read_bytes()
        comparing = time.monotonic()
        baseline = {h["addr"] for h in matcher.scan(data)}
        log("Baseline comparison: %.1fs · %d exact" % (time.monotonic() - comparing, len(baseline)))
        pending = [addr for addr in homes[rel] if addr not in baseline]
        base['pending_targets'] = len(pending)
        if not pending:
            log("Skipping AI: all %d targets already code/data exact locally" % len(homes[rel]))
            return None, [base]
        if provider_failed.is_set():
            return None, [base]
        offset = int(config.get('file_offsets', {}).get(rel, config.get('target_offset', 0))) % len(pending)
        pending = pending[offset:] + pending[:offset]
        original, working = texts[rel], texts[rel]
        symbol_map = {a: names[a]['symbol'] for a in pending if names.get(a, {}).get('symbol')}
        baseline_diagnostics = native_search.diagnose(data, symbol_map) if partials else {}
        base['diagnostics'] = baseline_diagnostics
        seed = partials.seed(rel, original, pending) if partials else None
        negative = output / 'exhausted' / (integration.digest(rel) + '.json')
        negative_key = integration.digest([base.get('input_signature'), base.get('object_sha256'),
            getattr(matcher, 'identity', None), pending, config.get('base_revision'), model, rounds,
            seed['source_sha256'] if seed else None,
            {k: config.get(k) for k in ('thinking', 'max_tokens', 'generation', 'context', 'compile_batch', 'provider_options',
                                       'automatic_prepass', 'prepass_limit', 'proven_facts', 'rewrite_rules', 'transform_modes', 'scoped_modes')
             if k != 'provider_options'},
            {k: v for k, v in config.get('provider_options', {}).items() if isinstance(v, (str, int, float, bool, type(None)))},
            hashlib.sha256(Path(native_search.__file__).read_bytes()).hexdigest(),
            hashlib.sha256(Path(native_transforms.__file__).read_bytes()).hexdigest(),
            hashlib.sha256(Path(__file__).read_bytes()).hexdigest()])
        if (config.get('search_cache', True) and base.get('input_signature') and not config.get('retry_exhausted')
                and negative.exists() and json.loads(negative.read_text()).get('key') == negative_key):
            base['search_cache_hit'] = True
            log('Skipping exhausted search: unchanged source, dependencies, compiler, targets and search settings')
            return None, [base]
        from roc.integration_policy import AttemptBudget
        budget = AttemptBudget(output / 'attempt-budgets' / (integration.digest(rel) + '.json'),
            integration.digest([base.get('input_signature'), base.get('object_sha256'), getattr(matcher, 'identity', None),
                                sorted({(a, a in owned) for addr in pending for a in by_addr.get(addr, {}).get('call_targets', [])}),
                                model, options.get('escalation_model'),
                                options.get('escalate_after'),
                                {k: config.get(k) for k in ('thinking','max_tokens','generation','context','compile_batch','proven_facts','rewrite_rules')},
                                [hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in
                                 (Path(__file__), Path(native_search.__file__), Path(native_transforms.__file__),
                                  ROOT/'roc/native_adapt.py', ROOT/'roc/native_batch.py', ROOT/'roc/integration_policy.py') if Path(p).exists()]]),
            config.get('max_no_improvement', 3)) if base.get('input_signature') else None
        if budget:
            budget.prime(baseline_diagnostics)
            options = dict(options, attempt_allowed=lambda addrs: any(not budget.blocked(a) for a in addrs), record_attempt=budget.record)
        if budget and not config.get('retry_exhausted'):
            blocked = [a for a in pending if budget.blocked(a)]
            pending = [a for a in pending if not budget.blocked(a)]
            base['blocked_targets'] = blocked
            if not pending:
                base.update(search_cache_hit=True, blocker='no-improvement-budget')
                log('All targets blocked by unchanged-input attempt budget; best partials retained')
                return None, [base]
        if config.get('reserve_file') and not config['reserve_file'](rel, pending):
            base.update(blocker='class-lease-unavailable', deferred_targets=pending)
            return None, [base]
        if partials:
            if seed:
                trial = compile_source(seed['source'], rel, 'partial-seed-' + seed['source_sha256'][:16])
                if trial['ok']:
                    seed_data = Path(trial['object']).read_bytes()
                    hits = {h['addr'] for h in matcher.scan(seed_data)}
                    current = native_search.diagnose(seed_data, symbol_map)
                    if not baseline - hits and any(current[a]['score'] > baseline_diagnostics[a]['score']
                            or current[a].get('frame_ok') and not baseline_diagnostics[a].get('frame_ok')
                            or current[a].get('calls_ok') and not baseline_diagnostics[a].get('calls_ok') for a in current):
                        working = seed['source']
                        data = seed_data
                        log('Resuming recompiled no-loss partial: ' + seed['addr'])

        attempted_sources = set()
        def trial_compile(source, label):
            attempted_sources.add(integration.digest(source))
            result = compile_source(source, rel, label)
            if result['ok'] and not native_search.visible_callees_ok(source, Path(result['object']).read_bytes(), config.get('proven_facts',[]), rel):
                result.update(ok=False, error='Visible callee emitted different code/data; keep original source', blocker='callee-codegen')
            if partials and result['ok']:
                obj = Path(result['object']).read_bytes()
                found = {h['addr'] for h in matcher.scan(obj)}
                result['diagnostics'] = native_search.diagnose(obj, symbol_map)
                result['partials_saved'] = partials.retain(rel, original, source, result, result['diagnostics'],
                                                          baseline_diagnostics, baseline - found)
            return result

        def evidence(addr):
            return dict(model_evidence(addr, names, by_addr), current_diff=diff(data, addr),
                        diagnostic=baseline_diagnostics.get(addr, {}))

        def completed(proposal, trials):
            if any(t.get('error_category') in providers.FATAL_ERRORS for t in trials):
                provider_failed.set()
            if not proposal and config.get('repair_rounds', 2):
                from roc import native_repair
                attempted = {a for t in trials for a in t.get('target_addresses', []) if a in symbol_map}
                repair_seed = partials.seed(rel, original, sorted(attempted)) if partials and attempted else None
                proposal, repairs = native_repair.run(rel, working,
                    {a: symbol_map[a] for a in sorted(attempted)}, baseline, trial_compile, matcher, log,
                    rounds=config.get('repair_rounds', 2), limit=config.get('repair_trials', 24),
                    context=declaration_context,
                    seed=repair_seed['source'] if repair_seed else None,
                    diagnostics=baseline_diagnostics,
                    seen=attempted_sources,
                    before_trial=options.get('before_request'))
                trials += repairs
            if proposal and working != original:
                proposal['edits'] = native_search.anchored_changes(original, apply_edits(working, proposal['edits']))
                proposal = minimize(rel, original, proposal['edits'], {h['addr'] for h in proposal['witnesses']},
                                    baseline, trial_compile, matcher, 'seed-composition',
                                    definitions=proposal['proof'].get('defined_symbols', ()))
            if (not proposal and base.get('input_signature') and config.get('search_cache', True)
                    and len([t for t in trials if t.get('generation')]) >= rounds
                    and all(t.get('ok') and not t.get('error') for t in trials
                            if t.get('mode') not in ('model-request', 'repair-coverage'))
                    and not any(t.get('stopped') or t.get('deferred_targets') for t in trials if t.get('mode') == 'repair-coverage')):
                integration.atomic_json(negative, dict(key=negative_key, blocker='exhausted-rounds', accepted=False))
            if budget:
                budget.record(trials, [h['addr'] for h in proposal['witnesses']] if proposal else [])
            return proposal, [base] + trials

        def diff(obj, addr):
            return body_diff(obj, names[addr]["symbol"], addr) if names.get(addr, {}).get("symbol") else "no rebuilt body"
        try:
            prepass = []
            trials = []
            dependencies = base.get('compiler_config', {}).get('dependencies', {})
            declaration_context = config.get('declaration_context', '') + '\n' + '\n'.join(
                Path(p).read_text(errors='replace') for p in dependencies
                if '/App/include/' in str(p).replace('\\','/') and Path(p).is_file())
            if config.get('automatic_prepass'):
                selected_methods = {symbol_method(symbol_map[a]) for a in pending[:3] if a in symbol_map}
                dependencies = base.get('compiler_config', {}).get('dependencies', {})
                declaration_context = config.get('declaration_context', '') + '\n' + '\n'.join(
                    Path(p).read_text(errors='replace') for p in dependencies
                    if '/App/include/' in str(p).replace('\\','/') and Path(p).is_file())
                local_trials = list(native_transforms.method_variants(working, selected_methods,
                    declaration_context, config.get('transform_modes')))
                from roc.native_adapt import adapt
                for address in pending[:3]:
                    mined_file = next((p for p in (ROOT/'src/2008-06'/(address+'.cpp'), ROOT/'work/native-evidence'/address/'mined.cpp') if p.is_file()), None)
                    method = symbol_method(symbol_map.get(address, ''))
                    if mined_file and method:
                        try:
                            edits = adapt(mined_file.read_text(encoding='utf-8'), working, method, declaration_context)
                            local_trials.insert(0, ('mined-body:'+method, apply_edits(working, edits), edits))
                        except ValueError:
                            pass  # Ambiguous/synthetic declarations require ABI work, not body transplantation.
                local_trials += list(native_transforms.immediate_variants(working, baseline_diagnostics))
                local_trials += list(native_transforms.proven_variants(working, config.get('proven_facts', []), rel))
                local_trials += list(native_search.explicit_variants(working, config.get('rewrite_rules', []), rel))
                local_trials += list(native_transforms.template_variants(working, declaration_context))
                local_trials += list(native_search.scoped_variants(working,
                    config.get('scoped_modes', ['scoped-osize', 'scoped-speed', 'scoped-fp', 'scoped-noautoinline']), selected_methods))
                if config.get('targeted_recipes', True) and baseline_diagnostics:
                    families = {'temporary-inline':'expression-lifetime','temporary-name':'expression-lifetime',
                                'expression-grouping':'expression-lifetime','map-value-entry':'map-value-type'}
                    def relevant(item):
                        family, _, method = item[0].partition(':')
                        rows = [r for r in baseline_diagnostics.values() if symbol_method(r.get('symbol','')) == method]
                        return not rows or any(families.get(family,family) in r.get('recipes',[]) for r in rows)
                    local_trials = [item for item in local_trials if relevant(item)]
                seen = set()
                for mode, candidate, edits in local_trials[:config.get('prepass_limit', 12)]:
                    key = integration.digest(candidate)
                    if key in seen:
                        continue
                    seen.add(key)
                    result = trial_compile(candidate, 'prepass-'+key[:16])
                    hits = matcher.scan(Path(result['object']).read_bytes()) if result['ok'] else []
                    found = {h['addr'] for h in hits}
                    result.update(hits=hits, losses=sorted(baseline-found) if result['ok'] else [], search_family=mode)
                    prepass.append(result)
                    new = (found & set(pending))-baseline
                    if native_transforms.changed_methods(working,candidate)-{symbol_method(h['symbol']) for h in hits}:
                        result['blocker'] = 'unproven-method-change'
                        continue
                    if new and not baseline-found:
                        proposal = minimize(rel, working, edits, new, baseline, trial_compile, matcher,
                            'prepass', definitions=result.get('defined_symbols', ()), verified=result)
                        return completed(proposal, prepass)
                if partials:
                    improved_seed = partials.seed(rel, original, pending)
                    if improved_seed and improved_seed['source'] != working:
                        trial = trial_compile(improved_seed['source'], 'prepass-seed-'+improved_seed['source_sha256'][:16])
                        if trial['ok'] and not baseline-{h['addr'] for h in matcher.scan(Path(trial['object']).read_bytes())}:
                            working = improved_seed['source']
                            data = Path(trial['object']).read_bytes()
            if compile_batch > 1 and options.get('generation', 'edits') != 'edits':
                from roc import native_batch
                groups = {}
                spans = methods(working)
                for addr in pending:
                    method = symbol_method(names.get(addr, {}).get('symbol') or '')
                    if addr not in baseline and method in spans and spans[method][1] - spans[method][0] <= 6000:
                        groups.setdefault(method, []).append(addr)
                if len(groups) > 1:
                    selected = dict(list(groups.items())[:compile_batch])
                    proposal, trials = native_batch.model_batch(rel, working, selected, baseline, model, rounds,
                        trial_compile, matcher, evidence,
                        log, options, ai_pool, diff)
                    if any(t.get('error_category') in providers.FATAL_ERRORS for t in trials):
                        provider_failed.set()
                    if proposal or provider_failed.is_set() or options.get('generation') == 'method' or rounds <= 1:
                        return completed(proposal, prepass + trials)
                    feedback = '\n'.join(str(t.get('error', '')) for t in trials if t.get('error'))
                    diagnostic = next((t for t in trials if t.get('ok') and t.get('object')), None)
                    if diagnostic:
                        feedback += '\nBatch compiled; existing exact lost: %s.' % diagnostic.get('losses', [])[:12]
                        obj = Path(diagnostic['object']).read_bytes()
                        feedback += ''.join('\n%s target vs batch:\n%s' % (addr, diff(obj, addr)) for addr in pending[:2])
                    proposal, repairs = model_proposal(rel, working, pending, baseline, owned, model, rounds - 1,
                        trial_compile, matcher, evidence,
                        log, dict(options, generation='edits', initial_feedback=feedback), diff,
                        excerpt(working, [names[a]['symbol'] for a in pending[:3]]) if context == 'methods' else None)
                    return completed(proposal, prepass + trials + repairs)
            proposal, trials = model_proposal(rel, working, pending, baseline, owned, model, rounds,
                                              trial_compile, matcher, evidence,
                                              log, options, diff,
                                              excerpt(working, [names[a]["symbol"] for a in pending[:3]
                                                                   if names.get(a, {}).get("symbol")])
                                              if context == "methods" else None)
        except Exception as error:  # noqa: BLE001 - one provider/compile failure must not stop the other files
            if getattr(error, "category", "") in providers.FATAL_ERRORS:
                provider_failed.set()
                log("Provider configuration failed; queued files skipped: " + str(error))
            return completed(None, prepass + trials + [{"file": rel, "mode": "model", "ok": False, "error": str(error)[:500], "error_category": getattr(error, "category", "")}])
        return completed(proposal, prepass + trials)

    slots, slots_lock = list(range(jobs)), threading.Lock()
    def one(rel):
        if provider_failed.is_set() or options.get("before_request") and not options["before_request"]():
            return None, []
        with slots_lock:
            slot = slots.pop(0)
        local_slot.slot = slot
        started = time.monotonic()
        if event:
            event("native_started", slot=slot, file=rel, model=model)
        def report(message):
            if event:
                event("native_progress", slot=slot, file=rel, message=str(message))
            else:
                log(message)
        try:
            proposal, trials = discover(rel, report, dict(options, log=report))
            if proposal:
                proof = proposal['proof']
                ownership = ownership_candidates(Path(proof['object']).read_bytes(), proposal['witnesses'])
                unique = {h['addr'] for h in proposal['witnesses'] if ownership.get(h['addr']) == [h['addr']]}
                if len(unique) != len(proposal['witnesses']):
                    archive = output/'ambiguous-proposals'/(integration.digest([
                        rel, proposal['edits'], proposal.get('related_headers'), config.get('base_revision')])+'.json')
                    if not archive.exists():
                        integration.atomic_json(archive, dict(proposal=proposal, ownership_candidates=ownership))
                    report('%d code/data matches lack unique ownership; proof retained locally' %
                           (len(proposal['witnesses'])-len(unique)))
                    if unique:
                        proposal = minimize(rel, texts[rel], proposal['edits'], unique,
                            {h['addr'] for h in matcher.scan(Path(trials[0]['object']).read_bytes())},
                            lambda source,label:compile_source(source,rel,label), matcher, 'unique-ownership',
                            definitions=proof.get('defined_symbols', ()), verified=proof)
                    else:
                        proposal = None
                    if proposal is None:
                        trials.append(dict(file=rel, mode='ownership', ok=False, error_category='ambiguous_ownership',
                            error='Code/data matched, but no uniquely owned gain; proof retained locally'))
            if event:
                event("native_result", slot=slot, file=rel,
                      local_exact=len(proposal["witnesses"]) if proposal else 0,
                      error_category="" if proposal else next((t["error_category"] for t in reversed(trials) if t.get("error_category")), ""),
                      seconds=round(time.monotonic() - started, 1),
                      error="" if proposal else next((t.get("error", "") for t in reversed(trials) if t.get("error")), "")[:240])
            return proposal, trials
        finally:
            with slots_lock:
                slots.append(slot)

    proposals, records = [], []
    with ThreadPoolExecutor(max_workers=jobs) as ai_pool, ThreadPoolExecutor(max_workers=jobs) as pool:
        futures = [pool.submit(one, rel) for rel in files]
        for n, future in enumerate(as_completed(futures)):
            proposal, trials = future.result()
            records.extend(trials)
            journal.add(trials)
            if proposal:
                try:
                    integration.validate_patches({proposal["file"]: proposal["edits"]})
                except ValueError as error:
                    integration.atomic_json(output / 'blocked-proposals' / (integration.digest(proposal['file'])[:16] + '.json'),
                                            dict(proposal=proposal, reason=str(error)))
                    records.append(dict(file=proposal["file"], error="Proposal retained, not staged: " + str(error)))
                    log("Proposal retained, not staged: %s: %s" % (proposal["file"], error))
                    continue
                for hit in proposal["witnesses"]:
                    hit["claim_unit"] = claim_unit(hit, by_addr[hit["addr"]])
                if config.get('base_revision'):
                    proposal['base_revision'] = config['base_revision']
                proposals.append(proposal)
                integration.atomic_json(output / 'proposals.json', proposals)
                log('Saved %d local exact across %d files; %d/%d files finished, linked preflight follows discovery' % (
                    sum(len(p['witnesses']) for p in proposals), len(proposals), n + 1, len(files)))
            integration.atomic_json(output / "progress.json", {"phase": "model", "files_done": n + 1, "total": len(files),
                                                               "proposals": len(proposals)})
    journal.flush()
    integration.atomic_json(output / 'metrics.json', native_search.metrics(records, time.monotonic() - search_started, proposals,
                                                                        compilations=compile_records))
    integration.atomic_json(output / 'blockers.json', native_search.blocker_queues(records))
    return proposals, records


def native_context(config, api, addresses=None):
    """Compile settings, targets and owned exacts every native discovery shares (sweep, model pass, agent CLI)."""
    module = rebuild.load_module("2008-06", "rbxgs-app")
    tree, overlay = rebuild.build_overlay("2008-06", "RbxgsApp", module["overlay"])
    recipe = libs.RECIPES["rbxgs"]
    includes = [libs._case_path(libs.LIBS / path).resolve() for path in recipe["include"] if path != "WINSDK"]
    includes = rebuild._overlaid(includes, [], (tree, overlay))[0]
    defines = recipe["defines"] + " BOOST_ALL_NO_LIB"
    # Discovery reads installed manifests only. Mutable source/output trees stay private.
    evidence_root = Path(os.environ.get("ROC_NATIVE_EVIDENCE_ROOT", ROOT))
    manifest = Path(config.get("manifest", evidence_root / "rebuild/2008-06/manifests/functions.json"))
    names_path = evidence_root / "rebuild/2008-06/out/native-names.json"
    owned_path = Path(config.get("owned_report", evidence_root / "rebuild/2008-06/out/RbxgsApp/report.json"))
    linked_path = evidence_root / "work/integration/progress-native.json"
    if all(path.exists() for path in (manifest, names_path, owned_path, linked_path)):
        rows = json.loads(manifest.read_text(encoding="utf-8"))
        owned = set(json.loads(owned_path.read_text()).get("owned_addrs", []))
        integrated = set(json.loads(linked_path.read_text())["addresses"])
        names = json.loads(names_path.read_text())
    else:
        # Contributor PCs rarely hold the server's rebuild artifacts: take the same evidence from the server.
        evidence = server_evidence(api)
        rows = [{"addr": addr, "unit": unit, "size": size, "score": 100} for addr, (unit, size) in evidence["targets"].items()]
        owned, names = set(evidence["linked"]), evidence["names"]
        integrated = set(evidence["linked"])
    for job in api.call("/v1/integration")["jobs"]:
        if job["state"] == "accepted":
            owned.update(job["receipt"].get("gains", []))
            integrated.update(job["receipt"].get("gains", []))
    # Every byte-exact mined source kind (snippet, vendor-file, generated-unit) is a target: the linked
    # rebuild owns an address by exact bytes. Snippet-only targeting hid ~5k exact app functions.
    from roc.native_adapt import type_paths, eligible
    native_paths, _ = type_paths(ROOT, json.loads((ROOT/'rebuild/2008-06/patches/rbxgs-client.json').read_text()))
    targets = {row['addr'] for row in rows if row.get('score') == 100 and eligible(row.get('unit'), row['addr'], names, native_paths)}
    if addresses:
        targets &= set(addresses)
    analysis_path = ROOT/'work/2008-06/functions.jsonl'
    analysis = match._functions_at(analysis_path, analysis_path.stat().st_mtime_ns, analysis_path.stat().st_size) if analysis_path.exists() else {}
    enriched = {row['addr']: dict(row, call_targets=analysis.get(row['addr'], {}).get('call_targets', [])) for row in rows}
    return SimpleNamespace(tree=tree, overlay=overlay, includes=includes, defines=defines, flags=config.get("flags", FLAGS),
                           by_addr=enriched, owned=owned, targets=targets,
                             matcher=Matcher(targets | owned, ROOT / 'work/native-search/matches' if config.get('search_cache', True) else None), names=names, integrated=integrated)


EVIDENCE_CACHE = ROOT / "work/integration-client/evidence.json"


def server_evidence(api):
    """GET /v1/integration/evidence, cached for tools (roc standins) that run without an API handle."""
    evidence = api.call("/v1/integration/evidence", timeout=300)
    integration.atomic_json(EVIDENCE_CACHE, evidence)
    return evidence


def run(spec, name, server=None, jobs=4, limit=None, output=None, log=print):
    """Discover, minimize, recompile, claim, stage, and optionally submit real native fixes."""
    require_private_workspace()
    config = dict(spec["native_sweep"])
    run_started = time.monotonic()
    config.setdefault('keep_partials', True)
    config.setdefault('automatic_prepass', True)
    config.setdefault('repair_rounds', 2)
    config.setdefault('repair_trials', 24)
    if type(config['repair_rounds']) is not int or not 0 <= config['repair_rounds'] <= 8:
        raise ValueError('Repair rounds must be 0-8')
    if type(config['repair_trials']) is not int or not 1 <= config['repair_trials'] <= 256:
        raise ValueError('Repair trial limit must be 1-256')
    partial_lock = threading.Lock()
    if config.get("llm"):
        config.setdefault("model", config["llm"])  # submissions name the model that wrote the edits
    if spec.get("client", "2008-06") != "2008-06":
        raise ValueError("Native sweep supports the coherent 2008-06 module only")
    output = Path(output or ROOT / "work/research" / name).resolve()
    output.mkdir(parents=True, exist_ok=True)
    outbox = output / 'partial-reports.json'
    def retain_report(row):
        with partial_lock:
            pending = json.loads(outbox.read_text()) if outbox.exists() else []
            pending.append(row)
            integration.atomic_json(outbox, pending)
    config['partial_report'] = retain_report
    previous = output / 'proposals.json'
    if previous.exists():
        content = previous.read_bytes()
        archive = output / 'proposal-history' / (hashlib.sha256(content).hexdigest() + '.json')
        archive.parent.mkdir(exist_ok=True)
        if not archive.exists():
            archive.write_bytes(content)
    run_id = uuid.uuid4().hex
    recovery_ticket, recovery_blocked = None, []
    integration.atomic_json(output / "summary.json", {"recipe": name, "state": "running", "run_id": run_id, "new_verified": 0})
    integration.atomic_json(output / "progress.json", {"phase": "setup", "run_id": run_id})
    def finish(summary):
        if outbox.exists() and settings.get('user'):
            pending = json.loads(outbox.read_text())
            for revision in sorted({r['base_revision'] for r in pending}):
                selected = [r for r in pending if r['base_revision'] == revision]
                for start in range(0, len(selected), 64):
                    batch = selected[start:start + 64]
                    try:
                        api.call('/v1/integration/partials', dict(user=settings['user'],
                            model=config.get('model') or config.get('llm') or 'native-grid',
                            base_revision=revision, partials=batch), timeout=15)
                    except (worker.ApiFailure, OSError, ValueError):
                        log('Partial webhook report pending; retained for next run')
                        break
                    pending = [r for r in pending if r not in batch]
                    integration.atomic_json(outbox, pending)
        metrics_path = output / 'metrics.json'
        if metrics_path.exists():
            measured = json.loads(metrics_path.read_text())
            measured.update(server_verified=summary.get('new_verified', 0),
                            verification_wait_seconds=summary.get('verification_wait_seconds', 0),
                            verified_per_hour=summary.get('new_verified', 0) * 3600 / max(time.monotonic() - run_started, .001))
            count = summary.get('new_verified', 0)
            measured['ai_requests_per_verified_function'] = measured.get('model_requests', 0)/count if count else None
            measured['reported_tokens_per_verified_function'] = measured.get('reported_tokens', 0)/count if count and measured.get('token_reporting_complete') else None
            integration.atomic_json(metrics_path, measured)
            summary['metrics'] = measured
        summary.update(run_id=run_id, state=summary.get("state") or ("queued" if summary.get("job") else "staged" if summary.get("applied_files") else "proposals" if summary.get("proposed_files") else "no-proposals"))
        if recovery_ticket and summary['state'] != 'failed':
            record = json.loads(recovery_ticket.read_text())
            integration.atomic_json(recovery_ticket, dict(record, state='done', job=summary.get('job')))
        if recovery_blocked:
            hold_proposals(output, recovery_blocked, base['revision'], state='blocked', model=config.get('model'))
        integration.atomic_json(output / "summary.json", summary)
        integration.atomic_json(output / "runs" / (run_id + ".json"), summary)
        integration.atomic_json(output / "progress.json", {"phase": summary["state"], "run_id": run_id,
                                                           "job": summary.get("job"), "new_verified": summary.get("new_verified", 0)})
        return summary
    settings = worker.load_settings()
    api = worker.Api(server or settings["server"], integration.native_token() or settings.get("native_token") or settings.get("token"))
    claimed, used = [], set()
    keep_claims = False
    reservations = None
    summary = {}
    generator = ROOT / "rebuild/2008-06/patches/make_rbxgs_client.py"
    try:
        if config.get("submit") and not config.get("model"):
            raise ValueError("Submission requires actual model identity")
        if config.get("after_job"):
            integration.atomic_json(output / "progress.json", {"phase": "waiting_for_job", "run_id": run_id,
                                                               "job": config["after_job"]})
            prior = wait_for_job(api, config["after_job"], config.get("verify_timeout", 4 * 3600), log)
            if prior["state"] != "accepted" or not prior["receipt"].get("accepted"):
                raise ValueError("Prerequisite native batch was rejected; discovery not started")
            integration.command(SimpleNamespace(action="sync", server=server, user=None, token=integration.native_token()))
        recovered = integration.resume_pending(api, ROOT / "work/integration-client", settings.get("user"))
        if recovered:
            result = recovered[0]
            restore_submitted_baseline(result["id"], log)
            return finish(dict(recipe=name, job=result["id"], state=result["state"],
                               applied_paths=result.get("applied_paths", []), files_tried=[],
                               applied_files=len(result.get("applied_paths", [])), new_verified=0))
        original = generator.read_bytes()
        base = api.call("/v1/integration/base")
        if config.get("apply"):
            integration.require_reference_gate(base)
        if hashlib.sha256(original).hexdigest() != base["generator"]:
            raise ValueError("Sync accepted work and preserve unsent generator edits before sweeping")
        overlay_file = generator.with_name("rbxgs-client.json")
        if json.loads(overlay_file.read_text()) != base["overlay"]:
            if not integration.sync_client_baseline(ROOT, base, only_if_clean=True):
                raise ValueError("Local overlay differs from server baseline; preserve local edits and sync first")
            log("accepted baseline advanced; clean local overlay refreshed")
        integration.atomic_json(ROOT / "work/integration-client/baseline.json", base)
        log("Native setup: materializing accepted source overlay and indexing target evidence")
        ctx = native_context(config, api, spec.get("targets", {}).get("addresses"))
        tree, overlay, includes, defines, flags = ctx.tree, ctx.overlay, ctx.includes, ctx.defines, ctx.flags
        by_addr, owned, targets, matcher = ctx.by_addr, ctx.owned, ctx.targets, ctx.matcher
        files = sorted({p.relative_to(tree).as_posix() for pattern in config.get("files", ["App/*/*.cpp"])
                        for p in tree.glob(pattern) if not p.name.startswith("roc_")})
        if limit and not config.get("targets_only"):
            files = files[:limit]
        log("Native setup: resolving historical compiler and source files")
        rebuild.toolchain()  # Resolve discovery once before compile workers start.
        texts = {rel: (overlay / rel if (overlay / rel).exists() else tree / rel).read_text(errors="replace") for rel in files}
        if config.get('automatic_transforms', True):
            all_sources = dict(texts)
            for p in tree.glob('App/*/*.cpp'):
                if p.name.startswith('roc_'):
                    continue
                rel = p.relative_to(tree).as_posix()
                if rel not in all_sources:
                    selected_source = overlay/rel if (overlay/rel).exists() else p
                    all_sources[rel] = selected_source.read_text(errors='replace')
            homes = target_files(texts, targets-owned, ctx.names, by_addr)
            config['proven_facts'] = list(config.get('proven_facts', [])) + native_transforms.callee_facts(
                all_sources, homes, ctx.names, by_addr)
        discovery_targets = targets - owned - getattr(ctx, "integrated", set())
        if config.get("targets_only"):
            discovery_targets -= getattr(ctx, "integrated", set())
            homes = target_files(texts, discovery_targets, ctx.names, by_addr)
            files = sorted(homes, key=lambda rel: (-len(homes[rel]), rel))
            if limit:
                files = files[:limit]
            texts = {rel: texts[rel] for rel in files}
        saved_path = config.get('proposals_file')
        if config.get('resume_saved') and not saved_path:
            recovery_ticket, saved_path = pending_proposals(output, base['revision'])
            if recovery_ticket:
                config['model'] = json.loads(recovery_ticket.read_text())['model']
                log('Recovering saved proposals against current baseline; no AI requests; original model ' + config['model'])
        if saved_path:
            # Proposals an agent already proved with `roc native-try check`: claim, stage and submit them as one batch.
            saved_bytes = Path(saved_path).read_bytes()
            archive = output / ("saved-proposals-" + hashlib.sha256(saved_bytes).hexdigest()[:20] + ".json")
            if not archive.exists():
                archive.write_bytes(saved_bytes)
            proposals, records = json.loads(saved_bytes), []
            final_checks, trials, rechecked = [], [], []
            seen = set()
            for proposal in proposals:
                proposal["file"] = next(iter(integration.canonical_patches({proposal["file"]: []}, base["overlay"])))
                rel = proposal["file"]
                if rel.casefold() in seen:
                    raise ValueError("Duplicate saved source proposals: " + rel)
                seen.add(rel.casefold())
                if proposal.get("related_headers"):
                    proposal["related_headers"] = integration.canonical_patches(proposal["related_headers"], base["overlay"])
                changes = {name: edits for name, edits in dict(proposal.get('related_headers', {}),
                           **{rel: proposal['edits']}).items() if edits}
                try:
                    integration.validate_patches(changes)
                except ValueError as error:
                    integration.atomic_json(output / 'blocked-proposals' / (integration.digest(rel)[:16] + '.json'),
                                            dict(proposal=proposal, reason=str(error)))
                    log('Proposal retained, not staged: %s: %s' % (rel, error))
                    if recovery_ticket:
                        recovery_blocked.append(proposal)
                    continue
                original_proposal = json.loads(json.dumps(proposal))
                try:
                    proposal = recheck_proposal(proposal, ctx, texts, output, base['revision'], log, recover=bool(recovery_ticket))
                except SavedProposalError as error:
                    if not recovery_ticket:
                        raise
                    recovery_blocked.append(original_proposal)
                    integration.atomic_json(output/'blocked-proposals'/(integration.digest(original_proposal)+'.json'),
                                            dict(proposal=original_proposal, reason=str(error)))
                    log('Saved proposal retained for repair: %s: %s' % (rel, error))
                    continue
                if proposal is None:
                    continue
                final_checks.append(proposal["proof"])
                rechecked.append(proposal)
            proposals = rechecked
        elif config.get("llm"):
            discovery = dict(config, base_revision=base['revision'])
            if config.get('apply') and config.get('reserve_before_ai', True):
                from roc.integration_policy import Reservations
                identity_file = ROOT/'work/integration-client/identity.json'
                if not identity_file.exists():
                    integration.atomic_json(identity_file, dict(id=uuid.uuid4().hex))
                identity = json.loads(identity_file.read_text())['id'][:12]
                inventory = api.call('/v1/integration?claims=1').get('inventory', {})
                by_target = {a:u for u, addrs in inventory.items() for a in addrs}
                def save_reserved(claim):
                    folder = ROOT/'work/integration-client/claims'/claim['id']
                    integration.atomic_json(folder/'packet.json', claim)
                    (folder/'generator-base.py').write_bytes(generator.read_bytes())
                reservations = Reservations(
                    lambda: worker.Api(server or settings['server'], integration.native_token() or settings.get('native_token') or settings.get('token')),
                    settings['user'], settings['user']+'@native-sweep:'+identity, base['revision'],
                    base.get('limits', {}).get('claims', 16), save_reserved, bulk=base.get('features', {}).get('exact_unit_batches', False))
                discovery['reserve_file'] = lambda rel, addrs: reservations.reserve({by_target[a] for a in addrs if a in by_target})
            if config.get('rolling_workers') and config.get('tried_revision') != base['revision']:
                discovery.update(exclude_files=[], file_offsets={}, retry_targets={})
            proposals, records = model_discovery(discovery, texts, discovery_targets, owned, by_addr, matcher, output, jobs, log,
                                                 lambda source, rel, label: compile_unit(source, rel, label, output, tree,
                                                                                         overlay, includes, defines, flags),
                                                 ctx.names)
            final_checks = [p["proof"] for p in proposals]
            trials = []
        else:
            proposals, records, final_checks = grid_discovery(dict(config, base_revision=base['revision']), texts,
                discovery_targets, matcher, output, jobs,
                lambda source, rel, label: compile_unit(source, rel, label, output, tree, overlay, includes, defines, flags),
                ctx.names, by_addr, log)
            trials = []
        for proposal in proposals:
            proposal["base_revision"] = base["revision"]
        proposal_output = output / "proposals.json"
        if saved_path and Path(saved_path).resolve() == proposal_output.resolve():
            proposal_output = output / "rechecked-proposals.json"
        integration.atomic_json(proposal_output, proposals)
        integration.atomic_json(output / "final-checks.json", final_checks)
        summary = {"recipe": name, "client": "2008-06", "op": "native-grid", "tried": len(records),
                   "proposed_files": len(proposals), "local_exact": sum(len(p["witnesses"]) for p in proposals),
                   "new_verified": 0, "files_tried": sorted({r["file"] for r in records}),
                   "base_revision":base['revision'],
                   "pending_files":{r['file']:r['pending_targets'] for r in records if 'pending_targets' in r}}
        if not proposals or not config.get("apply"):
            return finish(summary)
        if api.call("/v1/integration/base")["revision"] != base["revision"]:
            hold_proposals(output, proposals, base['revision'], ticket=recovery_ticket, model=config.get('model'))
            raise BaselineAdvanced("Accepted baseline changed; saved proofs queued for revalidation before applying")
        identity_file = ROOT / "work/integration-client/identity.json"
        if not identity_file.exists():
            integration.atomic_json(identity_file, {"id": uuid.uuid4().hex})
        identity = json.loads(identity_file.read_text())["id"][:12]
        units, selected, blocked, routed = {}, [], set(), {}
        claim_state = api.call("/v1/integration?claims=1")
        inventory = claim_state.get("inventory")
        parked = set(claim_state.get("parked_units", [])) | {item["unit"] for item in claim_state.get("parked", [])}
        catalog_units = {addr: unit for unit, addresses in (inventory or {}).items() for addr in addresses}
        worker_name = settings["user"] + "@native-sweep:" + identity
        live = [c for c in claim_state.get("claims", []) if c["expires"] > time.time() or c["state"] == "submitted"]
        foreign = {c["unit"] for c in live if c["state"] in ("claimed", "submitted") and
                   (c["user"], c["worker"]) != (settings["user"], worker_name)}
        max_claims = base.get("limits", {}).get("claims", 16)
        for proposal in proposals:
            labels = {h["claim_unit"] for h in proposal["witnesses"]}
            labels.update(by_addr[h["addr"]]["unit"] for h in proposal["witnesses"] if h["addr"] in by_addr)
            needed = set()
            for hit in proposal["witnesses"]:
                unit = catalog_units.get(hit["addr"], by_addr.get(hit["addr"], {}).get("unit", hit["claim_unit"]))
                needed.add(unit if re.fullmatch(r"RBX::(?:\w+::)*\w+", unit) else hit["claim_unit"])
            if (labels | needed) & (parked | foreign):
                blocked.update((labels | needed) & (parked | foreign))
                blockers_path = output / 'blockers.json'
                blockers = json.loads(blockers_path.read_text()) if blockers_path.exists() else {}
                blockers.setdefault('scheduling-claim', []).append(dict(file=proposal['file'],
                    units=sorted((labels | needed) & (parked | foreign)), accepted=False))
                integration.atomic_json(blockers_path, blockers)
                continue
            if inventory is not None:
                absent = needed - inventory.keys()
                if absent:
                    log("Skipping unavailable claim units: " + ", ".join(sorted(absent)))
                needed &= inventory.keys()
            routed[proposal["file"]] = needed
            if len(set(units) | needed) > max_claims:
                continue
            for unit in sorted(needed - set(units)):
                log("native claiming " + unit)
                existing = next((c for c in live if c["unit"] == unit and c["user"] == settings["user"]
                                 and c["worker"] == worker_name and c["state"] == "claimed"
                                 and c["base_revision"] == base["revision"]), None)
                packet = ROOT / "work/integration-client/claims" / existing["id"] / "packet.json" if existing else None
                result = {"claims": [json.loads(packet.read_text())]} if packet and packet.exists() else api.call("/v1/integration/claim", {"user": settings["user"], "worker": worker_name,
                                                          "unit": unit, "count": 1})
                if result["claims"] and result["claims"][0]["base_revision"] != base["revision"] and \
                        api.call("/v1/integration/base")["revision"] == base["revision"]:
                    log("refreshing own stale claim: " + unit)
                    api.call("/v1/integration/release", {"user": settings["user"], "claim": result["claims"][0]["id"]})
                    result = api.call("/v1/integration/claim", {"user": settings["user"],
                                      "worker": settings["user"] + "@native-sweep:" + identity, "unit": unit, "count": 1})
                if result["claims"]:
                    claim = result["claims"][0]
                    claimed.append(claim)
                    if claim["base_revision"] != base["revision"]:
                        raise ValueError("Claim baseline changed; rerun discovery")
                    units[unit] = claim
            # Gains are credited from the linked rebuild, not per claim: take a proposal when it holds at least one
            # claim and no other worker holds a live claim on any class it touches (catalog-less classes and
            # sub-24-byte targets cannot be claimed at all).
            conflicts = (labels | needed) & foreign_claims(settings["user"], identity)
            if not conflicts:
                selected.append(proposal)  # rides on any claim this batch holds; at least one is required below
            else:
                blocked.update(conflicts)
        if selected and not units:
            result = api.call("/v1/integration/claim", {"user": settings["user"], "worker": settings["user"] + "@native-sweep:" + identity,
                                                      "count": 1})
            for claim in result["claims"]:
                claimed.append(claim)
                units[claim["unit"]] = claim
        used = {unit for p in selected for unit in routed[p["file"]]} & units.keys()
        if selected and not used and units:
            used = {sorted(units)[0]}  # carrier claim for catalog-less classes
        additions = {}
        for proposal in selected:
            for path, pairs in dict(proposal.get("related_headers", {}), **{proposal["file"]: proposal["edits"]}).items():
                for pair in pairs:
                    if pair not in additions.setdefault(path, []):
                        additions[path].append(pair)
        if not additions or not used:
            summary.update(state="blocked", blocked_units=sorted(blocked),
                           reason="Classes held by another worker" if blocked else "No native claim available")
            return finish(summary)
        additions = integration.canonical_patches(additions, base["overlay"])
        renewed = api.call("/v1/integration/renew", {"user": settings["user"], "claims": [units[u]["id"] for u in sorted(used)]})
        if not renewed.get("ok"):
            raise ValueError("Claims changed before linked preflight; saved proposals retained")
        linked = linked_preflight_progress(ROOT, additions, output, log)
        if api.call("/v1/integration/base")["revision"] != base["revision"]:
            hold_proposals(output, proposals, base['revision'], ticket=recovery_ticket, model=config.get('model'))
            raise BaselineAdvanced("Accepted baseline advanced during linked preflight; saved proofs queued for revalidation")
        for unit in used:
            claim = units[unit]
            folder = ROOT / "work/integration-client/claims" / claim["id"]
            integration.atomic_json(folder / "packet.json", claim)
            (folder / "generator-base.py").write_bytes(original)
        notes = output / "batch-notes.txt"
        notes.write_text("Native integration: real C++ methods and related declarations.\n"
                         "Every listed method passed exact instruction and referenced-data checks after minimizing edits.\n"
                         "Per-TU previously owned matches preserved; independent linked/runtime/ABI gates still required.\n\n" +
                         "\n".join("Claim %s scheduling addresses: %s. Factory/RTTI tags may differ; exact native proof follows." %
                                   (unit, " ".join(units[unit]["addresses"][:3])) for unit in sorted(used)) + "\n\n" +
                         "\n".join("%s: %s %s; %s; object %s" % (h["claim_unit"], h["addr"], h["symbol"], p["mode"], p["proof"]["object"])
                                   for p in selected for h in p["witnesses"]), encoding="utf-8")
        batch = output / "batch.json"
        integration.atomic_json(batch, {"claims": [units[u]["id"] for u in sorted(used)]})
        (output / "generator-base.py").write_bytes(original)
        stage_generator(generator, original, additions)
        try:
            integration.run_generator(generator, ROOT)
            integration.overlay_delta(base["overlay"], json.loads(overlay_file.read_text()))
        except BaseException:
            generator.write_bytes(original)
            integration.run_generator(generator, ROOT)
            raise
        summary.update(applied_files=len(selected), applied_paths=[p["file"] for p in selected],
                       batch=str(batch), evidence=str(notes))
        keep_claims = True
        if config.get("submit"):
            writers = sorted({m for p in selected for m in (p.get("models") or [config["model"]])})
            writer_label = " + ".join(writers)
            if len(writer_label) > 120:
                raise ValueError("Writer model attribution exceeds server limit; proposals retained")
            args = SimpleNamespace(action="submit", server=server, user=None, token=integration.native_token(),
                                   claim=None, all=False, batch=str(batch), model=writer_label, evidence_file=str(notes), retry=False, wait=False,
                                   applied_paths=summary["applied_paths"], preflight_artifacts=linked.get("artifacts") if linked else None)
            integration.command(args)
            marker = ROOT / "work/integration-client/claims" / units[sorted(used)[0]]["id"] / "job.json"
            summary["job"] = json.loads(marker.read_text())["id"]
            restore_submitted_baseline(summary["job"], log)
            finish(summary)
            if config.get("wait"):
                job = wait_for_job(api, summary["job"], config.get("verify_timeout", 4 * 3600), log)
                summary.update(state=job["state"], receipt=job["receipt"],
                               verification_wait_seconds=job.get('verification_wait_seconds', 0))
                if job["state"] == "accepted" and job["receipt"].get("accepted"):
                    summary["new_verified"] = job["receipt"].get("credits", 0)
                    integration.command(SimpleNamespace(action="sync", server=server, user=None, token=integration.native_token()))
        return finish(summary)
    except BaseException as error:
        if recovery_ticket and not isinstance(error, BaselineAdvanced):
            record = json.loads(recovery_ticket.read_text())
            integration.atomic_json(recovery_ticket, dict(record,
                state='pending' if isinstance(error, worker.ApiFailure) else 'blocked',
                error=str(error), attempted_revision=base['revision']))
        state = summary.get("state") if summary.get("state") in ("accepted", "rejected") else "queued" if summary.get("job") else "failed"
        finish(dict(summary, recipe=name, state=state, error=str(error), new_verified=summary.get("new_verified", 0)))
        raise
    finally:
        if reservations:
            try:
                reservations.close({c['id'] for c in claimed})
            except worker.ApiFailure as error:
                log('Early reservation cleanup failed; leases remain bounded: '+str(error))
        for claim in claimed:
            if not keep_claims or claim["unit"] not in used:
                try:
                    api.call("/v1/integration/release", {"user": settings["user"], "claim": claim["id"]})
                except worker.ApiFailure as error:
                    log("Claim release failed (%s): %s" % (claim["id"], error))
        api.close()

roc/native_try.py.base:
"""Agent-driven native integration: the DeepSeek native pass as four commands any agent (Codex, Claude) can drive.

  roc native-try targets [--limit N]            files whose rebuilt methods are exact-mined near misses
  roc native-try evidence FILE [--context ...] [--only ADDR,...]
                                                the exact prompt the model pass sends (rules, code, targets, diffs)
  roc native-try check FILE BLOCKS.txt          apply SEARCH/REPLACE blocks, compile the real file, report;
                                                a new exact with no loss is minimized and saved as a proposal
  roc native-try check FILE                     revalidate saved edits after syncing a new baseline
  roc native-try preflight                      independently build/link saved batch and run acceptance gates
  roc native-try submit --model MODEL           claim, stage and submit every saved proposal as one verified batch

Saved proposals live in work/native-try/proposals.json; later checks of a file build on its saved edits.
Contributor PCs without rebuild artifacts read the evidence from the server (/v1/integration/evidence).
Run it only in a private checkout: it writes rebuild/2008-06/out, and refuses the server's checkout.
`check` edits one source/header; header trials identify a real caller with --only ADDR."""
import hashlib
import json
import re
from pathlib import Path

from roc import integration, native_sweep, worker

OUT = native_sweep.ROOT / "work/native-try"
PROPOSALS = OUT / "proposals.json"


def context():
    # Every action writes the module overlay under rebuild/2008-06/out: never in the server's live checkout.
    native_sweep.require_private_workspace()
    settings = worker.load_settings()
    if not settings.get("server"):
        raise ValueError("Configure a server first: roc config --user NAME --server URL")
    api = worker.Api(settings["server"], integration.native_token() or settings.get("native_token") or settings.get("token"))
    try:
        base = api.call("/v1/integration/base")
        generator = native_sweep.ROOT / "rebuild/2008-06/patches/make_rbxgs_client.py"
        if hashlib.sha256(generator.read_bytes()).hexdigest() != base["generator"]:
            for snapshot in (native_sweep.ROOT / "work/integration-client/jobs").glob("*/submitted-generator.py"):
                original = snapshot.with_name("generator-base.py")
                if original.exists() and generator.read_bytes() == snapshot.read_bytes() and \
                        hashlib.sha256(original.read_bytes()).hexdigest() == base["generator"]:
                    native_sweep.restore_submitted_baseline(snapshot.parent.name)
                    break
        if hashlib.sha256(generator.read_bytes()).hexdigest() != base["generator"]:
            raise ValueError("Local baseline differs from server; run roc integrate sync first")
        if json.loads(generator.with_name("rbxgs-client.json").read_text()) != base["overlay"]:
            if not integration.sync_client_baseline(native_sweep.ROOT, base, only_if_clean=True):
                raise ValueError("Local baseline differs from server; preserve local edits and sync first (roc integrate sync)")
            print("accepted baseline advanced; clean local overlay refreshed", flush=True)
        integration.atomic_json(native_sweep.ROOT / "work/integration-client/baseline.json", base)
        ctx = native_sweep.native_context({}, api)
        ctx.base_revision = base["revision"]
    finally:
        api.close()
    ctx.compile = lambda source, rel, label: native_sweep.compile_unit(source, rel, label, OUT, ctx.tree, ctx.overlay,
                                                                       ctx.includes, ctx.defines, ctx.flags,
                                                                       translation_unit=getattr(ctx, "translation_unit", None),
                                                                       related_headers=getattr(ctx, "related_headers", None))
    return ctx


def saved():
    proposals = json.loads(PROPOSALS.read_text()) if PROPOSALS.exists() else []
    overlay = native_sweep.ROOT / "rebuild/2008-06/patches/rbxgs-client.json"
    base = json.loads(overlay.read_text()) if overlay.exists() else {}
    names = integration.canonical_patches({p["file"]: [] for p in proposals}, base)
    canonical = {name.casefold(): name for name in names}
    seen = set()
    for proposal in proposals:
        name = canonical[proposal["file"].casefold()]
        if name.casefold() in seen:
            raise ValueError("Duplicate saved source proposals: " + name)
        seen.add(name.casefold())
        proposal["file"] = name
        if "related_headers" in proposal:
            proposal["related_headers"] = integration.canonical_patches(proposal["related_headers"], base)
    return proposals


def file_state(ctx, rel):
    """(text with saved edits applied, saved edits, waiting near-miss targets, baseline exacts, baseline object)."""
    original = (ctx.overlay / rel if (ctx.overlay / rel).exists() else ctx.tree / rel).read_text(errors="replace")
    if not hasattr(ctx, "related_headers"):
        ctx.related_headers = next((p.get("related_headers", {}) for p in saved() if p["file"] == rel), {})
    edits = [pair for p in saved() if p["file"] == rel for pair in p["edits"]]
    text = native_sweep.apply_edits(original, edits) if edits else original
    wanted = ctx.targets - ctx.owned
    caller = getattr(ctx, "translation_unit", rel)
    caller_text = (ctx.overlay / caller if (ctx.overlay / caller).exists() else ctx.tree / caller).read_text(errors="replace") if caller != rel else text
    homes = native_sweep.target_files({caller: caller_text}, wanted, ctx.names, ctx.by_addr)
    base = ctx.compile(text, rel, "baseline")
    if not base["ok"]:
        raise SystemExit("baseline compile failed:\n" + base["error"][-2000:])
    data = Path(base["object"]).read_bytes()
    dependencies = Path(base["object"]).with_suffix(".deps")
    included = json.loads(dependencies.read_text()) if dependencies.exists() else []
    # Use compiler evidence: an accepted overlay can differ from the original tools header.
    ctx.evidence_headers = {name: paths for name in re.findall(r'^\s*#\s*include\s*"([^"]+)"', text, re.M)
                            if (paths := [path for path in included if path.replace("\\", "/").lower().endswith(
                                "/" + name.replace("\\", "/").lower())])}
    ctx.evidence_hits = ctx.matcher.scan(data)
    return text, edits, sorted(homes.get(caller, [])), {h["addr"] for h in ctx.evidence_hits}, data


def header_caller(ctx, args):
    if Path(args.file).suffix.lower() not in (".h", ".hpp", ".inl"):
        return
    previous = next((p for p in saved() if p["file"] == args.file), {})
    caller = previous.get("translation_unit")
    if not caller:
        selected = set((getattr(args, "only", None) or "").split(",")) - {""}
        if not selected:
            raise ValueError("Header trial needs --only ADDR to identify its real caller; saved trials remember it")
        texts = {p.relative_to(ctx.tree).as_posix():
                 (ctx.overlay / p.relative_to(ctx.tree) if (ctx.overlay / p.relative_to(ctx.tree)).exists() else p).read_text(errors="replace")
                 for p in ctx.tree.glob("App/*/*.cpp") if not p.name.startswith("roc_")}
        homes = native_sweep.target_files(texts, selected, ctx.names, ctx.by_addr)
        if not homes:
            raise ValueError("No native caller found for the selected header targets")
        caller = max(sorted(homes), key=lambda rel: len(homes[rel]))
    ctx.translation_unit = caller
    print("header proof caller: " + caller, flush=True)


def diff(ctx, obj, addr):
    symbol = ctx.names.get(addr, {}).get("symbol")
    return native_sweep.body_diff(obj, symbol, addr) if symbol else "no rebuilt body"


def cmd_targets(ctx, args):
    wanted = {a for a in ctx.targets - ctx.owned - getattr(ctx, "integrated", set())
              if getattr(args, "min_score", 0) <= ctx.names.get(a, {}).get("score", 0) <= getattr(args, "max_score", 100)}
    wanted -= {w["addr"] for proposal in saved() for w in proposal["witnesses"]}
    texts = {p.relative_to(ctx.tree).as_posix():
             (ctx.overlay / p.relative_to(ctx.tree) if (ctx.overlay / p.relative_to(ctx.tree)).exists() else p).read_text(errors="replace")
             for p in ctx.tree.glob("App/*/*.cpp") if not p.name.startswith("roc_")}
    homes = native_sweep.target_files(texts, wanted, ctx.names, ctx.by_addr)
    for rel in sorted(homes, key=lambda r: -len(homes[r]))[:args.limit]:
        print("%-48s %3d  %s" % (rel, len(homes[rel]), " ".join(homes[rel][:6])))


def cmd_evidence(ctx, args):
    header_caller(ctx, args)
    text, _, addrs, exact, data = file_state(ctx, args.file)
    if args.only:
        addrs = [a for a in addrs if a in args.only.split(",")]
    if not addrs:
        raise SystemExit("no waiting near-miss target in " + args.file)
    shown = native_sweep.excerpt(text, [ctx.names[a]["symbol"] for a in addrs if ctx.names.get(a, {}).get("symbol")]) if args.context == "methods" else text
    items = [dict(native_sweep.model_evidence(a, ctx.names, ctx.by_addr), current_diff=diff(ctx, data, a),
                  tu_code_and_data_exact=a in exact) for a in addrs[:6]]
    ownership = native_sweep.ownership_candidates(data, [h for h in getattr(ctx, "evidence_hits", []) if h["addr"] in addrs[:6]])
    for item in items:
        item["globally_integrated"] = item["addr"] in getattr(ctx, "integrated", set())
        if item["tu_code_and_data_exact"]:
            item["next_action"] = "Already exact in this translation unit; inspect linked ownership/provider before changing source. Server acceptance still required."
        if item["addr"] in ownership:
            item["code_candidates"] = ownership[item["addr"]]
            item["module_ownership_unique"] = ownership[item["addr"]] == [item["addr"]]
            if not item["module_ownership_unique"]:
                item["next_action"] = "Address-ambiguous body; current server ownership gate cannot credit this local exact."
        if item["globally_integrated"]:
            item["next_action"] = "Already independently integrated; changing another module's copy does not earn a new distinct credit."
    if getattr(args, "brief", False):
        for item in items:
            item.pop("target_asm", None)
        print("FILE %s\n```cpp\n%s\n```\nHEADERS (compiler-selected)\n%s\nTARGETS\n%s" %
              (args.file, shown, json.dumps(getattr(ctx, "evidence_headers", {}), indent=1), json.dumps(items, indent=1)))
    else:
        print("HEADERS (compiler-selected)\n" + json.dumps(getattr(ctx, "evidence_headers", {}), indent=1))
        print(native_sweep.model_prompt(args.file, shown, items))


def cmd_check(ctx, args):
    header_caller(ctx, args)
    previous_proposal = next((p for p in saved() if p["file"] == args.file), {})
    ctx.related_headers = {name: list(pairs) for name, pairs in previous_proposal.get("related_headers", {}).items()}
    text, edits, addrs, baseline, _ = file_state(ctx, args.file)
    previous = [w for p in saved() if p["file"] == args.file for w in p["witnesses"]]
    if not args.blocks and not previous:
        raise ValueError("check requires a blocks file, or saved edits to recheck")
    blocks = Path(args.blocks).read_text(encoding="utf-8-sig") if args.blocks else ""
    headers = {}
    if blocks.lstrip().startswith("{"):
        bundle = json.loads(blocks)
        if args.file not in bundle or Path(args.file).suffix.lower() != ".cpp":
            raise ValueError("Paired JSON edits need the primary CPP file and its header edits")
        new_edits = bundle.pop(args.file)
        headers = bundle
        for name, pairs in dict(headers, **{args.file: new_edits}).items():
            if name != args.file and Path(name).suffix.lower() not in (".h", ".hpp", ".inl"):
                raise ValueError("Related files must be headers")
            if not isinstance(pairs, list) or any(not isinstance(pair, list) or len(pair) != 2 or
                                                 not all(isinstance(value, str) for value in pair) for pair in pairs):
                raise ValueError("Paired edits must contain SEARCH/REPLACE string pairs")
        for name, pairs in headers.items():
            ctx.related_headers.setdefault(name, []).extend(pairs)
    else:
        new_edits = native_sweep.parse_edits(blocks) if blocks else []
    changed = bool(new_edits or headers)
    candidate = native_sweep.apply_edits(text, new_edits) if new_edits else text
    result = ctx.compile(candidate, args.file, "check")
    if not result["ok"]:
        raise SystemExit("compile failed:\n" + result["error"][-3000:])
    data = Path(result["object"]).read_bytes()
    hits = ctx.matcher.scan(data)
    found = {h["addr"] for h in hits}
    keep = baseline | {w["addr"] for w in previous}
    # Whole-TU proofs include real header instantiations; inventory file labels are only hints.
    new = (found & ctx.targets) - baseline - ctx.owned - getattr(ctx, "integrated", set())
    lost = keep - found
    ownership = native_sweep.ownership_candidates(data, [h for h in hits if h["addr"] in new])
    ambiguous = {a: candidates for a, candidates in ownership.items() if candidates != [a]}
    new -= ambiguous.keys()
    waiting = set(addrs) - found
    if getattr(args, "only", None):
        waiting &= set(args.only.split(","))
    diffs = {addr: diff(ctx, data, addr) for addr in
             sorted(lost or (waiting if not new and (changed or not previous) else set()))[:3]}
    report = Path(result["object"]).with_suffix(".evidence.json")
    integration.atomic_json(report, dict(file=args.file, base_revision=ctx.base_revision, proof=result,
                                        newly_exact=sorted(new), lost=sorted(lost), still_not_exact=sorted(waiting),
                                        ownership_candidates=ownership, current_diffs=diffs))
    if ambiguous:
        print("address-ambiguous local exacts (no unique module credit): " +
              json.dumps({a: len(candidates) for a, candidates in sorted(ambiguous.items())[:6]}) +
              ("; %d more targets (see evidence)" % (len(ambiguous) - 6) if len(ambiguous) > 6 else ""))
    print("newly exact: %s\nlost: %s\nstill not exact: %s" % (sorted(new) or "none", sorted(lost) or "none",
                                                             sorted(set(addrs) - found) or "none"))
    print("evidence: " + str(report))
    # Successful trials need only their gain/loss summary. On failure show regressions first,
    # rather than burying them under unrelated waiting methods.
    for addr, instructions in diffs.items():
        print("\n%s target vs rebuilt:\n%s" % (addr, instructions))
    if lost or (not new and (not previous or changed)):
        raise SystemExit(1)
    if new_edits:
        proposal = native_sweep.minimize(args.file, text, new_edits, new, keep,
                                         lambda source, label: ctx.compile(source, args.file, label), ctx.matcher, "check",
                                         allow_empty=bool(ctx.related_headers), definitions=result.get("defined_symbols", ()))
    else:
        proposal = dict(file=args.file, edits=[], mode="model", witnesses=[],
                        proof=dict(result, hits=ctx.matcher.scan(data), losses=[]))
    if not proposal:
        raise SystemExit("minimized edits lost the proof; nothing saved")
    if headers:
        source = native_sweep.apply_edits(text, proposal["edits"]) if proposal["edits"] else text
        for name, pairs in headers.items():
            for pair in list(pairs):
                kept = list(ctx.related_headers[name])
                ctx.related_headers[name].remove(pair)
                trial = ctx.compile(source, args.file, "minimize-header-" + native_sweep.integration.digest([name, ctx.related_headers[name]])[:12])
                found = {h["addr"] for h in ctx.matcher.scan(Path(trial["object"]).read_bytes())} if trial["ok"] else set()
                if not new <= found or keep - found or set(result.get("defined_symbols", ())).intersection(trial.get("undefined_symbols", ())):
                    ctx.related_headers[name] = kept
        final = ctx.compile(source, args.file, "paired-final")
        hits = ctx.matcher.scan(Path(final["object"]).read_bytes()) if final["ok"] else []
        found = {h["addr"] for h in hits}
        if not new <= found or keep - found or set(result.get("defined_symbols", ())).intersection(final.get("undefined_symbols", ())):
            raise SystemExit("paired edits lost their final proof; nothing saved")
        proposal["proof"] = dict(final, hits=hits, losses=[])
        proposal["witnesses"] = [h for h in hits if h["addr"] in new]
    for hit in proposal["witnesses"]:
        hit["claim_unit"] = native_sweep.claim_unit(hit, ctx.by_addr[hit["addr"]])
    rest = [p for p in saved() if p["file"] != args.file]
    # One proposal per file: saved edits first, then these (anchors were checked against that text).
    proposal["edits"] = edits + proposal["edits"]
    proposal["witnesses"] += previous
    proposal["base_revision"] = ctx.base_revision
    if getattr(ctx, "translation_unit", None):
        proposal["translation_unit"] = ctx.translation_unit
    if ctx.related_headers:
        proposal["related_headers"] = {name: pairs for name, pairs in ctx.related_headers.items() if pairs}
    if PROPOSALS.exists():
        archive = OUT / "archive" / ("before-check-" + integration.digest(PROPOSALS.read_text()) + ".json")
        if not archive.exists():
            integration.atomic_json(archive, json.loads(PROPOSALS.read_text()))
    integration.atomic_json(PROPOSALS, rest + [proposal])
    print("saved: %d edit(s) for %s" % (len(proposal["edits"]), ", ".join(w["addr"] for w in proposal["witnesses"])))


def cmd_preflight(args):
    native_sweep.require_private_workspace()
    from roc.rebuild_install import prepare
    prepare()
    context()  # sync the accepted baseline before combining saved recipes
    proposals = saved()
    if not proposals:
        raise ValueError("no saved proposals")
    additions = {}
    for proposal in proposals:
        for name, edits in dict(proposal.get("related_headers", {}), **{proposal["file"]: proposal["edits"]}).items():
            for edit in edits:
                if edit not in additions.setdefault(name, []):
                    additions[name].append(edit)
    from roc.integration_verify import linked_preflight
    receipt = linked_preflight(native_sweep.ROOT, additions, OUT, lambda message: print(message, flush=True))
    print(json.dumps(receipt, indent=1))


def cmd_submit(args):
    if not saved():
        raise SystemExit("no saved proposals")
    spec = {"client": "2008-06", "native_sweep": {"proposals_file": str(PROPOSALS), "apply": True, "submit": True,
                                                  "model": args.model, "wait": False}, "targets": {}}
    summary = native_sweep.run(spec, "native-try", output=OUT / "submit", log=lambda message: print(message, flush=True))
    print(json.dumps({k: summary.get(k) for k in ("state", "job", "applied_files", "local_exact", "reason", "blocked_units")}, indent=1))
    if not summary.get("job"):
        raise SystemExit("No submission queued; saved proposals retained")
    if summary.get("job"):
        submitted = set(summary["applied_paths"])
        proposals = saved()
        integration.atomic_json(PROPOSALS.with_name("submitted-%s.json" % summary["job"][:12]),
                                [p for p in proposals if p["file"] in submitted])
        remaining = [p for p in proposals if p["file"] not in submitted]
        if remaining:
            integration.atomic_json(PROPOSALS, remaining)
        else:
            PROPOSALS.unlink()
        native_sweep.restore_submitted_baseline(summary["job"])


def main(args):
    try:
        return dispatch(args)
    except ValueError as error:
        raise SystemExit(str(error)) from None


def dispatch(args):
    if args.action == "preflight":
        return cmd_preflight(args)
    if args.action == "submit":
        return cmd_submit(args)
    if args.action == "reset":
        if getattr(args, "file", None):
            remaining = [p for p in saved() if p["file"].casefold() != args.file.casefold()]
            if remaining:
                integration.atomic_json(PROPOSALS, remaining)
            else:
                PROPOSALS.unlink(missing_ok=True)
            return print("saved proposal cleared: " + args.file)
        PROPOSALS.unlink(missing_ok=True)
        return print("saved proposals cleared")
    if args.action in ("evidence", "check") and not args.file:
        raise ValueError(args.action + " requires a source FILE")
    ctx = context()
    if getattr(args, "file", None):
        registry = native_sweep.ROOT / "rebuild/2008-06/patches/rbxgs-client.json"
        if registry.exists():
            args.file = next(iter(integration.canonical_patches({args.file: []}, json.loads(registry.read_text()))))
    {"targets": cmd_targets, "evidence": cmd_evidence, "check": cmd_check}[args.action](ctx, args)


def register(cmd):
    cmd("native-try", main, "agent-driven native integration: targets, evidence, check, submit (docs/NATIVE_AGENT.md)",
        (["action"], {"choices": ["targets", "evidence", "check", "preflight", "submit", "reset"]}),
        (["file"], {"nargs": "?"}), (["blocks"], {"nargs": "?"}),
        (["--context"], {"choices": ["file", "methods"], "default": "file"}),
        (["--limit"], {"type": int, "default": 25}), (["--model"], {}),
        (["--min-score"], {"type": int, "default": 0}),
        (["--max-score"], {"type": int, "default": 100}),
        (["--brief"], {"action": "store_true", "help": "evidence: omit repeated rules and assembly; keep source, mined proof and diffs"}),
        (["--only"], {"help": "target addresses for evidence/check diagnostics; selects a header proof caller"}))

roc/native_try.py.text:
"""Agent-driven native integration: the DeepSeek native pass as four commands any agent (Codex, Claude) can drive.

  roc native-try targets [--limit N]            files whose rebuilt methods are exact-mined near misses
  roc native-try evidence FILE [--context ...] [--only ADDR,...]
                                                the exact prompt the model pass sends (rules, code, targets, diffs)
  roc native-try check FILE BLOCKS.txt          apply SEARCH/REPLACE blocks, compile the real file, report;
                                                a new exact with no loss is minimized and saved as a proposal
  roc native-try check FILE                     revalidate saved edits after syncing a new baseline
  roc native-try preflight                      independently build/link saved batch and run acceptance gates
  roc native-try submit --model MODEL           claim, stage and submit every saved proposal as one verified batch

Saved proposals live in work/native-try/proposals.json; later checks of a file build on its saved edits.
Contributor PCs without rebuild artifacts read the evidence from the server (/v1/integration/evidence).
Run it only in a private checkout: it writes rebuild/2008-06/out, and refuses the server's checkout.
`check` edits one source/header; header trials identify a real caller with --only ADDR."""
import hashlib
import json
import re
from pathlib import Path

from roc import integration, native_sweep, worker

OUT = native_sweep.ROOT / "work/native-try"
PROPOSALS = OUT / "proposals.json"


def context():
    # Every action writes the module overlay under rebuild/2008-06/out: never in the server's live checkout.
    native_sweep.require_private_workspace()
    settings = worker.load_settings()
    if not settings.get("server"):
        raise ValueError("Configure a server first: roc config --user NAME --server URL")
    api = worker.Api(settings["server"], integration.native_token() or settings.get("native_token") or settings.get("token"))
    try:
        base = api.call("/v1/integration/base")
        generator = native_sweep.ROOT / "rebuild/2008-06/patches/make_rbxgs_client.py"
        if hashlib.sha256(generator.read_bytes()).hexdigest() != base["generator"]:
            for snapshot in (native_sweep.ROOT / "work/integration-client/jobs").glob("*/submitted-generator.py"):
                original = snapshot.with_name("generator-base.py")
                if original.exists() and generator.read_bytes() == snapshot.read_bytes() and \
                        hashlib.sha256(original.read_bytes()).hexdigest() == base["generator"]:
                    native_sweep.restore_submitted_baseline(snapshot.parent.name)
                    break
        if hashlib.sha256(generator.read_bytes()).hexdigest() != base["generator"]:
            raise ValueError("Local baseline differs from server; run roc integrate sync first")
        if json.loads(generator.with_name("rbxgs-client.json").read_text()) != base["overlay"]:
            if not integration.sync_client_baseline(native_sweep.ROOT, base, only_if_clean=True):
                raise ValueError("Local baseline differs from server; preserve local edits and sync first (roc integrate sync)")
            print("accepted baseline advanced; clean local overlay refreshed", flush=True)
        integration.atomic_json(native_sweep.ROOT / "work/integration-client/baseline.json", base)
        ctx = native_sweep.native_context({}, api)
        ctx.base_revision = base["revision"]
    finally:
        api.close()
    ctx.compile = lambda source, rel, label: native_sweep.compile_unit(source, rel, label, OUT, ctx.tree, ctx.overlay,
                                                                       ctx.includes, ctx.defines, ctx.flags,
                                                                       translation_unit=getattr(ctx, "translation_unit", None),
                                                                       related_headers=getattr(ctx, "related_headers", None))
    return ctx


def saved():
    proposals = json.loads(PROPOSALS.read_text()) if PROPOSALS.exists() else []
    overlay = native_sweep.ROOT / "rebuild/2008-06/patches/rbxgs-client.json"
    base = json.loads(overlay.read_text()) if overlay.exists() else {}
    names = integration.canonical_patches({p["file"]: [] for p in proposals}, base)
    canonical = {name.casefold(): name for name in names}
    seen = set()
    for proposal in proposals:
        name = canonical[proposal["file"].casefold()]
        if name.casefold() in seen:
            raise ValueError("Duplicate saved source proposals: " + name)
        seen.add(name.casefold())
        proposal["file"] = name
        if "related_headers" in proposal:
            proposal["related_headers"] = integration.canonical_patches(proposal["related_headers"], base)
    return proposals


def file_state(ctx, rel):
    """(text with saved edits applied, saved edits, waiting near-miss targets, baseline exacts, baseline object)."""
    original = (ctx.overlay / rel if (ctx.overlay / rel).exists() else ctx.tree / rel).read_text(errors="replace")
    if not hasattr(ctx, "related_headers"):
        ctx.related_headers = next((p.get("related_headers", {}) for p in saved() if p["file"] == rel), {})
    edits = [pair for p in saved() if p["file"] == rel for pair in p["edits"]]
    text = native_sweep.apply_edits(original, edits) if edits else original
    wanted = ctx.targets - ctx.owned
    caller = getattr(ctx, "translation_unit", rel)
    caller_text = (ctx.overlay / caller if (ctx.overlay / caller).exists() else ctx.tree / caller).read_text(errors="replace") if caller != rel else text
    homes = native_sweep.target_files({caller: caller_text}, wanted, ctx.names, ctx.by_addr)
    base = ctx.compile(text, rel, "baseline")
    if not base["ok"]:
        raise SystemExit("baseline compile failed:\n" + base["error"][-2000:])
    data = Path(base["object"]).read_bytes()
    dependencies = Path(base["object"]).with_suffix(".deps")
    included = json.loads(dependencies.read_text()) if dependencies.exists() else []
    # Use compiler evidence: an accepted overlay can differ from the original tools header.
    ctx.evidence_headers = {name: paths for name in re.findall(r'^\s*#\s*include\s*"([^"]+)"', text, re.M)
                            if (paths := [path for path in included if path.replace("\\", "/").lower().endswith(
                                "/" + name.replace("\\", "/").lower())])}
    ctx.evidence_hits = ctx.matcher.scan(data)
    return text, edits, sorted(homes.get(caller, [])), {h["addr"] for h in ctx.evidence_hits}, data


def header_caller(ctx, args):
    if Path(args.file).suffix.lower() not in (".h", ".hpp", ".inl"):
        return
    previous = next((p for p in saved() if p["file"] == args.file), {})
    caller = previous.get("translation_unit")
    if not caller:
        selected = set((getattr(args, "only", None) or "").split(",")) - {""}
        if not selected:
            raise ValueError("Header trial needs --only ADDR to identify its real caller; saved trials remember it")
        texts = {p.relative_to(ctx.tree).as_posix():
                 (ctx.overlay / p.relative_to(ctx.tree) if (ctx.overlay / p.relative_to(ctx.tree)).exists() else p).read_text(errors="replace")
                 for p in ctx.tree.glob("App/*/*.cpp") if not p.name.startswith("roc_")}
        homes = native_sweep.target_files(texts, selected, ctx.names, ctx.by_addr)
        if not homes:
            raise ValueError("No native caller found for the selected header targets")
        caller = max(sorted(homes), key=lambda rel: len(homes[rel]))
    ctx.translation_unit = caller
    print("header proof caller: " + caller, flush=True)


def diff(ctx, obj, addr):
    symbol = ctx.names.get(addr, {}).get("symbol")
    return native_sweep.body_diff(obj, symbol, addr) if symbol else "no rebuilt body"


def cmd_targets(ctx, args):
    wanted = {a for a in ctx.targets - ctx.owned - getattr(ctx, "integrated", set())
              if getattr(args, "min_score", 0) <= ctx.names.get(a, {}).get("score", 0) <= getattr(args, "max_score", 100)}
    wanted -= {w["addr"] for proposal in saved() for w in proposal["witnesses"]}
    texts = {p.relative_to(ctx.tree).as_posix():
             (ctx.overlay / p.relative_to(ctx.tree) if (ctx.overlay / p.relative_to(ctx.tree)).exists() else p).read_text(errors="replace")
             for p in ctx.tree.glob("App/*/*.cpp") if not p.name.startswith("roc_")}
    homes = native_sweep.target_files(texts, wanted, ctx.names, ctx.by_addr)
    for rel in sorted(homes, key=lambda r: -len(homes[r]))[:args.limit]:
        print("%-48s %3d  %s" % (rel, len(homes[rel]), " ".join(homes[rel][:6])))


def cmd_evidence(ctx, args):
    header_caller(ctx, args)
    text, _, addrs, exact, data = file_state(ctx, args.file)
    if args.only:
        addrs = [a for a in addrs if a in args.only.split(",")]
    if not addrs:
        raise SystemExit("no waiting near-miss target in " + args.file)
    shown = native_sweep.excerpt(text, [ctx.names[a]["symbol"] for a in addrs if ctx.names.get(a, {}).get("symbol")]) if args.context == "methods" else text
    items = [dict(native_sweep.model_evidence(a, ctx.names, ctx.by_addr), current_diff=diff(ctx, data, a),
                  tu_code_and_data_exact=a in exact) for a in addrs[:6]]
    ownership = native_sweep.ownership_candidates(data, [h for h in getattr(ctx, "evidence_hits", []) if h["addr"] in addrs[:6]])
    for item in items:
        item["globally_integrated"] = item["addr"] in getattr(ctx, "integrated", set())
        if item["tu_code_and_data_exact"]:
            item["next_action"] = "Already exact in this translation unit; inspect linked ownership/provider before changing source. Server acceptance still required."
        if item["addr"] in ownership:
            item["code_candidates"] = ownership[item["addr"]]
            item["module_ownership_unique"] = ownership[item["addr"]] == [item["addr"]]
            if not item["module_ownership_unique"]:
                item["next_action"] = "Address-ambiguous body; current server ownership gate cannot credit this local exact."
        if item["globally_integrated"]:
            item["next_action"] = "Already independently integrated; changing another module's copy does not earn a new distinct credit."
    if getattr(args, "brief", False):
        for item in items:
            item.pop("target_asm", None)
        print("FILE %s\n```cpp\n%s\n```\nHEADERS (compiler-selected)\n%s\nTARGETS\n%s" %
              (args.file, shown, json.dumps(getattr(ctx, "evidence_headers", {}), indent=1), json.dumps(items, indent=1)))
    else:
        print("HEADERS (compiler-selected)\n" + json.dumps(getattr(ctx, "evidence_headers", {}), indent=1))
        print(native_sweep.model_prompt(args.file, shown, items))


def cmd_check(ctx, args):
    header_caller(ctx, args)
    previous_proposal = next((p for p in saved() if p["file"] == args.file), {})
    ctx.related_headers = {name: list(pairs) for name, pairs in previous_proposal.get("related_headers", {}).items()}
    text, edits, addrs, baseline, _ = file_state(ctx, args.file)
    previous = [w for p in saved() if p["file"] == args.file for w in p["witnesses"]]
    if not args.blocks and not previous:
        raise ValueError("check requires a blocks file, or saved edits to recheck")
    blocks = Path(args.blocks).read_text(encoding="utf-8-sig") if args.blocks else ""
    headers = {}
    if blocks.lstrip().startswith("{"):
        bundle = json.loads(blocks)
        if args.file not in bundle or Path(args.file).suffix.lower() != ".cpp":
            raise ValueError("Paired JSON edits need the primary CPP file and its header edits")
        new_edits = bundle.pop(args.file)
        headers = bundle
        for name, pairs in dict(headers, **{args.file: new_edits}).items():
            if name != args.file and Path(name).suffix.lower() not in (".h", ".hpp", ".inl"):
                raise ValueError("Related files must be headers")
            if not isinstance(pairs, list) or any(not isinstance(pair, list) or len(pair) != 2 or
                                                 not all(isinstance(value, str) for value in pair) for pair in pairs):
                raise ValueError("Paired edits must contain SEARCH/REPLACE string pairs")
        for name, pairs in headers.items():
            ctx.related_headers.setdefault(name, []).extend(pairs)
    else:
        new_edits = native_sweep.parse_edits(blocks) if blocks else []
    changed = bool(new_edits or headers)
    candidate = native_sweep.apply_edits(text, new_edits) if new_edits else text
    result = ctx.compile(candidate, args.file, "check")
    if not result["ok"]:
        raise SystemExit("compile failed:\n" + result["error"][-3000:])
    data = Path(result["object"]).read_bytes()
    hits = ctx.matcher.scan(data)
    found = {h["addr"] for h in hits}
    keep = baseline | {w["addr"] for w in previous}
    # Whole-TU proofs include real header instantiations; inventory file labels are only hints.
    new = (found & ctx.targets) - baseline - ctx.owned - getattr(ctx, "integrated", set())
    lost = keep - found
    ownership = native_sweep.ownership_candidates(data, [h for h in hits if h["addr"] in new])
    ambiguous = {a: candidates for a, candidates in ownership.items() if candidates != [a]}
    new -= ambiguous.keys()
    waiting = set(addrs) - found
    if getattr(args, "only", None):
        waiting &= set(args.only.split(","))
    diffs = {addr: diff(ctx, data, addr) for addr in
             sorted(lost or (waiting if not new and (changed or not previous) else set()))[:3]}
    report = Path(result["object"]).with_suffix(".evidence.json")
    integration.atomic_json(report, dict(file=args.file, base_revision=ctx.base_revision, proof=result,
                                        newly_exact=sorted(new), lost=sorted(lost), still_not_exact=sorted(waiting),
                                        ownership_candidates=ownership, current_diffs=diffs))
    if ambiguous:
        print("address-ambiguous local exacts (no unique module credit): " +
              json.dumps({a: len(candidates) for a, candidates in sorted(ambiguous.items())[:6]}) +
              ("; %d more targets (see evidence)" % (len(ambiguous) - 6) if len(ambiguous) > 6 else ""))
    print("newly exact: %s\nlost: %s\nstill not exact: %s" % (sorted(new) or "none", sorted(lost) or "none",
                                                             sorted(set(addrs) - found) or "none"))
    print("evidence: " + str(report))
    # Successful trials need only their gain/loss summary. On failure show regressions first,
    # rather than burying them under unrelated waiting methods.
    for addr, instructions in diffs.items():
        print("\n%s target vs rebuilt:\n%s" % (addr, instructions))
    if lost or (not new and (not previous or changed)):
        raise SystemExit(1)
    if new_edits:
        proposal = native_sweep.minimize(args.file, text, new_edits, new, keep,
                                         lambda source, label: ctx.compile(source, args.file, label), ctx.matcher, "check",
                                         allow_empty=bool(ctx.related_headers), definitions=result.get("defined_symbols", ()))
    else:
        proposal = dict(file=args.file, edits=[], mode="model", witnesses=[],
                        proof=dict(result, hits=ctx.matcher.scan(data), losses=[]))
    if not proposal:
        raise SystemExit("minimized edits lost the proof; nothing saved")
    if headers:
        source = native_sweep.apply_edits(text, proposal["edits"]) if proposal["edits"] else text
        for name, pairs in headers.items():
            for pair in list(pairs):
                kept = list(ctx.related_headers[name])
                ctx.related_headers[name].remove(pair)
                trial = ctx.compile(source, args.file, "minimize-header-" + native_sweep.integration.digest([name, ctx.related_headers[name]])[:12])
                found = {h["addr"] for h in ctx.matcher.scan(Path(trial["object"]).read_bytes())} if trial["ok"] else set()
                if not new <= found or keep - found or set(result.get("defined_symbols", ())).intersection(trial.get("undefined_symbols", ())):
                    ctx.related_headers[name] = kept
        final = ctx.compile(source, args.file, "paired-final")
        hits = ctx.matcher.scan(Path(final["object"]).read_bytes()) if final["ok"] else []
        found = {h["addr"] for h in hits}
        if not new <= found or keep - found or set(result.get("defined_symbols", ())).intersection(final.get("undefined_symbols", ())):
            raise SystemExit("paired edits lost their final proof; nothing saved")
        proposal["proof"] = dict(final, hits=hits, losses=[])
        proposal["witnesses"] = [h for h in hits if h["addr"] in new]
    for hit in proposal["witnesses"]:
        hit["claim_unit"] = native_sweep.claim_unit(hit, ctx.by_addr[hit["addr"]])
    rest = [p for p in saved() if p["file"] != args.file]
    # One proposal per file: saved edits first, then these (anchors were checked against that text).
    proposal["edits"] = edits + proposal["edits"]
    proposal["witnesses"] += previous
    proposal["base_revision"] = ctx.base_revision
    if getattr(ctx, "translation_unit", None):
        proposal["translation_unit"] = ctx.translation_unit
    if ctx.related_headers:
        proposal["related_headers"] = {name: pairs for name, pairs in ctx.related_headers.items() if pairs}
    if PROPOSALS.exists():
        archive = OUT / "archive" / ("before-check-" + integration.digest(PROPOSALS.read_text()) + ".json")
        if not archive.exists():
            integration.atomic_json(archive, json.loads(PROPOSALS.read_text()))
    integration.atomic_json(PROPOSALS, rest + [proposal])
    print("saved: %d edit(s) for %s" % (len(proposal["edits"]), ", ".join(w["addr"] for w in proposal["witnesses"])))


def cmd_preflight(args):
    native_sweep.require_private_workspace()
    from roc.rebuild_install import prepare
    prepare()
    context()  # sync the accepted baseline before combining saved recipes
    proposals = saved()
    if not proposals:
        raise ValueError("no saved proposals")
    additions = {}
    for proposal in proposals:
        for name, edits in dict(proposal.get("related_headers", {}), **{proposal["file"]: proposal["edits"]}).items():
            for edit in edits:
                if edit not in additions.setdefault(name, []):
                    additions[name].append(edit)
    from roc.integration_verify import linked_preflight
    receipt = linked_preflight(native_sweep.ROOT, additions, OUT, lambda message: print(message, flush=True))
    print(json.dumps(receipt, indent=1))


def cmd_submit(args):
    if not saved():
        raise SystemExit("no saved proposals")
    spec = {"client": "2008-06", "native_sweep": {"proposals_file": str(PROPOSALS), "apply": True, "submit": True,
                                                  "model": args.model, "wait": False}, "targets": {}}
    summary = native_sweep.run(spec, "native-try", output=OUT / "submit", log=lambda message: print(message, flush=True))
    print(json.dumps({k: summary.get(k) for k in ("state", "job", "applied_files", "local_exact", "reason", "blocked_units")}, indent=1))
    if not summary.get("job"):
        raise SystemExit("No submission queued; saved proposals retained")
    if summary.get("job"):
        submitted = set(summary["applied_paths"])
        proposals = saved()
        integration.atomic_json(PROPOSALS.with_name("submitted-%s.json" % summary["job"][:12]),
                                [p for p in proposals if p["file"] in submitted])
        remaining = [p for p in proposals if p["file"] not in submitted]
        if remaining:
            integration.atomic_json(PROPOSALS, remaining)
        else:
            PROPOSALS.unlink()
        native_sweep.restore_submitted_baseline(summary["job"])


def main(args):
    try:
        return dispatch(args)
    except ValueError as error:
        raise SystemExit(str(error)) from None


def dispatch(args):
    if args.action == "preflight":
        return cmd_preflight(args)
    if args.action == "submit":
        return cmd_submit(args)
    if args.action == "reset":
        if getattr(args, "file", None):
            remaining = [p for p in saved() if p["file"].casefold() != args.file.casefold()]
            if remaining:
                integration.atomic_json(PROPOSALS, remaining)
            else:
                PROPOSALS.unlink(missing_ok=True)
            return print("saved proposal cleared: " + args.file)
        PROPOSALS.unlink(missing_ok=True)
        return print("saved proposals cleared")
    if args.action in ("evidence", "check") and not args.file:
        raise ValueError(args.action + " requires a source FILE")
    ctx = context()
    if getattr(args, "file", None):
        registry = native_sweep.ROOT / "rebuild/2008-06/patches/rbxgs-client.json"
        if registry.exists():
            args.file = next(iter(integration.canonical_patches({args.file: []}, json.loads(registry.read_text()))))
    {"targets": cmd_targets, "evidence": cmd_evidence, "check": cmd_check}[args.action](ctx, args)


def register(cmd):
    cmd("native-try", main, "agent-driven native integration: targets, evidence, check, submit (docs/NATIVE_AGENT.md)",
        (["action"], {"choices": ["targets", "evidence", "check", "preflight", "submit", "reset"]}),
        (["file"], {"nargs": "?"}), (["blocks"], {"nargs": "?"}),
        (["--context"], {"choices": ["file", "methods"], "default": "file"}),
        (["--limit"], {"type": int, "default": 25}), (["--model"], {}),
        (["--min-score"], {"type": int, "default": 0}),
        (["--max-score"], {"type": int, "default": 100}),
        (["--brief"], {"action": "store_true", "help": "evidence: omit repeated rules and assembly; keep source, mined proof and diffs"}),
        (["--only"], {"help": "target addresses for evidence/check diagnostics; selects a header proof caller"}))

roc/rebuild.py.text:
"""2008-06 client rebuild: toolchain, audit, whole-file builds, TU diffs and links.

Separate from mining: nothing here edits src/, clients/, tools/ or bounds.json.
Outputs go to rebuild/<client>/ (manifests/ and out/ stay untracked until
rebuild/<client>/POLICY.md allows publishing them).
"""
import json
import hashlib
import functools
import inspect
import collections
import os
import re
import struct
import subprocess
import sys
import types
from pathlib import Path

from roc import match, setup

ROOT = Path(__file__).resolve().parent.parent
TOOLS = ROOT / "tools"
DOCS = ROOT / "docs"
BUILD = 21022  # the 2008-06 client's compiler (VS2008 RTM)


def workspace(client):
    path = ROOT / "rebuild" / client
    (path / "out").mkdir(parents=True, exist_ok=True)
    return path



def _ml():
    """The VS2008-era MASM used for small assembly stubs."""
    candidates = [
        ROOT / "tools" / "vc2008sp1" / "Microsoft" / "Visual C++ for Python" / "9.0" / "VC" / "bin" / "ml.exe",
        ROOT / "tools" / "vc2008rtm" / "Program Files" / "Microsoft Visual Studio 9.0" / "VC" / "bin" / "ml.exe",
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    found = next((p for p in (ROOT / "tools").rglob("ml.exe")), None)
    if found is None:
        raise RuntimeError("ml.exe not found")
    return found


def _first(*candidates):
    for c in candidates:
        if c and Path(c).exists():
            return Path(c)
    return None


def _ci(folder, name):
    """Case-insensitive child lookup (the SDK ships Kernel32.Lib)."""
    if not folder or not folder.is_dir():
        return None
    low = name.lower()
    return next((p for p in folder.iterdir() if p.name.lower() == low), None)


def sdk_roots(tools):
    """Discover installed SDKs once per tools tree, not once per compile batch."""
    return setup.toolchain_paths(tools)[1]


sdk_roots.cache_clear = setup.toolchain_paths.cache_clear
sdk_roots.cache_info = setup.toolchain_paths.cache_info


def toolchain(build=BUILD):
    """Paths for one period toolchain; None where a piece is missing. Never substitutes a newer build."""
    cl = setup.compilers().get(build)
    cl = Path(cl) if cl else None
    vc = cl.parents[1] if cl else None
    ide = cl.parents[2] / "Common7" / "IDE" if cl else None
    candidates = [Path(p) for p in os.environ.get("ROC_WINSDK", "").split(os.pathsep) if p]
    sdk = next((r for r in candidates if _ci(r / "Lib", "kernel32.lib")), None)
    if sdk is None:
        sdk = next((r for r in sdk_roots(TOOLS) if _ci(r / "Lib", "kernel32.lib")), None)
    atlmfc = _first(os.environ.get("ROC_ATLMFC"), TOOLS / "libs" / "mfc-9.0-rtm" / "atlmfc")
    return {
        "build": build,
        "cl": cl,
        "link": _first(vc / "bin" / "link.exe") if vc else None,
        "lib": _first(vc / "bin" / "lib.exe") if vc else None,
        "mspdb": _first(ide / "mspdb80.dll") if ide else None,
        "vc_include": _first(vc / "include") if vc else None,
        "vc_lib": _first(vc / "lib") if vc else None,
        "crt": _first(vc / "lib" / "msvcrt.lib") if vc else None,
        "sdk_include": _first(sdk / "Include") if sdk else None,
        "sdk_lib": _first(sdk / "Lib") if sdk else None,
        "rc": _ci(sdk / "Bin", "rc.exe") if sdk else None,
        "atlmfc_include": _first(atlmfc / "include") if atlmfc else None,
        "atlmfc_lib": _first(atlmfc / "lib") if atlmfc else None,
        "atls": _first(atlmfc / "lib" / "atls.lib") if atlmfc else None,
        "mfcs90": _first(atlmfc / "lib" / "mfcs90.lib") if atlmfc else None,
    }


def env(tc):
    """Process environment for cl/link/lib with the VC, SDK and ATL/MFC include and lib paths."""
    e = setup.cl_env(tc["cl"])
    e["INCLUDE"] = ";".join(str(p) for p in (tc["vc_include"], tc["atlmfc_include"], tc["sdk_include"]) if p)
    e["LIB"] = ";".join(str(p) for p in (tc["vc_lib"], tc["atlmfc_lib"], tc["sdk_lib"]) if p)
    return e


def run(tc, tool, args, cwd, timeout=600):
    """Run cl/link/lib (or a tool path such as ml.exe); returns (returncode, combined output)."""
    exe = tc[tool] if isinstance(tool, str) and tool in tc else Path(tool)
    cmd = setup.cl_command(exe) + [str(a) for a in args]  # Wine on Linux
    done = subprocess.run(cmd, cwd=cwd, env=env(tc), stdin=subprocess.DEVNULL, capture_output=True, text=True, errors="replace", timeout=timeout)
    return done.returncode, (done.stdout + done.stderr).strip()


REQUIRED = ("cl", "link", "lib", "mspdb", "vc_include", "crt", "sdk_include", "sdk_lib")


def doctor(client="2008-06", log=print):
    tc = toolchain()
    for key, value in tc.items():
        if key == "build":
            continue
        log("[%s] %-15s %s" % ("ok  " if value else ("MISS" if key in REQUIRED else "opt "), key, value or "-"))
    missing = [k for k in REQUIRED if not tc[k]]
    if missing:
        log("Missing required pieces: " + ", ".join(missing))
        return False
    ok, text = smoke(client, tc)
    log(("[ok  ] smoke exe runs: %s" if ok else "[FAIL] smoke: %s") % text)
    return ok


SMOKE = r"""#include <windows.h>
#include <stdio.h>
int main()
{
    OSVERSIONINFOA info = { sizeof(info) };
    GetVersionExA(&info);
    printf("rebuild-smoke %d\n", _MSC_FULL_VER);
    return info.dwMajorVersion > 0 ? 0 : 1;
}
"""


def smoke(client, tc=None):
    """Compile and link a tiny PE32 console exe with the period toolchain, then run it."""
    tc = tc or toolchain()
    out = workspace(client) / "out" / "smoke"
    out.mkdir(parents=True, exist_ok=True)
    (out / "smoke.cpp").write_text(SMOKE)
    code, text = run(tc, "cl", ["/nologo", "/O2", "/MD", "/EHsc", "/c", "smoke.cpp"], out)
    if code:
        return False, "compile failed: " + text[-400:]
    code, text = run(tc, "link", ["/nologo", "/SUBSYSTEM:CONSOLE", "/MACHINE:X86", "smoke.obj", "kernel32.lib",
                                  "/OUT:smoke.exe", "/MAP:smoke.map"], out)
    if code:
        return False, "link failed: " + text[-400:]
    try:
        done = subprocess.run([str(out / "smoke.exe")] if setup.WINDOWS else [setup.wine_exe(), str(out / "smoke.exe")],
                              stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=60)
    except OSError as error:
        return False, "run failed: %s (the VC90 CRT msvcr90.dll must be loadable)" % error
    return done.returncode == 0 and "rebuild-smoke 1500" in done.stdout, done.stdout.strip() or done.stderr.strip()


# ---------- Phase 2: read-only audit ----------

def _source_kind(source):
    lib = match.directives(source or "").get("lib", "")
    recipe, _, rel = lib.partition(" ")
    rel = rel.strip().replace("\\", "/")
    if not recipe:
        return ("snippet" if source else "none"), None, None
    return ("generated-unit" if rel.rsplit("/", 1)[-1].startswith("roc_") else "vendor-file"), recipe, rel


def _dump(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=1, sort_keys=True) + "\n", encoding="utf-8")


def audit(client="2008-06", rows=None, log=print):
    """Write manifests/{original-pe,functions,tu-coverage}.json. rows: [{addr, score, source}] (server sources)."""
    import hashlib
    import pefile
    from roc import clients, worker
    entry = clients.load()[client]
    exe = clients.exe_path(client, entry)
    pe = pefile.PE(str(exe))
    out = workspace(client) / "manifests"
    imports = {}
    for d in getattr(pe, "DIRECTORY_ENTRY_IMPORT", []):
        imports[d.dll.decode()] = sorted((i.name.decode() if i.name else "#%d" % i.ordinal) for i in d.imports)
    _dump(out / "original-pe.json", {
        "sha256": hashlib.sha256(Path(exe).read_bytes()).hexdigest(),
        "image_base": "%08x" % pe.OPTIONAL_HEADER.ImageBase,
        "entry_point": "%08x" % (pe.OPTIONAL_HEADER.ImageBase + pe.OPTIONAL_HEADER.AddressOfEntryPoint),
        "sections": [{"name": s.Name.rstrip(b"\0").decode(), "va": "%08x" % (pe.OPTIONAL_HEADER.ImageBase + s.VirtualAddress),
                      "size": s.Misc_VirtualSize} for s in pe.sections],
        "imports": imports,
        "tls": hasattr(pe, "DIRECTORY_ENTRY_TLS"),
    })
    if rows is None:
        s = worker.load_settings()
        api = worker.Api(s["server"], s.get("token"))
        try:
            rows = api.call("/v1/sources?client=" + client, timeout=300)
        finally:
            api.close()
    by_addr = {r["addr"]: r for r in rows}
    functions, files = [], {}
    for addr, f in sorted(match._functions(client).items()):
        if f.get("kind", "code") != "code":
            continue
        row = by_addr.get(addr, {})
        source = row.get("source") or ""
        kind, recipe, rel = _source_kind(source)
        d = match.directives(source)
        functions.append({"addr": addr, "size": f["size"], "unit": f.get("unit"), "score": row.get("score", 0),
                          "source_kind": kind, "recipe": recipe, "file": rel, "cl": d.get("cl"), "flags": d.get("flags")})
        if recipe:
            tu = files.setdefault("%s|%s" % (recipe, rel), {"recipe": recipe, "file": rel, "kind": kind,
                                                              "exact": [], "open": [], "flags": set(), "cl": set()})
            tu["exact" if row.get("score") == 100 else "open"].append(addr)
            tu["flags"].add(d.get("flags") or "")
            tu["cl"].add(d.get("cl") or "")
    coverage = []
    for tu in files.values():
        tu.update(flags=sorted(tu["flags"]), cl=sorted(tu["cl"]), exact_count=len(tu["exact"]), open_count=len(tu["open"]))
        coverage.append(tu)
    coverage.sort(key=lambda t: (-t["exact_count"], t["open_count"], t["file"]))
    _dump(out / "functions.json", functions)
    _dump(out / "tu-coverage.json", coverage)
    kinds = {}
    for f in functions:
        key = (f["source_kind"], f["score"] == 100)
        kinds[key] = kinds.get(key, 0) + 1
    log("%s: %d code functions; %s" % (client, len(functions), ", ".join(
        "%s %s=%d" % (k, "exact" if e else "open", n) for (k, e), n in sorted(kinds.items()))))
    log("%d source files/units referenced; manifests in %s" % (len(coverage), out))
    abi_evidence(client, log=log)
    return coverage


def abi_evidence(client="2008-06", log=print):
    """Write manifests/abi-evidence.json from the original exe alone: per vtable class (work/<client>/vtables.json),
    the functions that store its vtables and at which `this` offsets (constructors/destructors: subobject layout),
    the vbtables those functions store, and the allocation sizes passed to malloc/operator new right before a call
    to one of those functions. Every entry is an observation of the binary (confidence "observed")."""
    import struct
    import pefile
    from capstone import Cs, CS_ARCH_X86, CS_MODE_32
    from capstone.x86_const import X86_OP_IMM, X86_OP_MEM
    from roc import clients
    exe = clients.exe_path(client, clients.load()[client])
    pe = pefile.PE(str(exe))
    base = pe.OPTIONAL_HEADER.ImageBase
    image = pe.get_memory_mapped_image()
    vtables = json.loads((ROOT / "work" / client / "vtables.json").read_text())
    owner = {int(v["vtable"], 16): v["class"] for v in vtables}
    allocators = {i.address for d in getattr(pe, "DIRECTORY_ENTRY_IMPORT", []) for i in d.imports
                  if i.name in (b"malloc", b"??2@YAPAXI@Z")}
    md = Cs(CS_ARCH_X86, CS_MODE_32)
    md.detail = True
    stores, vbtables, calls = {}, {}, []  # fn -> [(off, vt)], vbtable addr -> entries, (caller, size, callee)
    for addr, f in sorted(match._functions(client).items()):
        if f.get("kind", "code") != "code":
            continue
        start = int(addr, 16)
        pending = None  # size pushed for an allocation, until the allocation's result is passed to a call
        last_push, allocated = None, None
        for ins in md.disasm(image[start - base:start - base + f["size"]], start):
            ops = ins.operands
            if ins.mnemonic == "mov" and len(ops) == 2 and ops[0].type == X86_OP_MEM and ops[1].type == X86_OP_IMM \
                    and ops[0].size == 4:
                imm = ops[1].imm & 0xffffffff
                if imm in owner:
                    stores.setdefault(start, []).append((ops[0].mem.disp, imm, ins.reg_name(ops[0].mem.base) if ops[0].mem.base else ""))
                elif base <= imm < base + len(image) - 16 and ops[0].mem.index == 0:
                    first = struct.unpack_from("<i", image, imm - base)[0]
                    if first == -ops[0].mem.disp and first <= 0:
                        entries = list(struct.unpack_from("<4i", image, imm - base))
                        n = 1
                        while n < len(entries) and 0 < entries[n] < 0x10000:
                            n += 1
                        vbtables.setdefault(imm, {"fn": set(), "at": ops[0].mem.disp, "entries": entries[:n]})["fn"].add(start)
            elif ins.mnemonic == "push" and ops and ops[0].type == X86_OP_IMM:
                last_push = ops[0].imm & 0xffffffff
            elif ins.mnemonic == "call" and ops:
                target = ops[0].imm if ops[0].type == X86_OP_IMM else (
                    ops[0].mem.disp & 0xffffffff if ops[0].type == X86_OP_MEM and not ops[0].mem.base else None)
                if target in allocators and last_push is not None:
                    allocated = last_push
                elif allocated is not None and ops[0].type == X86_OP_IMM:
                    calls.append((start, allocated, target))
                    allocated = None
                last_push = None
    classes = {}
    for fn, items in stores.items():
        for off, vt, reg in items:
            c = classes.setdefault(owner[vt], {"vtables": set(), "vptr_stores": {}, "alloc_sizes": {}, "vbtables": {}})
            c["vtables"].add("%08x" % vt)
            c["vptr_stores"].setdefault("%08x" % fn, set()).add((reg, off, "%08x" % vt))
    for vb, item in vbtables.items():
        for fn in item["fn"]:
            for vt in {vt for _, vt, _ in stores.get(fn, [])}:
                classes[owner[vt]]["vbtables"]["%08x" % vb] = {"at": item["at"], "entries": item["entries"]}
    for caller, size, callee in calls:
        # the allocated object is the callee's `this`: the base register most of its vptr stores go through
        # (an inlined `new` of another class inside the constructor stores through another register)
        regs = [reg for _, _, reg in stores.get(callee, [])]
        this = max(sorted(set(regs)), key=regs.count) if regs else None
        for vt in {vt for off, vt, reg in stores.get(callee, []) if off == 0 and reg == this}:
            classes[owner[vt]]["alloc_sizes"].setdefault("0x%x" % size, set()).add("%08x" % caller)
    out = {}
    for name, c in sorted(classes.items()):
        out[name] = {"confidence": "observed", "vtables": sorted(c["vtables"]),
                     "vptr_stores": {fn: [["[%s+0x%x]" % (reg, off), vt] for reg, off, vt in sorted(v)] for fn, v in sorted(c["vptr_stores"].items())},
                     "alloc_sizes": {s: sorted(v) for s, v in sorted(c["alloc_sizes"].items())},
                     "vbtables": dict(sorted(c["vbtables"].items()))}
    _dump(workspace(client) / "manifests" / "abi-evidence.json", out)
    log("%s: abi evidence for %d vtable classes (%d with allocation sizes, %d with vbtables)"
        % (client, len(out), sum(1 for c in out.values() if c["alloc_sizes"]), sum(1 for c in out.values() if c["vbtables"])))
    return out


# ---------- Phase 3: whole-file build + TU diff ----------

def tu_source(recipe, rel, cl=BUILD, flags="/O2 /Ob2 /Oy /GF /GS- /EHsc /MD"):
    """The mining wrapper that compiles one authentic file whole, exactly as its exacts were verified."""
    return "// roc-cl: %s\n// roc-flags: %s\n// roc-lib: %s %s\n" % (cl, flags, recipe, rel)


def tu_diff(client, tu, log=print):
    """Compile one coverage row's file whole; pair each object function with the 2008 address it matches.
    Returns {obj, functions: [{symbol, size, addr|None, status}], exact, total}."""
    flags = tu["flags"][0] if tu["flags"] and tu["flags"][0] else "/O2 /Ob2 /Oy /GF /GS- /EHsc /MD"
    cl = int(tu["cl"][0]) if tu["cl"] and tu["cl"][0] else BUILD
    obj = match.compile_text(client, tu_source(tu["recipe"], tu["file"], cl, flags))
    funcs = match.coff_functions(obj)
    targets = {}
    for addr in tu["exact"] + tu["open"]:
        code, relocs, _ = match.target(client, addr)
        targets[addr] = (code, relocs)
    rows, owned, generic = [], set(), set()
    for name, body, relocs in funcs:
        hits = [a for a, (code, trel) in targets.items()
                if len(code) == len(body) and match.exact_match(code, trel, body, relocs)]
        status = "owned" if len(hits) == 1 else ("generic-shape" if hits else "not-in-2008-or-differs")
        (owned if len(hits) == 1 else generic).update(hits)
        rows.append({"symbol": name, "size": len(body), "addrs": hits, "status": status})
    generic -= owned
    missing = sorted(set(targets) - owned - generic)
    report = {"recipe": tu["recipe"], "file": tu["file"], "cl": cl, "flags": flags, "functions": rows,
              "owned": sorted(owned), "generic_shape_addrs": sorted(generic), "unpaired_targets": missing,
              "object_functions": len(funcs)}
    log("%s %s: %d object functions; %d 2008 addresses owned 1:1, %d only via a generic shape, %d unpaired"
        % (tu["recipe"], tu["file"], len(funcs), len(owned), len(generic), len(missing)))
    return obj, report


_INDEX = {}


def size_index(client):
    """{size: [(addr, code, relocs)]} over every code function of the client (built once per process)."""
    if client not in _INDEX:
        _paired_addresses.cache_clear()
        idx = {}
        for addr, f in match._functions(client).items():
            if f.get("kind", "code") == "code":
                code, relocs, _ = match.target(client, addr)
                idx.setdefault(len(code), []).append((addr, code, relocs))
        _INDEX[client] = idx
    return _INDEX[client]


@functools.lru_cache(maxsize=16384)
def _paired_addresses(client, body, relocs):
    """Template bodies recur across TUs; cache immutable matches, including twins."""
    return tuple(a for a, code, trel in _INDEX[client].get(len(body), ())
                 if match.exact_match(code, trel, body, relocs))


def pair(client, funcs):
    """[(symbol, size, [2008 addrs whose masked bytes equal it])] against the whole binary."""
    size_index(client)
    return [(name, len(body), list(_paired_addresses(client, body, tuple(relocs))))
            for name, body, relocs in funcs]


def _code_edges(obj, functions, index):
    """Unadjusted direct calls/jumps and pushed callbacks defined in this object."""
    sections, symbols, locations, _ = index
    edges = {}
    for symbol, (body, _) in functions.items():
        value, section = locations[symbol]
        header = sections[section]
        refs = []
        for n in range(header[7]):
            at, ref, kind = struct.unpack_from('<IIH', obj, header[5] + n*10)
            offset = at-value
            if not 1 <= offset <= len(body)-4 or struct.unpack_from('<i', body, offset)[0]:
                continue
            callee = symbols[ref][0]
            if callee not in functions:
                continue
            if kind == 20 and body[offset-1] in (0xe8, 0xe9):
                refs.append((offset, callee, True))
            elif kind == 6 and body[offset-1] == 0x68:
                refs.append((offset, callee, False))
        edges[symbol] = refs
    return edges


def pair_object(client, obj, symbols=None):
    """Whole-binary code/data matches, refined only by proven local callee addresses."""
    functions = {s:(b,r) for s,b,r in match.coff_functions(obj)}
    requested = set(functions) if symbols is None else set(functions).intersection(symbols)
    if not requested:
        return []
    index = match._coff_data_index(obj)
    edges = _code_edges(obj, functions, index)
    active, pending = set(requested), list(requested)
    while pending:
        for _, callee, _ in edges[pending.pop()]:
            if callee not in active:
                active.add(callee)
                pending.append(callee)
    rows = pair(client, [(s,b,r) for s,(b,r) in functions.items() if s in active])
    matches, known, data_state = {}, {}, {}
    for symbol, size, addresses in rows:
        data_state[symbol] = {}
        qualified, complete = [], {}
        if addresses:
            refs = match.coff_data_refs(obj, symbol, index=index)
            if not refs:
                matches[symbol] = addresses
                data_state[symbol] = {a:True for a in addresses}
                continue
            for address in addresses:
                code, _, _ = match.target(client, address)
                checked, bad = match.data_check(client, address, code, refs)
                data_state[symbol][address] = False if bad else True if len(checked) == len(refs) else None
                if not bad:
                    qualified.append(address)
                    complete[address] = len(checked) == len(refs)
            # Missing target data must not turn code twins into a unique owner.
            if len(addresses) > 1 and len(qualified) == 1 and not complete[qualified[0]]:
                qualified = addresses
            if len(qualified) == 1 and complete[qualified[0]]:
                known[symbol] = qualified[0]
        matches[symbol] = qualified
    # Only earlier proofs seed each round. Cycles cannot bootstrap ownership.
    for _ in range(len(rows)):
        added = {}
        unresolved = {s for s in matches if len(matches[s]) > 1}
        for symbol, _, _ in rows:
            if symbol in known or len(matches[symbol]) < 2:
                continue
            # Resolve ambiguous local dependencies first; a partial proof must
            # not become an anchor before another callee can contradict it.
            if any(callee in unresolved and callee not in known for _,callee,_ in edges[symbol]):
                continue
            constraints = [e for e in edges[symbol] if e[1] in known]
            if not constraints:
                continue
            qualified = []
            for address in matches[symbol]:
                if data_state[symbol][address] is False:
                    continue
                code, _, _ = match.target(client, address)
                for offset, callee, relative in constraints:
                    destination = (int(address,16)+offset+4+struct.unpack_from('<i',code,offset)[0]
                                   if relative else struct.unpack_from('<I',code,offset)[0])
                    if destination != int(known[callee],16):
                        break
                else:
                    qualified.append(address)
            if len(qualified) == 1 and data_state[symbol][qualified[0]] is None:
                continue  # Callees cannot waive unavailable referenced-data proof.
            matches[symbol] = qualified
            if len(qualified) == 1:
                added[symbol] = qualified[0]
        if not added:
            break
        known.update(added)
    return [(s,n,matches[s]) for s,n,_ in rows if s in requested]


def _ownership_code(value):
    """Stable loaded-code identity, independent of marshal reference flags or set order."""
    if isinstance(value, types.CodeType):
        return [value.co_code.hex(), getattr(value, "co_exceptiontable", b"").hex(),
                value.co_names, value.co_varnames, value.co_freevars, value.co_cellvars,
                value.co_argcount, value.co_posonlyargcount, value.co_kwonlyargcount,
                value.co_nlocals, value.co_flags, [_ownership_code(c) for c in value.co_consts]]
    if isinstance(value, (tuple, frozenset)):
        items = [_ownership_code(v) for v in value]
        return [type(value).__name__, sorted(items, key=repr) if isinstance(value, frozenset) else items]
    return [type(value).__name__, value.hex() if isinstance(value, bytes) else repr(value)]


def _ownership_context(client):
    """Fingerprint the actual matcher inputs and loaded implementation once per build."""
    digest = hashlib.sha256(b"native-ownership-cache-v2")
    base, image = match._image(client)
    digest.update(str((sys.version, base)).encode())
    digest.update(image)
    digest.update(json.dumps(match._functions(client), sort_keys=True).encode())
    digest.update(json.dumps(sorted(match._base_relocs(client))).encode())
    # Hash loaded code, not files another process may have edited since import.
    for module in (match, sys.modules[__name__]):
        for name, value in sorted(vars(module).items()):
            function = inspect.unwrap(value)
            if inspect.isfunction(function) and function.__module__ == module.__name__:
                digest.update(name.encode())
                digest.update(json.dumps(_ownership_code(function.__code__)).encode())
    # A changed functions table/image must also retire the process-local index.
    _INDEX.pop(client, None)
    _paired_addresses.cache_clear()
    return digest.hexdigest()


def _ownership_rows(client, obj, cache, context):
    """Reuse only complete object proofs for identical code, data and target context."""
    from roc.integration import atomic_json, digest
    body = obj.read_bytes()
    key = hashlib.sha256(context.encode() + body).hexdigest()
    try:
        saved = json.loads(cache.read_text(encoding="utf-8"))
        rows = saved["rows"]
        if (saved["key"] == key and saved["digest"] == digest(rows)
                and isinstance(rows, list)
                and all(isinstance(row, list) and len(row) == 3
                        and isinstance(row[0], str) and type(row[1]) is int
                        and isinstance(row[2], list)
                        and all(isinstance(a, str) and re.fullmatch(r"[0-9a-f]{8}", a)
                                for a in row[2]) for row in rows)):
            return [(s, n, addresses) for s, n, addresses in rows], True
    except (OSError, ValueError, KeyError, TypeError):
        pass
    rows = pair_object(client, body)
    atomic_json(cache, {"key": key, "rows": rows, "digest": digest(rows)})
    return rows, False


def _forced_owned_symbols(client, linked, cache_dir, context):
    """Force the external symbols that the ownership report actually credits."""
    selected = set()
    for obj in linked.glob("*.obj"):
        external = coff_externals(obj.read_bytes())
        rows, _ = _ownership_rows(client, obj, cache_dir / (obj.name + ".json"), context)
        selected.update(sym for sym, _, addresses in rows if len(addresses) == 1 and external.get(sym))
    return selected


def build_library(client, recipe, files, flags, name, cl=BUILD, jobs=6, log=print):
    """Compile each authentic file whole into out/<name>/, archive <name>.lib, and write <name>.tudiff.json."""
    import concurrent.futures as cf
    out = workspace(client) / "out" / name
    out.mkdir(parents=True, exist_ok=True)

    from roc import libs

    def one(rel):
        try:
            obj = match.compile_text(client, libs.source_for(recipe, rel, None, cl, flags))
        except match.CompileError as error:
            return rel, None, str(error)[:300]
        path = out / (Path(rel).stem + ".obj")
        path.write_bytes(obj)
        return rel, path, None

    with cf.ThreadPoolExecutor(jobs) as pool:
        built = list(pool.map(one, files))
    objs = [p for _, p, e in built if p]
    errors = {rel: e for rel, _, e in built if e}
    tc = toolchain(cl)
    lib_name = Path(name).name + ".lib"
    code, text = run(tc, "lib", ["/nologo", "/OUT:" + lib_name] + [p.name for p in objs], out)
    report = {"recipe": recipe, "flags": flags, "cl": cl, "files": {}, "compile_errors": errors,
              "lib": str(out / lib_name) if code == 0 else None, "lib_output": text[-500:]}
    owned_total = generic_total = 0
    for rel, path, err in built:
        if not path:
            continue
        rows = pair(client, match.coff_functions(path.read_bytes()))
        owned = sorted({a for _, _, hits in rows if len(hits) == 1 for a in hits})
        generic = sorted({a for _, _, hits in rows if len(hits) > 1 for a in hits} - set(owned))
        owned_total += len(owned)
        generic_total += len(generic)
        report["files"][rel] = {"object_functions": len(rows), "owned": owned, "generic_shape": generic,
                                "symbols": [{"symbol": s, "size": n, "addrs": h} for s, n, h in rows]}
    report.update(owned=owned_total, generic=generic_total)
    _dump(out / (Path(name).name + ".tudiff.json"), report)
    log("%s: %d/%d files compiled, lib %s; %d 2008 functions owned 1:1, %d via generic shapes"
        % (name, len(objs), len(files), "ok" if report["lib"] else "FAILED", owned_total, generic_total))
    return report


def unresolved_symbols(text):
    """Decorated names from LNK2001/LNK2019 lines (C++: the parenthesised name after the quoted one; C: bare)."""
    return [a or b for a, b in re.findall(r'unresolved external symbol (?:"[^"]*" \(([^)]+)\)|([?\w@$]+))', text)]


# #pragma comment(lib) names vendor headers ask for; rebuilt modules supply that code instead
VENDOR_AUTOLINK = ("zlib.lib", "G3D.lib", "GLG3D.lib", "sdl.lib", "sdlmain.lib", "glut32.lib", "ToolkitPro1122vc90DS.lib",
                   "ToolkitPro1122vc90S.lib", "ToolkitPro1122vc90LDS.lib")


def link_test(client, test, libs, includes=(), defines="WIN32 NDEBUG _MBCS _CRT_SECURE_NO_WARNINGS", flags="/O2 /GS- /EHsc /MD",
              system_libs=("kernel32.lib", "user32.lib", "gdi32.lib", "advapi32.lib", "shell32.lib", "ole32.lib",
                           "oleaut32.lib", "comdlg32.lib", "ws2_32.lib", "winmm.lib", "opengl32.lib", "glu32.lib"), cl=BUILD, run_args=(), library_symbols=()):
    """Compile tests/<test>.cpp, link it against rebuilt libs with the period linker, run it.
    Returns dict(compiled, linked, ran, exit, output, unresolved, map)."""
    tc = toolchain(cl)
    ws = workspace(client)
    out = ws / "out" / "tests" / test
    out.mkdir(parents=True, exist_ok=True)
    src = ws / "tests" / (test + ".cpp")
    args = ["/nologo", "/c"] + flags.split() + ["/D" + d for d in defines.split()] + ["/I" + str(i) for i in includes]
    code, text = run(tc, "cl", args + ["/Fo" + test + ".obj", str(src)], out)
    result = {"compiled": code == 0, "linked": False, "ran": False, "exit": None, "output": text[-1500:], "unresolved": []}
    if code:
        return result
    if library_symbols:
        obj = out / (test + ".obj")
        obj.write_bytes(strip_symbols(obj.read_bytes(), drop=library_symbols))
    code, text = run(tc, "link", ["/nologo", "/SUBSYSTEM:CONSOLE", "/MACHINE:X86", "/MAP:%s.map" % test,
                                  "/OUT:%s.exe" % test, test + ".obj"] + [str(l) for l in libs] + list(system_libs)
                       + ["imagehlp.lib", "version.lib", "wininet.lib", "dbghelp.lib", "psapi.lib"] + ["/NODEFAULTLIB:" + l for l in VENDOR_AUTOLINK], out)
    result["unresolved"] = sorted(set(unresolved_symbols(text)))
    result["duplicates"] = sorted(set(re.findall(r"\((\?[^)]+)\) already defined in", text)))
    result["referencers"] = sorted(set(a or b for a, b in re.findall(r'referenced in function (?:"[^"]*" \((\?[^)]+)\)|(_\w+))', text)))
    result.update(linked=code == 0, output=text[-1500:], map=str(out / (test + ".map")))
    if code:
        return result
    done = subprocess.run([str(out / (test + ".exe"))] + list(run_args), stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=300)
    result.update(ran=True, exit=done.returncode, output=(done.stdout + done.stderr).strip()[-1500:])
    return result


def defined_symbols(obj_path):
    return {name for name, _, _ in match.coff_functions(Path(obj_path).read_bytes())}


def coff_externals(data):
    """{name: defined} for the external (class 2) symbols of a COFF object."""
    import struct
    _, _, _, symptr, nsym, _, _ = struct.unpack_from("<HHIIIHH", data, 0)
    strtab, out, i = symptr + nsym * 18, {}, 0
    while i < nsym:
        raw, _, secnum, _, cls, naux = struct.unpack_from("<8sIhHBB", data, symptr + 18 * i)
        if cls == 2:
            if raw[:4] == b"\0\0\0\0":
                start = strtab + struct.unpack_from("<I", raw, 4)[0]
                name = data[start:data.index(b"\0", start)]
            else:
                name = raw.rstrip(b"\0")
            name = name.decode("latin-1")
            out[name] = out.get(name, False) or secnum > 0
        i += 1 + naux
    return out


def _coff_closure(data, roots, external=frozenset()):
    """Sections, external names and symbol indices reachable from selected definitions."""
    import struct
    _, nsec, _, symptr, nsym, optsz, _ = struct.unpack_from("<HHIIIHH", data)
    strtab = symptr + nsym * 18
    sections = [struct.unpack_from("<8sIIIIIIHHI", data, 20 + optsz + 40 * i) for i in range(nsec)]
    symbols, weak, children, pending, i = {}, {}, {}, [], 0
    while i < nsym:
        raw, value, section, typ, storage, aux = struct.unpack_from("<8sIhHBB", data, symptr + 18 * i)
        if raw[:4] == b"\0\0\0\0":
            start = strtab + struct.unpack_from("<I", raw, 4)[0]
            name = data[start:data.index(b"\0", start)].decode("latin-1")
        else:
            name = raw.rstrip(b"\0").decode("latin-1")
        symbols[i] = (section, storage, name)
        if section > 0 and name in roots:
            pending.append(section)
        if storage == 105 and aux:  # weak external's fallback symbol
            weak[i] = struct.unpack_from("<I", data, symptr + 18 * (i + 1))[0]
        if storage == 3 and aux and section > 0 and value == 0:
            parent, selection = struct.unpack_from("<HB", data, symptr + 18 * (i + 1) + 12)
            if selection == 5:
                children.setdefault(parent, []).append(section)
        i += 1 + aux
    for index, (_, _, name) in symbols.items():
        if name not in roots or index not in weak:
            continue
        target, seen = index, set()
        while target in weak and target not in seen:
            seen.add(target)
            target = weak[target]
        section = symbols.get(target, (0,))[0]
        if section > 0:
            pending.append(section)
    definitions = {name: section for section, storage, name in symbols.values() if section > 0 and storage == 2}
    reached = set()
    while pending:
        section = pending.pop()
        if section in reached:
            continue
        reached.add(section)
        pending.extend(children.get(section, ()))
        descriptor = sections[section - 1]
        for i in range(descriptor[7]):
            target = struct.unpack_from("<I", data, descriptor[5] + 10 * i + 4)[0]
            seen = set()
            while target in weak and target not in seen:
                seen.add(target)
                target = weak[target]
            target_section, storage, target_name = symbols.get(target, (0, 0, ""))
            if storage == 2 and target_section == 0:
                target_section = definitions.get(target_name, 0)
            if target_section > 0 and not (storage == 2 and target_name in external):
                pending.append(target_section)
    return (reached, {name for section, storage, name in symbols.values() if section in reached and storage == 2},
            {i for i, (section, _, name) in symbols.items() if section in reached or name in roots})

def _coff_subset(data, roots, external=frozenset()):
    """Compact a real COFF dependency closure, remapping sections and symbol indices."""
    import struct
    reached, names, safe = _coff_closure(data, roots, external)
    _, nsec, _, symptr, nsym, optsz, _ = struct.unpack_from("<HHIIIHH", data)
    strtab = symptr + nsym * 18
    sections = [list(struct.unpack_from("<8sIIIIIIHHI", data, 20 + optsz + 40 * i)) for i in range(nsec)]
    retained = sorted(reached | {i + 1 for i, section in enumerate(sections)
                                if section[0].rstrip(b"\0") in {b".drectve", b".sxdata"}})
    # An empty SafeSEH table makes the VS2008 linker reject the object (LNK1236)
    # or crash during archive lookup (LNK1000). Keep it only for live handlers.
    retained = [index for index in retained if sections[index - 1][0].rstrip(b"\0") != b".sxdata"
                or any(symbol in safe for symbol in struct.unpack(
                    "<%dI" % (sections[index - 1][3] // 4),
                    data[sections[index - 1][4]:sections[index - 1][4] + sections[index - 1][3]]))]
    section_ids = {old: new + 1 for new, old in enumerate(retained)}
    records, i = {}, 0
    while i < nsym:
        _, _, section, _, storage, aux = struct.unpack_from("<8sIhHBB", data, symptr + 18 * i)
        records[i] = (bytearray(data[symptr + 18 * i:symptr + 18 * (i + 1 + aux)]), section, storage, aux)
        i += 1 + aux
    wanted = set(safe)
    for section_id in retained:
        section = sections[section_id - 1]
        for i in range(section[7]):
            wanted.add(struct.unpack_from("<I", data, section[5] + 10 * i + 4)[0])
    pending = list(wanted)
    while pending:
        index = pending.pop()
        record, _, storage, aux = records[index]
        if storage == 105 and aux:
            fallback = struct.unpack_from("<I", record, 18)[0]
            if fallback not in wanted:
                wanted.add(fallback)
                pending.append(fallback)
    indices, count = {}, 0
    for index in sorted(wanted):
        indices[index] = count
        count += 1 + records[index][3]
    output = bytearray(data[:20 + optsz]) + bytearray(40 * len(retained))
    for section_id in retained:
        section = sections[section_id - 1][:]
        uninitialized = section[4] == 0 and section[3] > 0
        payload = b"" if uninitialized else data[section[4]:section[4] + section[3]]
        if section[0].rstrip(b"\0") == b".sxdata":
            payload = b"".join(struct.pack("<I", indices[index])
                               for index in struct.unpack("<%dI" % (len(payload) // 4), payload) if index in safe)
        relocation = bytearray()
        for i in range(section[7]):
            offset, symbol, typ = struct.unpack_from("<IIH", data, section[5] + 10 * i)
            relocation += struct.pack("<IIH", offset, indices[symbol], typ)
        section[3], section[4] = section[3] if uninitialized else len(payload), len(output) if payload else 0
        output += payload
        section[5] = len(output) if relocation else 0
        output += relocation
        section[6], section[8] = 0, 0
        struct.pack_into("<8sIIIIIIHHI", output, 20 + optsz + 40 * (section_ids[section_id] - 1), *section)
    new_symptr = len(output)
    for index in sorted(wanted):
        record, section, storage, aux = records[index]
        if section > 0:
            if section not in section_ids:
                struct.pack_into("<Ih", record, 8, 0, 0)
            else:
                struct.pack_into("<h", record, 12, section_ids[section])
        if storage == 3 and aux and section > 0:
            parent, selection = struct.unpack_from("<HB", record, 30)
            if selection == 5:
                struct.pack_into("<H", record, 30, section_ids[parent])
        elif storage == 105 and aux:
            struct.pack_into("<I", record, 18, indices[struct.unpack_from("<I", record, 18)[0]])
        output += record
    output += data[strtab:]
    struct.pack_into("<H", output, 2, len(retained))
    struct.pack_into("<II", output, 8, new_symptr, count)
    return bytes(output), names

def strip_symbols(data, keep=None, drop=()):
    """COFF rewrite for per-function swaps. Each external definition that is dropped (named in drop, or, with
    keep given, not named in keep) becomes an undefined external, so references resolve to the definition
    another object supplies; a COMDAT section keyed by it, and its associative sections, are removed. With
    keep given, static-initializer sections (.CRT$X*) are removed too: the kept object must not construct
    globals another object owns."""
    import struct
    data = bytearray(data)
    _, nsec, _, symptr, nsym, optsz, _ = struct.unpack_from("<HHIIIHH", data, 0)
    strtab = symptr + nsym * 18
    sec_at = lambda i: 20 + optsz + 40 * i  # noqa: E731
    remove, comdat_key, assoc, shared, twins, i = set(), {}, [], set(), {}, 0
    exports = keep
    while i < nsym:
        at = symptr + 18 * i
        raw, value, secnum, typ, cls, naux = struct.unpack_from("<8sIhHBB", data, at)
        if cls == 3 and naux and secnum > 0 and value == 0:  # section symbol: aux holds COMDAT selection
            number, selection = struct.unpack_from("<HB", data, at + 18 + 12)
            if selection == 5:
                assoc.append((secnum, number))
            elif struct.unpack_from("<I", data, sec_at(secnum - 1) + 36)[0] & 0x1000:
                comdat_key.setdefault(secnum, None)
                if selection != 1 and not struct.unpack_from("<I", data, sec_at(secnum - 1) + 36)[0] & 0x20:
                    shared.add(secnum)  # shared data (e.g. string literals), never unrequested inline code
        elif cls == 2 and secnum > 0:
            if raw[:4] == b"\0\0\0\0":
                start = strtab + struct.unpack_from("<I", raw, 4)[0]
                name = bytes(data[start:data.index(b"\0", start)])
            else:
                name = raw.rstrip(b"\0")
            name = name.decode("latin-1")
            if secnum in comdat_key and comdat_key[secnum] is None:
                comdat_key[secnum] = name
            if (keep is not None and name not in keep and secnum not in shared) or name in drop:
                if comdat_key.get(secnum) == name:
                    # a COMDAT section needs its key symbol: keep it, local, on the removed section, and
                    # point references at an appended undefined external of the same name
                    remove.add(secnum)
                    data[at + 16] = 3
                    twins[i] = bytes(raw) + struct.pack("<IhHBB", 0, 0, typ, 2, 0)
                else:
                    struct.pack_into("<Ih", data, at + 8, 0, 0)
        i += 1 + naux
    if keep is not None:
        for s in range(1, nsec + 1):
            section = sec_at(s - 1)
            name = bytes(data[section:section + 8])
            if name.startswith(b".CRT$X"):
                remove.add(s)
            elif name == b".drectve":
                size, start = struct.unpack_from("<II", data, section + 16)
                def retain_export(found):
                    symbol = found.group().split(b":", 1)[1].replace(b'"', b'').split(b",", 1)[0].rsplit(b"=", 1)[-1]
                    return found.group() if symbol.decode("latin-1") in exports else b" " * len(found.group())
                # Whole mining TUs can export thousands of unselected methods.
                # Those directives otherwise force unrelated bodies into the link.
                data[start:start + size] = re.sub(rb'(?i)[/-]EXPORT:(?:[^\s"]+|"[^"]*")+', retain_export,
                                                 bytes(data[start:start + size]))
    for child, parent in assoc:
        if parent in remove:
            remove.add(child)
    for s in remove:
        flags = struct.unpack_from("<I", data, sec_at(s - 1) + 36)[0]
        struct.pack_into("<I", data, sec_at(s - 1) + 36, flags | 0x800)  # IMAGE_SCN_LNK_REMOVE
    if twins:
        index = {old: nsym + n for n, old in enumerate(sorted(twins))}
        for s in range(nsec):
            relptr, nrel = struct.unpack_from("<I", data, sec_at(s) + 24)[0], struct.unpack_from("<H", data, sec_at(s) + 32)[0]
            for k in range(nrel):
                old = struct.unpack_from("<I", data, relptr + 10 * k + 4)[0]
                if old in index:
                    struct.pack_into("<I", data, relptr + 10 * k + 4, index[old])
        struct.pack_into("<I", data, 12, nsym + len(twins))
        data[strtab:strtab] = b"".join(twins[old] for old in sorted(twins))  # symbols precede the string table
    return bytes(data)


def verified_layer(client, spec, log=print, exclude=frozenset(), vdrop=frozenset(), helpers=None,
                   base_functions=frozenset()):
    """out/<Module>/verified (rebuild/2008-06/swap_build.py) as a preferred layer of kept symbols only, and the
    set of those symbols, to drop from every other object. A symbol kept by several groups is taken once.
    helpers: {symbol: obj} non-exact helpers a swapped function calls that no other object defines, kept in that one
    object (not counted, not dropped elsewhere). Missing dependencies must resolve to real implementations;
    symbol references alone cannot prove that a body is unreachable."""
    folder = workspace(client) / "out" / spec["name"] / "verified"
    if not spec.get("verified") or not (folder / "swaps.json").exists():
        return None, set()
    layer = workspace(client) / "out" / spec["name"] / "layer-verified"
    layer.mkdir(parents=True, exist_ok=True)
    for old in layer.glob("*.obj"):
        old.unlink()
    taken = set()
    items = json.loads((folder / "swaps.json").read_text())["swaps"]
    reserved = (set(helpers or {}) | set(spec.get("external_helpers", []))) - vdrop
    if spec.get("prune_unselected_sections"):
        for item in items:
            definitions = coff_externals((folder / item["obj"]).read_bytes())
            reserved.update(k for k in item["keep"] if definitions.get(k)
                            and not k.startswith(("??__E", "??__F")) and k not in exclude and k not in vdrop)
    for item in items:
        data = (folder / item["obj"]).read_bytes()
        externals = coff_externals(data)
        # Local callbacks and EH labels travel with their owner. /INCLUDE cannot
        # force them from an archive, nor can another object resolve them.
        keep = {k for k in item["keep"] if externals.get(k)
                and not k.startswith(("??__E", "??__F"))} - taken - exclude - vdrop
        extra = {h for h, o in (helpers or {}).items() if o == item["obj"]} - vdrop - set(spec.get("external_helpers", []))
        if keep or (spec.get("prune_unselected_sections") and extra):
            taken |= keep
            # Mining objects also emit unselected inline bodies. Let the module's
            # own header context supply these whenever it has a real definition.
            roots = keep | extra
            exported = roots
            if spec.get("prune_unselected_sections"):
                data, retained = _coff_subset(data, roots, external=reserved - roots)
            else:
                retained = roots
            data = strip_symbols(data, keep=retained, drop=vdrop | exclude | (base_functions - keep))
            if spec.get("prune_unselected_sections"):
                # Explicitly dropped helpers can leave orphan unwind/data records.
                data, _ = _coff_subset(data, exported, external=reserved - exported)
            (layer / ("verified_" + item["obj"])).write_bytes(data)
    log("verified layer: %d exact symbols swapped in" % len(taken))
    return layer, taken


def resolve_objects(client, test, layers, name, includes=(), max_rounds=20, log=print, extra_libs=(), defines=None,
                    drop=frozenset(), library_symbols=(), generated_objects=frozenset()):
    """layers: [dir, ...] most-preferred first (e.g. 2008-verified partial files, then complete upstream).
    Start from each file's most-preferred object; when the link reports an unresolved symbol, switch the
    file that defines it in a later layer to that layer. Returns the final link_test result plus choices."""
    out = workspace(client) / "out" / name
    files = {}
    for rank, layer in enumerate(layers):
        for obj in sorted(Path(layer).glob("*.obj")):
            if not obj.name.startswith("roc_") or obj.name in generated_objects:
                files.setdefault(obj.name, []).append((rank, obj))
    choice = {f: opts[0] for f, opts in files.items()}
    symbols = {(f, rank): defined_symbols(o) for f, opts in files.items() for rank, o in opts}
    tc = toolchain()
    for round_ in range(max_rounds):
        if out.exists():
            for old in out.glob("*.obj"):
                old.unlink()
        out.mkdir(parents=True, exist_ok=True)
        for f, (rank, obj) in choice.items():
            data = obj.read_bytes()
            (out / f).write_bytes(strip_symbols(data, drop=drop) if drop and not f.startswith("verified_") else data)
        lib_name = Path(name).name + ".lib"
        code, text = run(tc, "lib", ["/nologo", "/OUT:" + lib_name] + sorted(choice), out)
        kwargs = {"defines": defines} if defines else {}
        if library_symbols:
            kwargs["library_symbols"] = library_symbols
        result = link_test(client, test, [out / lib_name] + list(extra_libs), includes=includes, **kwargs)
        result["choices"] = {f: layers[rank] and str(Path(layers[rank]).name) for f, (rank, _) in choice.items()}
        missing = result["unresolved"]  # full list, not the truncated output
        if result["linked"] or not missing:
            return result
        switched = False
        for sym in missing:
            for f, opts in files.items():
                current = choice[f][0]
                later = next(((r, o) for r, o in opts if r > current and sym in symbols[(f, r)]), None)
                if later:
                    log("round %d: %s needs %s -> use %s from layer %d" % (round_ + 1, f, sym[:60], f, later[0]))
                    choice[f] = later
                    switched = True
                    break
        if not switched:
            log("unresolved with no later definition: " + ", ".join(m[:70] for m in missing))
            return result
    return result


def _twin(path, overlay):
    """The overlay copy a file under the overlay root would have (a non-existent path when it is outside)."""
    root, ov = overlay
    try:
        return Path(ov) / Path(path).resolve().relative_to(Path(root).resolve())
    except ValueError:
        return Path(ov) / "-outside-"


def compile_direct(client, sources, out_dir, includes, defines, flags="/O2 /GS- /EHsc /MD", cl=BUILD, append=None,
                   overlay=None, source_names=None):
    """Plain whole-file cl /c build (no mining wrapper): header search order is the ABI choice.
    append: a header included after each source, e.g. template bodies a tree declares but never defines."""
    tc = toolchain(cl)
    out = Path(out_dir).resolve()
    out.mkdir(parents=True, exist_ok=True)
    includes, compiled = _overlaid(includes, sources, overlay)
    source_names = {str(Path(p).resolve()): name for p, name in (source_names or {}).items()}
    cache_root = os.path.normcase(os.path.abspath(ROOT))
    cache_prefix = cache_root.rstrip(os.sep) + os.sep
    @functools.lru_cache(maxsize=None)
    def cache_path(path):
        name = os.path.normcase(os.path.abspath(path))
        return "." if name == cache_root else name[len(cache_prefix):] if name.startswith(cache_prefix) else name

    @functools.lru_cache(maxsize=None)
    def content(path):
        with Path(path).open("rb") as stream:
            return hashlib.file_digest(stream, "sha256").hexdigest()

    @functools.lru_cache(maxsize=None)
    def inventory_path(path):
        return os.path.normcase(path)

    inventories, inventory_walked = {}, {}
    @match._single_load
    @functools.lru_cache(maxsize=None)
    def inventory(folder):
        # New files can shadow previously resolved includes without changing them.
        folder = Path(folder)
        for parent in folder.parents:
            if parent not in inventories or folder not in inventory_walked[parent]:
                continue
            prefix = str(folder.relative_to(parent)) + os.sep
            normalized = inventory_path(prefix)
            names = {}
            for name, paths in inventories[parent].items():
                selected = [p[len(prefix):] for p in paths if inventory_path(p).startswith(normalized)]
                if selected:
                    names[name] = sorted(os.path.join('.', p) if os.sep not in p else p for p in selected)
            inventories[folder] = names
            inventory_walked[folder] = inventory_walked[parent]
            return names
        names = {}
        walked = set()
        for root, dirs, files in os.walk(folder):
            walked.add(Path(root))
            dirs[:] = [d for d in dirs if d != "_wrap"]
            prefix = os.path.relpath(root, folder)
            for name in files:
                if not name.endswith((".obj", ".deps", ".compile.json")):
                    names.setdefault(name.casefold(), []).append(os.path.join(prefix, name))
        inventories[folder] = {name: sorted(paths) for name, paths in names.items()}
        inventory_walked[folder] = walked
        return inventories[folder]

    # Shared headers recur in every object's deps: probe each overlay twin once per build.
    @functools.lru_cache(maxsize=None)
    def shadowed_dep(dep):
        return _twin(dep, overlay).exists()

    compiler_files = []
    if tc.get("cl"):
        compiler_files = sorted(p for p in Path(tc["cl"]).parent.iterdir()
                                if p.suffix.lower() in (".exe", ".dll"))
    if tc.get("mspdb"):
        compiler_files.append(Path(tc["mspdb"]))
    config = [client, cl, flags, defines, cache_path(append) if append else None,
              {k: cache_path(v) if isinstance(v, Path) else v for k, v in tc.items()},
              [(cache_path(p), content(p)) for p in compiler_files],
              [os.environ.get(k, "") for k in ("CL", "_CL_")]]

    def signature(orig, src, deps):
        files = sorted(set(([Path(orig)] if Path(orig).exists() else []) + [src]
                           + ([Path(append)] if append else []) + list(map(Path, deps))))
        dirs = [src.parent, Path(orig).parent] + list(includes) + [
            tc[k] for k in ("vc_include", "atlmfc_include", "sdk_include") if tc.get(k)]
        dirs += sorted({p.parent for p in files} - set(map(Path, dirs)))
        # Only a matching basename can shadow an include already used by this TU.
        # Unrelated generated sources must not invalidate every cached object.
        names = {p.name.casefold() for p in files}
        # Missing basenames need no repeated empty entries: any new shadowing
        # header becomes a nonempty entry and still changes the input digest.
        directory_inputs = []
        # Walk broad roots first; nested dependency directories reuse that exact
        # listing. Keep compiler include order unchanged in the serialized key.
        for folder in sorted(set(map(Path, dirs)), key=lambda p: len(p.parts)):
            inventory(folder)
        for folder in dirs:
            contents = inventory(folder)
            directory_inputs.append((cache_path(folder), [(name, contents[name]) for name in sorted(names & contents.keys())]))
        payload = [config, [(cache_path(p), content(p)) for p in files],
                   directory_inputs]
        if source_names.get(str(Path(orig).resolve())):
            payload.append(["source_name", source_names[str(Path(orig).resolve())]])
        return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()

    def compile_one(pair):
        orig, src = pair
        src = Path(src)
        obj = out / (src.stem + ".obj")
        deps_file = obj.with_suffix(".deps")
        cache_file = obj.with_suffix(".compile.json")
        command_file = obj.with_suffix(".command.json")
        if obj.exists() and deps_file.exists() and cache_file.exists() and command_file.exists() and src.suffix.lower() != ".asm":
            deps = json.loads(deps_file.read_text())
            # a header that gained an overlay twin since this object was built is shadowed now: rebuild
            shadowed = overlay and any(shadowed_dep(d) for d in deps)
            if not shadowed:
                saved = json.loads(cache_file.read_text())
                try:
                    # Hashing opens every dependency: a separate existence pass is redundant.
                    if saved == {"inputs": signature(orig, src, deps), "object": content(obj)}:
                        return str(orig), (True, "content cache hit")
                except FileNotFoundError:
                    pass  # Removed headers/objects require the ordinary compiler path.
        obj.unlink(missing_ok=True)  # a failed compile must not leave a stale object
        cache_file.unlink(missing_ok=True)
        if src.suffix.lower() == ".asm":
            code, text = run(tc, _ml(), ["/nologo", "/c", "/Fo" + str(obj), str(src)], out)
            return str(orig), (code == 0, text[-400:])
        unit = src
        source_name = source_names.get(str(Path(orig).resolve()))
        if append or source_name:
            unit = out / "_wrap" / (src.stem + ".cpp")
            unit.parent.mkdir(exist_ok=True)
            text = ('#line 1 %s\n%s\n' % (json.dumps(source_name), src.read_text()) if source_name
                    else '#include "%s"\n' % src.as_posix())
            if append:
                text += '#include "%s"\n' % Path(append).as_posix()
            unit.write_text(text, encoding="utf-8")
        # a patched copy compiles from the overlay, so its original folder must stay on the path
        # for sibling "quoted" includes (overlay twin first, as everywhere else)
        siblings = [src.parent, Path(orig).parent] if src != Path(orig) else []
        if unit != src and not siblings:
            siblings = [src.parent]
        args = ["/nologo", "/c"] + flags.split() + ["/D" + d for d in defines.split()] + \
               ["/I" + str(i) for i in siblings + list(includes)] + ["/showIncludes", "/Fo" + src.stem + ".obj", str(unit)]
        code, text = run(tc, "cl", args, out)
        included = re.findall(r"^Note: including file:\s*(.+?)\s*$", text, re.M)
        command_file.write_text(json.dumps({"compiler": str(tc.get("cl")), "args": args,
            "cwd": str(out), "source": str(src), "source_sha256": content(src),
            "source_name": source_name,
            "environment": dict({k: os.environ.get(k, "") for k in ("CL", "_CL_")},
                                INCLUDE=";".join(str(tc[k]) for k in ("vc_include", "atlmfc_include", "sdk_include") if tc.get(k))),
            "dependencies": {p: content(Path(p)) for p in sorted(set(included)) if Path(p).exists()},
            "exit": code}, indent=2))
        text = "\n".join(l for l in text.splitlines() if not l.startswith("Note: including file:"))
        if code == 0:
            deps_file.write_text(json.dumps(sorted(set(included))))
            if obj.exists():
                cache_file.write_text(json.dumps({"inputs": signature(orig, src, included),
                                                  "object": hashlib.sha256(obj.read_bytes()).hexdigest()}))
        return str(orig), (code == 0, "\n".join(l for l in text.splitlines() if " error " in l)[:2000] or text[-400:])

    import concurrent.futures
    # Objects/dependency files use source stems; colliding stems must stay serial.
    jobs = 4 if len({Path(s).stem.casefold() for s in compiled}) == len(compiled) else 1
    with concurrent.futures.ThreadPoolExecutor(max_workers=jobs) as pool:
        return dict(pool.map(compile_one, zip(sources, compiled)))


# ---------- modules: reproducible layered builds ----------

def _in_tree(path, src, tree):
    """An include dir inside the recipe tree maps to the patched copy (header patches apply too)."""
    path, src = Path(path).resolve(), Path(src).resolve()
    return tree / path.relative_to(src) if path.is_relative_to(src) else path


def patched_tree(client, recipe):
    """The recipe's source tree, with its binary-derived `patches` applied, as a cached copy under out/.
    Without patches the pristine tree is used in place."""
    import hashlib
    import shutil
    import tempfile
    from roc import libs
    r = libs.RECIPES[recipe]
    src = libs._case_path(libs.LIBS / r["src"]).resolve()
    if not r.get("patches"):
        return src
    key = hashlib.sha256(json.dumps(r["patches"], sort_keys=True).encode()).hexdigest()[:12]
    tree = workspace(client) / "out" / "trees" / ("%s-%s" % (recipe, key))
    if not tree.exists():
        tree.parent.mkdir(parents=True, exist_ok=True)
        tmp = Path(tempfile.mkdtemp(prefix=tree.name + "-", suffix=".tmp", dir=tree.parent))
        shutil.copytree(src, tmp, dirs_exist_ok=True)
        for rel, edits in r["patches"].items():
            text = (tmp / rel).read_text(errors="replace")
            for old, new in edits:
                if old not in text:
                    raise ValueError("patch for %s no longer applies: %r" % (rel, old[:60]))
                text = text.replace(old, new)
            (tmp / rel).write_text(text)
        # Windows scanners can briefly hold the freshly copied directory open.
        # Independent builders use separate temporary trees; neither deletes the
        # other's in-progress copy. Only a complete tree becomes the cache entry.
        for attempt in range(11):
            try:
                tmp.rename(tree)
                break
            except OSError as error:
                if tree.is_dir():
                    assert tmp.parent.resolve() == tree.parent.resolve()
                    shutil.rmtree(tmp, ignore_errors=True)
                    break
                if getattr(error, 'winerror', None) not in (5, 32, 33) or attempt == 10:
                    raise
                time.sleep(min(.1 * 2 ** attempt, 1))
    return tree

def build_overlay(client, module, spec):
    """Module-level source fixes without touching tools/: the files named in spec["patches"] (a JSON file of
    {rel: [[old, new], ...]}, rel under spec["root"]) are copied, edited and placed in out/<module>/overlay.
    Returns (root, overlay) for compile_direct, or None."""
    if not spec:
        return None
    import hashlib
    root = _spec_path(client, spec["root"]).resolve()
    patches = json.loads((ROOT / spec["patches"]).read_text(encoding="utf-8"))
    from roc.integration import canonical_patches
    patches = canonical_patches(patches)
    # one stable folder: a file is rewritten only when its patched text changes, so objects that do not
    # include it stay current (compile_direct tracks each object's includes)
    overlay = workspace(client) / "out" / module / "overlay"
    wanted = {}
    for rel, edits in patches.items():
        text = (root / rel).read_text(errors="replace") if (root / rel).exists() else ""
        for old, new in edits:
            if old == "@replace":  # adopt a whole header from a local unit; no vendor text in the patch file
                text = (root / new).read_text(errors="replace")
                continue
            if old.startswith("@all:"):  # every occurrence, e.g. a member that became a weak_ptr
                if old[5:] not in text:
                    raise ValueError("overlay patch for %s no longer applies: %r" % (rel, old[:60]))
                text = text.replace(old[5:], new)
                continue
            if old and old not in text:
                raise ValueError("overlay patch for %s no longer applies: %r" % (rel, old[:60]))
            text = text.replace(old, new, 1) if old else text + new
        wanted[Path(rel).as_posix()] = text
    for path in [p for p in overlay.rglob("*") if p.is_file()] if overlay.exists() else []:
        if path.relative_to(overlay).as_posix() not in wanted:
            path.unlink()  # no longer patched: dependents see it gone and rebuild
    for rel, text in wanted.items():
        target = overlay / rel
        if not target.exists() or target.read_text(errors="replace") != text:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text)
    # Retired generated units must not override live providers in another layer.
    for command in overlay.parent.glob("layer-*/*.command.json"):
        source = Path(json.loads(command.read_text()).get("source", ""))
        if source.is_relative_to(overlay) and not source.exists():
            command.with_name(command.name.removesuffix(".command.json") + ".obj").unlink(missing_ok=True)
    return root, overlay


def _overlaid(includes, sources, overlay):
    """Each include dir under the overlay root gets its overlay twin first; patched sources compile from the overlay."""
    if not overlay:
        return list(includes), list(sources)
    root, ov = overlay
    inc = []
    for i in includes:
        i = Path(i).resolve()
        if i.is_relative_to(root):
            inc.append(ov / i.relative_to(root))
        inc.append(i)
    src = []
    for original in sources:
        path = Path(original).resolve()
        if not path.is_relative_to(root):
            src.append(original)
            continue
        target = ov / path.relative_to(root)
        # Quoted includes search the source's folder before /I directories.
        # An unchanged TU beside an adopted header must compile beside its twin.
        if (not target.exists() and path.is_file() and target.parent.is_dir()
                and any(p.suffix.lower() in ('.h', '.hpp', '.inl') for p in target.parent.iterdir())):
            target.write_bytes(path.read_bytes())
        src.append(target if target.exists() else original)
    return inc, src


def _spec_path(client, value):
    """`tree:RECIPE/sub/dir` names a folder inside a recipe's (patched) tree; anything else is repo-relative."""
    if value.startswith("tree:"):
        recipe, _, rest = value[5:].partition("/")
        return patched_tree(client, recipe) / rest
    return (ROOT / value).resolve()


def load_module(client, name):
    return json.loads((ROOT / "rebuild" / client / "modules" / (name + ".json")).read_text(encoding="utf-8"))


def mfc_import_lib(client):
    """out/mfclib/mfc90.lib: the mfc90.dll import library (the 2008 exe imports mfc90.dll), made by the period lib.exe
    from the RTM MFC source's mfc90.def. Tests reference it as ../../mfclib/mfc90.lib from out/tests/<test>."""
    out = workspace(client) / "out" / "mfclib"
    if not (out / "mfc90.lib").exists():
        from roc import libs
        out.mkdir(parents=True, exist_ok=True)
        definition = libs.LIBS / "mfc-9.0-rtm" / "atlmfc" / "src" / "mfc" / "intel" / "mfc90.def"
        code, text = run(toolchain(), "lib", ["/nologo", "/MACHINE:X86", "/DEF:" + str(definition), "/NAME:mfc90.dll",
                                              "/OUT:mfc90.lib"], out)
        if code:
            raise RuntimeError("mfc90.lib: " + text[-300:])
    return out / "mfc90.lib"


def dll_exports(path):
    """Names a PE DLL exports by name (export directory, data directory 0)."""
    import struct
    data = Path(path).read_bytes()
    pe = struct.unpack_from("<I", data, 0x3c)[0]
    nsec, optsz = struct.unpack_from("<H", data, pe + 6)[0], struct.unpack_from("<H", data, pe + 20)[0]
    sections = [struct.unpack_from("<IIII", data, pe + 24 + optsz + 40 * i + 8) for i in range(nsec)]
    def at(rva):
        for vsize, va, rawsize, raw in sections:
            if va <= rva < va + max(vsize, rawsize):
                return rva - va + raw
        raise ValueError("rva %x outside sections" % rva)
    export_rva = struct.unpack_from("<I", data, pe + 24 + 96)[0]
    count, _, names = struct.unpack_from("<III", data, at(export_rva) + 24)
    starts = [at(struct.unpack_from("<I", data, at(names) + 4 * i)[0]) for i in range(count)]
    return [data[start:data.index(b"\0", start)].decode("latin-1") for start in starts]

def dll_import_lib(client, dll, source=None):
    """Build an import library from client or explicitly selected support DLL exports."""
    out = workspace(client) / "out" / "importlibs"
    path = Path(source) if source is not None else ROOT / "clients" / client / dll
    stem = Path(dll).stem
    if source is not None:
        data = path.read_bytes()
        if data[:2] != b"MZ" or struct.unpack_from("<H", data, struct.unpack_from("<I", data, 0x3c)[0] + 4)[0] != 0x14c:
            raise ValueError("support DLL must be an x86 PE: " + str(path))
        stem += "-" + hashlib.sha256(data).hexdigest()[:16]
    lib = out / (stem + ".lib")
    if not lib.exists():
        out.mkdir(parents=True, exist_ok=True)
        (out / (stem + ".def")).write_text(
            "LIBRARY %s\nEXPORTS\n" % Path(dll).name + "".join("  %s\n" % n for n in dll_exports(path)))
        code, text = run(toolchain(), "lib", ["/nologo", "/MACHINE:X86", "/DEF:" + stem + ".def",
                                              "/NAME:" + Path(dll).name, "/OUT:" + lib.name], out)
        if code:
            raise RuntimeError("%s: %s" % (lib.name, text[-300:]))
    return lib


def _module_ready(out, spec):
    """A link is usable only when all source layers compiled and its test passed."""
    try:
        report = json.loads((out / "report.json").read_text())
        return ((out / "linked" / "linked.lib").exists() and report.get("linked")
                and report.get("test_exit") == 0
                and all(not json.loads((out / ("layer-" + layer["name"]) / "errors.json").read_text())
                        for layer in spec["layers"]))
    except (OSError, ValueError, KeyError, TypeError):
        return False


def _compile_failure_report(out, name, errors, dependency_errors=None):
    """Invalidate stale ownership after a failed layer, retaining the last success."""
    report_path = out / "report.json"
    try:
        previous = json.loads(report_path.read_text())
        if previous.get("linked") and previous.get("test_exit") == 0:
            _dump(out / "report-before-compile-failure.json", previous)
            symbols = out / "owned-symbols.json"
            if symbols.exists():
                _dump(out / "owned-symbols-before-compile-failure.json", json.loads(symbols.read_text()))
    except (OSError, ValueError, AttributeError):
        pass
    report = {"module": name, "linked": False, "test_exit": None,
              "test_output": "compile or dependency errors; link skipped",
              "unresolved": [], "compile_errors": errors, "dependency_errors": dependency_errors or {}, "object_functions": 0,
              "owned_2008": 0, "owned_2008_16b": 0, "owned_addrs": [], "choices": {}}
    _dump(out / "owned-symbols.json", {})
    _dump(report_path, report)
    return report


def _link_support(client, specs, test):
    """Carry runtime and import-library requirements through dependency modules."""
    import shutil
    folder = workspace(client) / "out" / "tests" / test
    copied, libraries = {}, []

    def copy(source, name=None):
        source = Path(source)
        name = name or source.name
        digest = hashlib.sha256(source.read_bytes()).hexdigest()
        key = name.casefold()
        if key in copied:
            if copied[key] != digest:
                raise ValueError("Conflicting runtime files: " + name)
            return
        folder.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, folder / name)
        copied[key] = digest

    def add(path):
        if path not in libraries:
            libraries.append(path)

    for spec in specs:
        if spec.get("mfc_import"):
            lib = mfc_import_lib(client)
            add(lib)
            copy(lib, "mfc90.lib")
        for key in spec.get("toolchain_libs", []):
            support = toolchain().get(key)
            if support is None:
                raise RuntimeError("Missing toolchain library: " + key)
            add(support)
        for dll in spec.get("import_dlls", []):
            add(dll_import_lib(client, dll))
            copy(ROOT / "clients" / client / dll)
        for dll in spec.get("import_support_dlls", []):
            source = ROOT / dll
            add(dll_import_lib(client, source.name, source=source))
            copy(source)
        for name in spec.get("runtime_files", []):
            copy(ROOT / name)
    return libraries


def build_module(client, name, log=print):
    """Build every layer of modules/<name>.json, resolve the link, run its test, write a report."""
    from roc import libs
    spec = load_module(client, name)
    out = workspace(client) / "out" / spec["name"]
    ov = build_overlay(client, spec["name"], spec.get("overlay"))
    layer_dirs, compile_errors = [], {}
    for layer in spec["layers"]:
        folder = out / ("layer-" + layer["name"])
        if layer["mode"] == "archive":
            folder.mkdir(parents=True, exist_ok=True)
            for member in layer["files"]:
                (folder / member.replace("\\", "/").rsplit("/", 1)[-1]).write_bytes(
                    libs.archive_unit(layer["recipe"], member, layer.get("cl", BUILD)))
            errors = {}
        elif layer["mode"] == "recipe":
            libs.fetch(layer["recipe"])
            src = libs._case_path(libs.LIBS / libs.RECIPES[layer["recipe"]]["src"])
            listed = libs.RECIPES[layer["recipe"]].get("files")
            if isinstance(layer["files"], list):
                files = list(layer["files"])
            elif layer["files"] == "recipe" and isinstance(listed, list):
                files = list(listed)
            else:
                globs = (listed if layer["files"] == "recipe" else layer["files"]).split()
                files = sorted(p.relative_to(src).as_posix() for g in globs for p in src.glob(g)
                               if not p.name.startswith("roc_"))
            files = [f for f in files if f not in layer.get("exclude", [])]
            if (ov and src.resolve().is_relative_to(Path(ov[0]).resolve())
                    and not isinstance(layer["files"], list) and not isinstance(listed, list)):
                overlay_src = Path(ov[1]) / src.resolve().relative_to(Path(ov[0]).resolve())
                extra = {p.relative_to(overlay_src).as_posix() for g in globs for p in overlay_src.glob(g)
                         if not p.name.startswith('roc_')}
                files = sorted((set(files) | extra) - set(layer.get('exclude', [])))
            if not files:
                errors = {"<sources>": "No sources found for recipe " + layer["recipe"]}
                _dump(folder / "errors.json", errors)
                log("layer %s: no sources; link skipped" % layer["name"])
                return _compile_failure_report(out, spec["name"], {layer["name"]: errors})
            if layer.get("direct"):  # plain cl: /MD defines _DLL, so CRT data is imported as the linker expects
                rep = {"compile_errors": {f: "direct" for f in files}}
            else:
                rep = build_library(client, layer["recipe"], files, layer["flags"], "%s/layer-%s" % (spec["name"], layer["name"]),
                                    cl=layer.get("cl", BUILD), log=log)
            errors = rep["compile_errors"]
            if errors:  # e.g. windows.h: the mining environment has no SDK include path; the rebuild toolchain does
                recipe = libs.RECIPES[layer["recipe"]]
                tree = patched_tree(client, layer["recipe"])
                includes = [tree] + [_in_tree(libs._case_path(libs.LIBS / i), src, tree)
                                     for i in recipe.get("include", []) if i != "WINSDK"]
                includes += [(ROOT / i).resolve() for i in layer.get("extra_includes", [])]
                defines = (recipe.get("defines", "") + " " + layer.get("extra_defines", "")).strip()
                append = (ROOT / layer["append_include"]).resolve() if layer.get("append_include") else None
                flags = " ".join([layer["flags"]] + ["/FI" + h for h in recipe.get("preinclude", [])])  # recipe preludes
                source_names = {str(tree / rel): libs.source_file_name(recipe, rel) for rel in errors}
                res = compile_direct(client, [tree / rel for rel in errors], folder, includes, defines,
                                     flags, cl=layer.get("cl", BUILD), append=append, overlay=ov, source_names=source_names)
                if layer.get("fallback_cl"):  # e.g. VS2005 accepts access checks VS2008 rejects
                    res.update(compile_direct(client, [Path(k) for k, (ok, _) in res.items() if not ok], folder, includes,
                                              defines, layer["flags"], cl=layer["fallback_cl"], append=append, overlay=ov,
                                              source_names=source_names))
                errors = {Path(k).name: v for k, (ok, v) in res.items() if not ok}
        else:
            if layer.get("fetch_recipe"):
                libs.fetch(layer["fetch_recipe"])
            recipe = libs.RECIPES[layer["includes_from_recipe"]] if layer.get("includes_from_recipe") else {"include": []}
            includes = [(libs.LIBS / i).resolve() for i in recipe["include"] if i != "WINSDK"]
            includes += [(ROOT / i).resolve() for i in layer.get("extra_includes", [])]
            defines = libs.RECIPES[layer["defines_from_recipe"]]["defines"] if layer.get("defines_from_recipe") else layer.get("defines", "")
            defines = (defines + " " + layer.get("extra_defines", "")).strip()
            sources = [p for g in layer["files"].split() for p in sorted((ROOT / layer["dir"]).glob(g))
                       if not p.name.startswith("roc_") and p.name not in layer.get("exclude", [])]
            if not sources:
                errors = {"<sources>": "No sources found in " + layer["dir"]}
                _dump(folder / "errors.json", errors)
                log("layer %s: no sources; link skipped" % layer["name"])
                return _compile_failure_report(out, spec["name"], {layer["name"]: errors})
            append = (ROOT / layer["append_include"]).resolve() if layer.get("append_include") else None
            res = compile_direct(client, sources, folder, includes, defines, layer["flags"], cl=layer.get("cl", BUILD), append=append, overlay=ov)
            if layer.get("fallback_cl"):
                res.update(compile_direct(client, [Path(k) for k, (ok, _) in res.items() if not ok], folder, includes,
                                          defines, layer["flags"], cl=layer["fallback_cl"], append=append, overlay=ov))
            errors = {Path(k).name: v for k, (ok, v) in res.items() if not ok}
        _dump(folder / "errors.json", errors)
        log("layer %s: %d compile errors%s" % (layer["name"], len(errors), (" (" + ", ".join(sorted(errors)) + ")") if errors else ""))
        if errors:
            compile_errors[layer["name"]] = errors
        layer_dirs.append(folder)
    if compile_errors:
        log("module %s: compile errors; link skipped" % spec["name"])
        return _compile_failure_report(out, spec["name"], compile_errors)
    deps, pending, support_specs = [], list(spec.get("depends", [])), [spec]
    while pending:  # transitive: G3D needs zlib-winapi wherever G3D goes
        dep = pending.pop(0)
        dep_spec = load_module(client, dep)
        dep_lib = workspace(client) / "out" / dep_spec["name"] / "linked" / "linked.lib"
        if dep_lib in deps:
            continue
        dep_out = dep_lib.parent.parent
        if not _module_ready(dep_out, dep_spec):
            result = build_module(client, dep, log=log)
            if not result.get("linked") or result.get("test_exit") != 0 or not _module_ready(dep_out, dep_spec):
                log("module %s: dependency build failed: %s" % (spec["name"], dep))
                return _compile_failure_report(out, spec["name"], {}, {dep: "dependency build failed"})
        deps.append(dep_lib)
        support_specs.append(dep_spec)
        pending += dep_spec.get("depends", [])
    try:
        deps.extend(_link_support(client, support_specs, spec["test"]))
    except (OSError, ValueError, RuntimeError) as error:
        log("module %s: runtime dependency failed: %s" % (spec["name"], error))
        return _compile_failure_report(out, spec["name"], {}, {"runtime": str(error)})
    excluded_path = out / "verified" / "excluded.json"
    excluded = set(json.loads(excluded_path.read_text())) if excluded_path.exists() else set()
    vdrop_path = out / "verified" / "vdrop.json"
    vdrop = set(json.loads(vdrop_path.read_text())) if vdrop_path.exists() else set()
    helpers_path = out / "verified" / ("helpers-pruned.json" if spec.get("prune_unselected_sections") else "helpers.json")
    helpers = json.loads(helpers_path.read_text()) if helpers_path.exists() else {}
    # an inline or template body that several of the module's own objects define is shared code: swapping the 2008 copy
    # in replaces it for every caller, including ones compiled in other contexts (seen crashing M4a/M5), so only
    # file-owned functions swap in
    # Opt-in: resolve_objects selects one alternative per filename, never both layers.
    generated_objects = {Path(f).stem + ".obj" for layer in spec["layers"]
                         if isinstance(layer.get("files"), list) for f in layer["files"]}
    counts, base_functions = {}, set()
    for layer_dir in layer_dirs:
        for obj in Path(layer_dir).glob("*.obj"):
            if obj.name.startswith("roc_") and obj.name not in generated_objects:
                continue
            data = obj.read_bytes()
            externals = coff_externals(data)
            if spec.get("prefer_module_helpers"):
                base_functions.update(sym for sym, _, _ in match.coff_functions(data) if externals.get(sym))
            if spec.get("prefer_module_data"):
                base_functions.update(sym for sym, defined in externals.items() if defined)
            for sym, defined in externals.items():
                if defined:
                    counts.setdefault(sym, set()).add(
                        obj.name if spec.get("deduplicate_layer_files") else str(obj))
    shared = {sym for sym, providers in counts.items() if len(providers) > 1}
    force_owned = set()
    force_seen = set()
    force_context = None
    while True:  # keep required helpers, or swap incompatible callers back out
        verified, drop = verified_layer(client, spec, log=log, exclude=excluded | shared, vdrop=vdrop, helpers=helpers,
                                       base_functions=base_functions)
        if spec.get("force_verified") or spec.get("force_owned"):
            (out / "force").mkdir(exist_ok=True)
            (out / "force" / "force_verified.h").write_text(
                "".join('#pragma comment(linker, "/INCLUDE:%s")\n' % s for s in
                        sorted(force_owned | (drop if spec.get("force_verified") else set()))))
        result = resolve_objects(client, spec["test"], ([verified] if verified else []) + layer_dirs, spec["name"] + "/linked",
                                 includes=_overlaid([_spec_path(client, i) for i in spec.get("test_includes", [])], [], ov)[0], log=log,
                                 extra_libs=deps, defines=spec.get("test_defines"), drop=drop,
                                 library_symbols=drop & set(spec.get("test_library_symbols", [])),
                                 generated_objects=generated_objects)
        if spec.get("force_owned") and result["linked"]:
            if force_context is None:
                force_context = _ownership_context(client)
            selected = _forced_owned_symbols(client, out / "linked", out / "ownership-cache", force_context)
            if selected != force_owned:
                fingerprint = frozenset(selected)
                if fingerprint in force_seen or len(force_seen) >= 8:
                    raise ValueError("force_owned provider selection did not stabilize")
                force_seen.add(fingerprint)
                force_owned = selected
                log("force_owned: forcing %d selected symbols and relinking" % len(selected))
                continue
            mapped = {fields[1] for line in Path(result["map"]).read_text(errors="replace").splitlines()
                      if len(fields := line.split()) >= 2}
            missing = force_owned - mapped
            if missing:
                raise ValueError("force_owned symbols absent from link map: " + ", ".join(sorted(missing)[:8]))
        if verified and not result["linked"] and result["unresolved"]:
            # a missing helper defined by one of the verified objects themselves: keep it there
            missing, added = set(result["unresolved"]) - set(helpers) - vdrop, 0
            for obj in sorted((out / "verified").glob("*.obj")):
                for name, defined in coff_externals(obj.read_bytes()).items():
                    if defined and name in missing and name not in helpers:
                        helpers[name] = obj.name
                        added += 1
            if added:
                _dump(helpers_path, helpers)
                log("verified: keeping %d helpers the swapped functions call" % added)
                force_owned.clear()
                force_seen.clear()
                continue
        back = set(result.get("referencers", [])) & drop
        if not back and verified and result["unresolved"]:
            # Indirect calls and retained bodies can reach these dependencies: remove the whole incompatible object.
            missing = set(result["unresolved"])
            for obj in verified.glob("*.obj"):
                ext = coff_externals(obj.read_bytes())
                if any(not ext[m] for m in missing if m in ext):
                    back |= {k for k, d in ext.items() if d} & drop
        dupes = set(result.get("duplicates", [])) - vdrop
        if verified and dupes and not result["linked"]:
            # a verified inline copy against a regular definition elsewhere, or CRT members MSVCP90 exports
            vdrop |= dupes
            _dump(vdrop_path, sorted(vdrop))
            log("verified: %d duplicate definitions; undefined in verified objects" % len(dupes))
            force_owned.clear()
            force_seen.clear()
            continue
        if result["linked"] or not back:
            break
        excluded |= back
        _dump(excluded_path, sorted(excluded))
        force_owned.clear()
        force_seen.clear()
        if spec.get("prune_unselected_sections") and helpers:
            # Removing callers invalidates their helper closure. Rediscover only
            # dependencies of the remaining roots instead of retaining orphans.
            helpers = {}
            _dump(helpers_path, helpers)
        log("verified: %d swapped functions need helpers nothing else defines; swapping them back out" % len(back))
    linked = out / "linked"
    funcs, owned_addrs, owned16_addrs = 0, set(), set()
    owned_symbols = {}
    context = None
    cached = checked = 0
    for obj in sorted(linked.glob("*.obj")):
        if context is None:
            context = _ownership_context(client)
        rows, hit = _ownership_rows(client, obj, out / "ownership-cache" / (obj.name + ".json"), context)
        cached += hit
        checked += not hit
        funcs += len(rows)
        for symbol, _, addresses in rows:
            if len(addresses)==1:
                owned_symbols.setdefault(addresses[0],[]).append(dict(symbol=symbol,object=obj.name))
        owned_addrs.update(h[0] for _, _, h in rows if len(h) == 1)  # COMDAT copies repeat across objects
        owned16_addrs.update(h[0] for _, s, h in rows if len(h) == 1 and s >= 16)
    owned, owned16 = len(owned_addrs), len(owned16_addrs)
    log("ownership proofs: %d cached objects, %d checked" % (cached, checked))
    report = {"module": spec["name"], "linked": result["linked"], "test_exit": result["exit"], "test_output": result["output"][-500:],
              "unresolved": result["unresolved"], "object_functions": funcs, "owned_2008": owned, "owned_2008_16b": owned16,
              "choices": result.get("choices"), "owned_addrs": sorted(owned_addrs), "owned_symbols_file": "owned-symbols.json"}
    _dump(out / "owned-symbols.json", owned_symbols)
    _dump(out / "report.json", report)
    log("%s: linked=%s test_exit=%s; %d object functions, %d byte-identical to unique 2008 functions (%d of >=16 bytes)"
        % (spec["name"], result["linked"], result["exit"], funcs, owned, owned16))
    try:
        progress(client, notify=True, log=log)
    except Exception as error:  # progress is reporting only; never fail a build
        log("rebuild progress update failed: %s" % error)
    return report


# Phase 8 runtime milestones: each is a real test exe linked with a rebuilt module (and its deps)
MILESTONES = {"M2": ("m2_window", "rbxgs-app"), "M4a": ("m4_datamodel", "rbxgs-app"), "M5": ("m5_place", "rbxgs-app"), "M4b": ("m4_render", "rbxgs-app")}


def milestones(client, log=print):
    """Build and run each milestone test; writes out/milestones.json ({id: {passed, exit, output}})."""
    results = {}
    for mid, (test, module) in sorted(MILESTONES.items()):
        spec = load_module(client, module)
        libs, pending = [workspace(client) / "out" / spec["name"] / "linked" / "linked.lib"], list(spec.get("depends", []))
        while pending:
            dep_spec = load_module(client, pending.pop(0))
            lib = workspace(client) / "out" / dep_spec["name"] / "linked" / "linked.lib"
            if lib not in libs:
                libs.append(lib)
                pending += dep_spec.get("depends", [])
        ov = build_overlay(client, spec["name"], spec.get("overlay"))
        kwargs = {"defines": spec["test_defines"]} if spec.get("test_defines") else {}
        result = link_test(client, test, libs,
                           includes=_overlaid([_spec_path(client, i) for i in spec.get("test_includes", [])], [], ov)[0], **kwargs)
        results[mid] = {"test": test, "module": module, "passed": bool(result["linked"] and result["exit"] == 0),
                        "linked": result["linked"], "exit": result["exit"], "output": result["output"][-300:], "unresolved": result["unresolved"]}
        log("%s %s: linked=%s exit=%s" % (mid, test, result["linked"], result["exit"]))
    _dump(workspace(client) / "out" / "milestones.json", results)
    return results


def closure(client, name, log=print):
    """Link every object the module chose (not just what its test pulls in) plus its deps: the full list of
    symbols the module still lacks. Writes out/<module>/closure.json."""
    spec = load_module(client, name)
    out = workspace(client) / "out" / spec["name"]
    objs = sorted((out / "linked").glob("*.obj"))
    deps, pending = [], list(spec.get("depends", []))
    while pending:
        dep_spec = load_module(client, pending.pop(0))
        lib = workspace(client) / "out" / dep_spec["name"] / "linked" / "linked.lib"
        if lib not in deps:
            deps.append(lib)
            pending += dep_spec.get("depends", [])
    kwargs = {"defines": spec["test_defines"]} if spec.get("test_defines") else {}
    ov = build_overlay(client, spec["name"], spec.get("overlay"))
    result = link_test(client, spec["test"], objs + deps,
                       includes=_overlaid([_spec_path(client, i) for i in spec.get("test_includes", [])], [], ov)[0], **kwargs)
    _dump(out / "closure.json", {"module": spec["name"], "objects": len(objs), "linked": result["linked"],
                                 "unresolved": result["unresolved"]})
    log("%s closure: %d objects, linked=%s, %d unresolved symbols" % (spec["name"], len(objs), result["linked"], len(result["unresolved"])))
    missing = set(result["unresolved"])
    blamed = [o for o in objs if o.name.startswith("verified_") and missing & {k for k, d in coff_externals(o.read_bytes()).items() if not d}]
    if blamed:  # dead code in a verified object names it: swap that object out on the next module build
        excluded_path = out / "verified" / "excluded.json"
        excluded = set(json.loads(excluded_path.read_text())) if excluded_path.exists() else set()
        swaps = {"verified_" + item["obj"]: item["keep"] for item in json.loads((out / "verified" / "swaps.json").read_text())["swaps"]}
        for o in blamed:
            excluded |= set(swaps.get(o.name, ()))
        _dump(excluded_path, sorted(excluded))
        log("closure: %d verified objects need these; excluded, rebuild the module" % len(blamed))
    if result.get("duplicates") and (out / "verified" / "swaps.json").exists():
        vdrop_path = out / "verified" / "vdrop.json"
        vdrop = set(json.loads(vdrop_path.read_text())) if vdrop_path.exists() else set()
        _dump(vdrop_path, sorted(vdrop | set(result["duplicates"])))
        log("closure: %d duplicate definitions; undefined in verified objects, rebuild the module" % len(result["duplicates"]))
    try:
        progress(client, notify=True, log=log)
    except Exception as error:
        log("rebuild progress update failed: %s" % error)
    return result


def _placed_object(client, data):
    """Originally ambiguous bodies with complete data and unique object-level proofs."""
    candidates = {name: match.coff_data_refs(data, name)
                  for name, size, addresses in pair(client, match.coff_functions(data))
                  if size >= 16 and 2 <= len(addresses) <= 64}
    candidates = {name: refs for name, refs in candidates.items() if refs}
    if not candidates:
        return []
    hits = set()
    for name, _, addresses in pair_object(client, data, candidates):
        if len(addresses) != 1:
            continue
        address = addresses[0]
        code, _, _ = match.target(client, address)
        checked, bad = match.data_check(client, address, code, candidates[name])
        if not bad and len(checked) == len(candidates[name]):
            hits.add(address)
    return sorted(hits)


def placed(client="2008-06", log=print):
    """2008 addresses an address-ambiguous body (byte-identical, relocations masked, to several 2008 functions;
    >= 16 bytes, at most 64 candidates) reproduces at exactly one place: the one candidate whose referenced data
    (string literals, constants the body points to) completely matches the exe, with local callees
    refined by pair_object. Cached per object and target/matcher context in
    out/<Module>/placed.json; writes out/placed.json {address: module}. Slow the first time (minutes per module)."""
    context = None
    found = {}
    for spec_path in sorted((ROOT / "rebuild" / client / "modules").glob("*.json")):
        spec = json.loads(spec_path.read_text(encoding="utf-8"))
        out = workspace(client) / "out" / spec["name"]
        report = out / "report.json"
        if not report.exists() or not _module_ready(out, spec):
            continue
        if any(obj.stat().st_mtime_ns > report.stat().st_mtime_ns for obj in (out / "linked").glob("*.obj")):
            log("%s: build newer than link report; placement deferred" % spec["name"])
            continue
        cache_path = out / "placed.json"
        cache = json.loads(cache_path.read_text()) if cache_path.exists() else {}
        fresh = {}
        for obj in sorted((out / "linked").glob("*.obj")):
            if context is None:
                context = _ownership_context(client)
            data = obj.read_bytes()
            key = hashlib.sha256(b"placed-complete-object-v3\0" + context.encode() + data).hexdigest()
            if key not in cache:
                cache[key] = _placed_object(client, data)
            fresh[key] = cache[key]
            for a in cache[key]:
                found.setdefault(a, spec["name"])
        _dump(cache_path, fresh)
        log("%s: %d placed by complete data/local callee proofs" % (spec["name"], len({a for v in fresh.values() for a in v})))
    _dump(workspace(client) / "out" / "placed.json", found)
    log("placed by complete data/local callee proofs: %d addresses" % len(found))
    return found


def status(client="2008-06", log=print):
    """One line per built module from out/<module>/report.json, plus totals (no double counting of addresses)."""
    owned_all, shared_all, compiled_all = set(), set(), set()
    rows, ready_modules = [], set()
    for spec_path in sorted((ROOT / "rebuild" / client / "modules").glob("*.json")):
        spec = json.loads(spec_path.read_text(encoding="utf-8"))
        report_path = workspace(client) / "out" / spec["name"] / "report.json"
        if not report_path.exists():
            rows.append((spec_path.stem, "not built", "", "", ""))
            continue
        r = json.loads(report_path.read_text(encoding="utf-8"))
        compiled_all.update(r.get("owned_addrs", []))
        module_out = workspace(client) / "out" / spec["name"]
        ready = _module_ready(module_out, spec)
        if ready:
            ready_modules.add(spec["name"])
        linked = module_out / "linked"
        for obj in linked.glob("*.obj") if ready else ():
            for _, size, h in pair(client, match.coff_functions(obj.read_bytes())):
                if len(h) == 1:
                    owned_all.update(h)
                elif size >= 16:  # identical 2008 functions (e.g. template copies): reproduced, address ambiguous
                    shared_all.update(h)
        rows.append((spec_path.stem, "linked" if ready else "INCOMPLETE",
                     "test ok" if r.get("test_exit") == 0 else "test %s" % r.get("test_exit"),
                     r["object_functions"], r["owned_2008"] if ready else 0))
    for name, state, test, funcs, owned in rows:
        log("%-12s %-9s %-8s %6s object functions  %5s owned 2008" % (name, state, test, funcs, owned))
    log("distinct 2008 functions reproduced by linked rebuilt code: %d" % len(owned_all))
    log("cached compiled unique across all module reports (includes failed links): %d; %d absent from linked set"
        % (len(compiled_all), len(compiled_all - owned_all)))
    log("linked per-kind counts: %s" % dict(collections.Counter(
        match._functions(client)[a].get('kind', 'code') for a in owned_all)))
    from roc.rebuild_audit import cached_review
    review = cached_review(client)
    if review and set(review['linked_addrs']) == owned_all:
        log("additional parent-paired compiler pieces, byte/data checked: %s (separate from source-code total)"
            % review['paired_piece_counts'])
    else:
        log("compiler-piece review absent or stale: run roc rebuild %s review after builds finish" % client)
    placed_path = workspace(client) / "out" / "placed.json"
    if placed_path.exists():  # `roc rebuild <client> placed` (slow; cached)
        extra = {address for address, module in json.loads(placed_path.read_text()).items()
                 if module in ready_modules} - owned_all
        log("plus %d placed at one 2008 address by their referenced data (as of the last `placed` run)" % len(extra))
    log("plus %d (>= 16 bytes) whose bytes the rebuild reproduces but that have byte-identical twins in 2008 (address ambiguous)"
        % len(shared_all - owned_all))
    try:
        progress(client, notify=True, log=log)
    except Exception as error:
        log("rebuild progress update failed: %s" % error)
    return rows, owned_all

import json
import hashlib
import time

def progress(client="2008-06", log=print, notify=True):
    """Summarize rebuild module reports into docs/rebuild-progress.json."""
    if os.environ.get('ROC_INTEGRATOR_PRIVATE') == '1':
        return None  # private builds retain module receipts, not public site aggregates
    module_dir = ROOT / "rebuild" / client / "modules"
    out_dir = workspace(client) / "out"
    specs = sorted(module_dir.glob("*.json"))
    modules = []
    distinct = set()
    linked_count = 0
    unresolved_count = 0
    for spec_path in specs:
        spec = json.loads(spec_path.read_text(encoding="utf-8"))
        report_path = out_dir / spec["name"] / "report.json"
        if not report_path.exists():
            continue
        report = json.loads(report_path.read_text(encoding="utf-8"))
        linked = bool(_module_ready(out_dir / spec["name"], spec))
        if linked:
            linked_count += 1
            linked_dir = out_dir / spec["name"] / "linked"
            for obj in linked_dir.glob("*.obj"):
                rows = pair(client, match.coff_functions(obj.read_bytes()))
                distinct.update(h[0] for _, _, h in rows if len(h) == 1)
        unresolved = report.get("unresolved") or []
        unresolved_count += len(unresolved)
        modules.append({
            "name": spec["name"],
            "linked": linked,
            "test": report.get("test_exit"),
            "exact": report.get("owned_2008", 0) if linked else 0,
            "objectFunctions": report.get("object_functions", 0),
            "unresolved": len(unresolved),
        })

    total_specs = len(specs)
    reporting = len(modules)
    total_functions = 0
    functions_file = ROOT / "work" / client / "functions.jsonl"
    if functions_file.exists():
        total_functions = sum(1 for _ in functions_file.read_text(encoding="utf-8").splitlines() if _.strip())
    if not total_functions:
        total_functions = 22291

    if not modules:
        phase = "0"
        phase_label = "Not started"
    elif linked_count == 0:
        phase = "3"
        phase_label = "First linked unit"
    elif unresolved_count > 0:
        phase = "6"
        phase_label = "Link closure"
    elif any(m["test"] not in (0, None) for m in modules):
        phase = "4"
        phase_label = "Module tests"
    else:
        phase = "8"
        phase_label = "Runtime"
    # stubs: glue bodies tagged // STUB (empty or placeholder behaviour); M1 = every module linked with tests passing
    stub_count = sum(p.read_text(errors="replace").count("// STUB") for p in (workspace(client) / "glue").rglob("*.cpp"))
    milestones = 1 if modules and all(m["linked"] and m["test"] == 0 for m in modules) else 0
    ran = workspace(client) / "out" / "milestones.json"
    if milestones and ran.exists():
        milestones += sum(1 for k, r in json.loads(ran.read_text()).items() if r.get("passed") and k[1:].isdigit())  # M4a is half of M4

    data = {
        "phase": phase,
        "phaseLabel": phase_label,
        "overall": round(len(distinct) / total_functions, 4) if total_functions else 0.0,
        "bars": {
            "compiled": {"value": reporting, "total": total_specs or 1, "label": "Modules reporting"},
            "linked": {"value": linked_count, "total": reporting or 1, "label": "Modules linked"},
            "exact": {"value": len(distinct), "total": total_functions, "label": "Byte-exact functions"},
            "unresolved": {"value": unresolved_count, "total": max(unresolved_count, 1), "label": "Unresolved symbols", "invert": True},
            "stubs": {"value": stub_count, "total": max(stub_count, 1), "label": "Temporary stubs", "invert": True},
            "runtime": {"value": milestones, "total": 7, "label": "Runtime milestones"},
        },
        "modules": modules,
        "next": "Run roc rebuild %s status for details" % client,
    }

    path = DOCS / "rebuild-progress.json"
    existing = {}
    if path.exists():
        try:
            existing = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            existing = {}
    existing.setdefault("updated", "")
    existing.setdefault("clients", {})
    existing["clients"][client] = data
    existing["updated"] = time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime())
    path.write_text(json.dumps(existing, indent=2) + "\n", encoding="utf-8")
    log("rebuild progress written: %s" % path)

    return data

